CREATE OR REPLACE FUNCTION api_app_v1.complete_profile(p_role text, p_display_name text, p_birthdate date, p_terms_agreed boolean, p_marketing_agreed boolean DEFAULT false, p_grade_level text DEFAULT NULL::text, p_university_name text DEFAULT NULL::text, p_department_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_role text := lower(btrim(coalesce(p_role, '')));
  v_name text := btrim(coalesce(p_display_name, ''));
  v_grade text := nullif(btrim(coalesce(p_grade_level, '')), '');
  v_univ text := nullif(btrim(coalesce(p_university_name, '')), '');
  v_dept text := nullif(btrim(coalesce(p_department_name, '')), '');
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_row public.users%rowtype;
  v_norm text;
  v_minor boolean;
  v_next text;
  v_completed_at timestamptz;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'AUTH_REQUIRED');
  end if;

  select * into v_row from public.users u where u.id = v_uid for update;
  if not found then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'USER_NOT_FOUND');
  end if;
  if v_row.profile_completed_at is not null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ALREADY_COMPLETED', 'role', v_row.role, 'profile_completed_at', v_row.profile_completed_at);
  end if;

  -- 계정 게이트(core_private.user_profile_update_self_impl 과 같은 판정)
  v_norm := lower(btrim(coalesce(v_row.status, '')));
  if v_norm = 'banned' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_BANNED');
  end if;
  if v_norm = 'suspended' and (v_row.suspended_until is null or v_row.suspended_until > now()) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_SUSPENDED');
  end if;
  if v_norm not in ('active', 'suspended') then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_NOT_ACTIVE');
  end if;
  if public.account_deletion_write_blocked(v_uid) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_DELETION_IN_PROGRESS');
  end if;

  -- 입력 검증
  if v_role not in ('student', 'mentor') then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROLE_INVALID');
  end if;
  if v_name = '' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'DISPLAY_NAME_REQUIRED');
  end if;
  if char_length(v_name) > 30 then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'DISPLAY_NAME_TOO_LONG', 'max_length', 30);
  end if;
  if p_birthdate is null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'BIRTHDATE_REQUIRED');
  end if;
  if p_birthdate > v_today or p_birthdate < date '1900-01-01' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'BIRTHDATE_INVALID');
  end if;
  if not coalesce(p_terms_agreed, false) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'TERMS_REQUIRED');
  end if;
  if v_role = 'student' then
    if v_grade is null then
      return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'GRADE_REQUIRED');
    end if;
    if char_length(v_grade) > 20 then
      return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'GRADE_LEVEL_TOO_LONG', 'max_length', 20);
    end if;
  else
    if v_univ is null then
      return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'UNIVERSITY_REQUIRED');
    end if;
  end if;

  -- 만 14세 판정(187 과 같은 식 · KST 달력)
  v_minor := v_today < (p_birthdate + interval '14 years')::date;
  v_completed_at := now();

  -- 이메일 가입 트리거와 같은 결과(공유 impl): 역할·표시명(nickname)·생년월일·학년·약관(users 컬럼)·완성 시각 · 멘토면 프로필 행 + 로그
  perform core_private.user_signup_provision_impl(
    v_uid, v_role, v_row.email,
    null, v_name,
    case when v_role = 'student' then v_grade else null end, null, p_birthdate,
    true, true, coalesce(p_marketing_agreed, false),
    case when v_role = 'mentor' then v_univ else null end,
    case when v_role = 'mentor' then v_dept else null end,
    null, null, null,
    v_completed_at,
    jsonb_build_object(                      -- 동의 원장 입력(187 메타 키 · 이메일 가입과 같은 행이 남는다)
      'app_role', v_role,
      'birth_date', p_birthdate::text,
      'is_minor', v_minor::text,
      'terms_agreed', 'true',
      'privacy_agreed', 'true',
      'marketing_agreed', case when coalesce(p_marketing_agreed, false) then 'true' else 'false' end
    ));

  v_next := case when v_minor then 'guardian_consent'
                 when v_role = 'mentor' then 'identity_verification'
                 else 'home' end;

  return jsonb_build_object(
    'ok', true, 'contract_version', 1,
    'role', v_role, 'is_minor', v_minor, 'next', v_next,
    'nickname', v_name, 'profile_completed_at', v_completed_at
  );
end
$function$

CREATE OR REPLACE FUNCTION api_app_v1.create_individual_question_as_student_v2(p_question_type text, p_title text, p_body text, p_amount_cents integer DEFAULT NULL::integer, p_designated_mentor_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_subject text DEFAULT NULL::text)
 RETURNS SETOF individual_questions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_type text := lower(btrim(coalesce(p_question_type, '')));
  v_idem text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_subject text := nullif(btrim(coalesce(p_subject, '')), '');
  v_blocked text;
  v_price int;
  v_res public.individual_question_escrow_result;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  -- 207(DB-5 후속 b): 정지·차단·탈퇴 진행 중 계정은 등록 불가 — 앱 entry_guard/웹 assertAccountActive 와 같은 집합
  v_blocked := core_private.account_blocked_state(v_uid);
  if v_blocked is not null then
    raise exception 'ACCOUNT_BLOCKED' using errcode = 'P0001', detail = v_blocked;
  end if;

  if v_type not in ('direct', 'open') then
    raise exception 'INVALID_INPUT: question_type must be direct or open' using errcode = '22023';
  end if;

  if char_length(btrim(coalesce(p_title, ''))) = 0 or char_length(btrim(coalesce(p_body, ''))) = 0 then
    raise exception 'INVALID_INPUT: title and body are required' using errcode = '22023';
  end if;

  -- 과목: 코드 정본(subjects.code) 실존 값만 · 공개형은 필수(멘토 라우팅 전제) · 지정형은 선택
  if v_subject is not null and not exists (select 1 from public.subjects s where s.code = v_subject) then
    raise exception 'INVALID_SUBJECT' using errcode = '22023';
  end if;
  if v_type = 'open' and v_subject is null then
    raise exception 'SUBJECT_REQUIRED' using errcode = '22023';
  end if;

  -- 가격 결정(v1 동일): open 은 앱이 보낸 금액, direct 는 멘토 가격표에서 조회 — 임의 계산 없음
  if v_type = 'direct' then
    if p_designated_mentor_id is null then
      raise exception 'INVALID_INPUT: designated_mentor_id is required for direct' using errcode = '22023';
    end if;
    select mp.amount_cents into v_price from public.mentor_individual_question_pricing mp where mp.mentor_id = p_designated_mentor_id;
    if v_price is null then
      raise exception 'MENTOR_PRICE_NOT_SET' using errcode = 'P0001';
    end if;
  else
    v_price := p_amount_cents;
    if v_price is null or v_price <= 0 then
      raise exception 'INVALID_INPUT: amount_cents must be positive for open' using errcode = '22023';
    end if;
  end if;

  -- 멱등성 키: 앱이 안 보내면 랜덤 생성(코어 NOT NULL 충족용 — v1 동일)
  if v_idem is null then
    v_idem := 'iqc:' || gen_random_uuid()::text;
  end if;

  -- 코어 v2(service_role 전용)에 위임 — 자격 파라미터는 v1 과 같이 NULL
  v_res := public.create_individual_question_with_hold_v2(
    v_uid, v_type, p_designated_mentor_id, v_subject, null, p_title, p_body, v_price, v_idem, null, null);

  if not v_res.ok then
    raise exception 'INDIVIDUAL_QUESTION_CREATE_FAILED:%:%', v_res.code, v_res.message using errcode = 'P0001';
  end if;

  return query select q.* from public.individual_questions q where q.id = v_res.question_id;
end
$function$

CREATE OR REPLACE FUNCTION api_app_v1.create_individual_question_as_student_v3(p_question_type text, p_title text, p_body text, p_amount_cents integer DEFAULT NULL::integer, p_designated_mentor_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_subject text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_required_school_tier text DEFAULT NULL::text, p_required_major_category text DEFAULT NULL::text)
 RETURNS SETOF individual_questions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_type text := lower(btrim(coalesce(p_question_type, '')));
  v_idem text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_subject text := nullif(btrim(coalesce(p_subject, '')), '');
  v_topic text := nullif(btrim(coalesce(p_topic, '')), '');
  v_tier text := nullif(btrim(coalesce(p_required_school_tier, '')), '');
  v_major text := nullif(btrim(coalesce(p_required_major_category, '')), '');
  v_blocked text;
  v_price int;
  v_res public.individual_question_escrow_result;
begin
  -- ── 이하 v2(204 + 207 D-1) 본문 복제 — 권한·계정·상태·과목·가격·키 검사 동일 ──
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  -- 207(DB-5 후속 b): 정지·차단·탈퇴 진행 중 계정은 등록 불가 — v2 와 같은 판정 함수
  v_blocked := core_private.account_blocked_state(v_uid);
  if v_blocked is not null then
    raise exception 'ACCOUNT_BLOCKED' using errcode = 'P0001', detail = v_blocked;
  end if;

  if v_type not in ('direct', 'open') then
    raise exception 'INVALID_INPUT: question_type must be direct or open' using errcode = '22023';
  end if;

  if char_length(btrim(coalesce(p_title, ''))) = 0 or char_length(btrim(coalesce(p_body, ''))) = 0 then
    raise exception 'INVALID_INPUT: title and body are required' using errcode = '22023';
  end if;

  -- 과목: 코드 정본(subjects.code) 실존 값만 · 공개형은 필수(멘토 라우팅 전제) · 지정형은 선택
  if v_subject is not null and not exists (select 1 from public.subjects s where s.code = v_subject) then
    raise exception 'INVALID_SUBJECT' using errcode = '22023';
  end if;
  if v_type = 'open' and v_subject is null then
    raise exception 'SUBJECT_REQUIRED' using errcode = '22023';
  end if;

  -- 가격 결정(v1 동일): open 은 앱이 보낸 금액, direct 는 멘토 가격표에서 조회 — 임의 계산 없음
  if v_type = 'direct' then
    if p_designated_mentor_id is null then
      raise exception 'INVALID_INPUT: designated_mentor_id is required for direct' using errcode = '22023';
    end if;
    select mp.amount_cents into v_price from public.mentor_individual_question_pricing mp where mp.mentor_id = p_designated_mentor_id;
    if v_price is null then
      raise exception 'MENTOR_PRICE_NOT_SET' using errcode = 'P0001';
    end if;
  else
    v_price := p_amount_cents;
    if v_price is null or v_price <= 0 then
      raise exception 'INVALID_INPUT: amount_cents must be positive for open' using errcode = '22023';
    end if;
  end if;

  -- 멱등성 키: 앱이 안 보내면 랜덤 생성(코어 NOT NULL 충족용 — v1 동일)
  if v_idem is null then
    v_idem := 'iqc:' || gen_random_uuid()::text;
  end if;
  -- ── v2 복제 끝 ──

  -- v3 추가 ①: 단원·개념 — 자유 텍스트(웹 지정형·공개형 모두 허용) · 200자 상한
  if v_topic is not null and char_length(v_topic) > 200 then
    raise exception 'TOPIC_TOO_LONG' using errcode = '22023';
  end if;

  -- v3 추가 ②: 자격 조건 — 공개형만. 지정형은 멘토가 이미 정해졌으므로 무시(NULL)
  if v_type <> 'open' then
    v_tier := null;
    v_major := null;
  else
    if v_tier is not null and (
         v_tier = '미분류'
      or not exists (select 1 from public.school_tier_catalog c where c.code = v_tier and c.is_active)
      or v_tier not in ('서연고', '서성한', '중경외시', '건동홍', '그외')
    ) then
      raise exception 'INVALID_TIER' using errcode = '22023';
    end if;
    if v_major is not null and (
         not exists (select 1 from public.major_category_catalog c where c.code = v_major and c.is_active)
      or v_major not in ('메디컬', '교육', '인문', '사회상경', '자연', '공학', '예체능', '기타')
    ) then
      raise exception 'INVALID_MAJOR' using errcode = '22023';
    end if;
  end if;

  -- 코어 v2(service_role 전용)에 위임 — v2 와 같은 호출에 topic·자격 3인자만 채운다
  v_res := public.create_individual_question_with_hold_v2(
    v_uid, v_type, p_designated_mentor_id, v_subject, v_topic, p_title, p_body, v_price, v_idem, v_tier, v_major);

  if not v_res.ok then
    raise exception 'INDIVIDUAL_QUESTION_CREATE_FAILED:%:%', v_res.code, v_res.message using errcode = 'P0001';
  end if;

  return query select q.* from public.individual_questions q where q.id = v_res.question_id;
end
$function$

CREATE OR REPLACE FUNCTION api_app_v1.ensure_free_question_room(p_mentor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := (SELECT auth.uid());
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'AUTH_REQUIRED');
  END IF;
  IF p_mentor_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'MENTOR_NOT_FOUND');
  END IF;
  RETURN core_private.ensure_student_mentor_room(v_uid, p_mentor_id, NULL, NULL, true)
         || jsonb_build_object('contract_version', 1);
END $function$

CREATE OR REPLACE FUNCTION api_app_v1.mentor_activity_set(p_status text, p_pause_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_termination_effective_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT 'rest'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_uid uuid:=(SELECT auth.uid());
 v_role text; v_status text; v_susp timestamptz; v_norm text;
 v_target text:=lower(btrim(coalesce(p_status,'')));
 v_reason text:=lower(btrim(coalesce(p_reason,'rest')));
 v_result jsonb; v_summary jsonb; v_code text; v_state text;
BEGIN
  if v_uid is null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'AUTH_REQUIRED');
  end if;
  select u.role, u.status, u.suspended_until into v_role, v_status, v_susp from public.users u where u.id = v_uid;
  if not found or v_role is distinct from 'mentor' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROLE_NOT_MENTOR');
  end if;
  v_norm := lower(btrim(coalesce(v_status, '')));
  if v_norm = 'banned' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_BANNED');
  end if;
  if v_norm = 'suspended' and (v_susp is null or v_susp > now()) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_SUSPENDED');
  end if;
  if v_norm not in ('active', 'suspended') then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_NOT_ACTIVE');
  end if;
  if public.account_deletion_write_blocked(v_uid) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_DELETION_IN_PROGRESS');
  end if;
  if v_target not in ('active', 'paused', 'terminating') then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACTIVITY_STATUS_INVALID');
  end if;


 IF v_target='paused' AND p_pause_until IS NULL THEN
  RETURN jsonb_build_object('ok',false,'contract_version',1,'code','PAUSE_UNTIL_REQUIRED');
 END IF;
 v_result:=core_private.mentor_financial_transition_impl(v_uid,
  CASE v_target WHEN 'paused' THEN 'pause' WHEN 'active' THEN 'resume' ELSE 'termination_start' END,
  NULL,CASE WHEN v_target='paused' THEN v_reason ELSE NULL END,p_pause_until,p_termination_effective_at);
 IF NOT coalesce((v_result->>'ok')::boolean,false) THEN
  v_code:=v_result->>'code';
  IF v_code IN ('MENTOR_NOT_PAUSED','MENTOR_NOT_ACTIVE','MENTOR_ALREADY_TERMINATING') THEN
   SELECT coalesce(activity_status,'active') INTO v_state FROM public.mentor_profiles WHERE user_id=v_uid;
   RETURN jsonb_build_object('ok',false,'contract_version',1,'code','ACTIVITY_STATE_INVALID','current_state',v_state);
  END IF;
  RETURN v_result||jsonb_build_object('contract_version',1);
 END IF;
 v_summary:=v_result->'summary';
 IF v_target='paused' THEN
  RETURN jsonb_build_object('ok',true,'contract_version',1,'activity_status','paused',
   'pause_until',v_summary->'pauseUntil','pause_days',v_summary->'days','pause_reason',v_reason,
   'subscriptions_extended',v_summary->'subscriptionsExtended','event_status',v_result->'event_status','event_id',v_result->'event_id');
 ELSIF v_target='active' THEN
  RETURN jsonb_build_object('ok',true,'contract_version',1,'activity_status','active',
   'plans_reactivated',v_summary->'plansChanged','event_id',v_result->'event_id');
 ELSE
  RETURN jsonb_build_object('ok',true,'contract_version',1,'activity_status','terminating',
   'termination_effective_at',v_summary->'effectiveAt','notified_subscribers',v_summary->'notifiedSubscribers',
   'plans_deactivated',v_summary->'plansChanged','event_id',v_result->'event_id');
 END IF;
END $function$

CREATE OR REPLACE FUNCTION api_app_v1.mentor_plan_active_set(p_tier text, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_role text; v_status text; v_susp timestamptz; v_norm text;
  v_tier text := lower(btrim(coalesce(p_tier, '')));
  v_act text;
  v_plan record;
  v_others integer;
  v_changed boolean := false;
  v_active_tiers text[];
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'AUTH_REQUIRED');
  end if;
  select u.role, u.status, u.suspended_until into v_role, v_status, v_susp from public.users u where u.id = v_uid;
  if not found or v_role is distinct from 'mentor' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROLE_NOT_MENTOR');
  end if;
  v_norm := lower(btrim(coalesce(v_status, '')));
  if v_norm = 'banned' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_BANNED');
  end if;
  if v_norm = 'suspended' and (v_susp is null or v_susp > now()) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_SUSPENDED');
  end if;
  if v_norm not in ('active', 'suspended') then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_NOT_ACTIVE');
  end if;
  if public.account_deletion_write_blocked(v_uid) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_DELETION_IN_PROGRESS');
  end if;
  if v_tier not in ('limited', 'standard', 'premium') then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PLAN_TIER_INVALID');
  end if;
  if p_is_active is null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PLAN_ACTIVE_VALUE_REQUIRED');
  end if;

  select mp.activity_status into v_act from public.mentor_profiles mp where mp.user_id = v_uid for update;
  if not found then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'MENTOR_PROFILE_NOT_FOUND');
  end if;
  if lower(btrim(coalesce(v_act, 'active'))) in ('terminating', 'terminated') then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'MENTOR_TERMINATED');
  end if;

  select mp.id, mp.is_active into v_plan from public.mentor_plans mp
   where mp.mentor_id = v_uid and mp.plan_tier = v_tier for update;
  if not found then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PLAN_NOT_FOUND', 'plan_tier', v_tier);
  end if;

  if p_is_active = false then
    select count(*) into v_others from public.mentor_plans mp
     where mp.mentor_id = v_uid and mp.plan_tier in ('limited', 'standard', 'premium')
       and mp.plan_tier <> v_tier and coalesce(mp.is_active, true);
    if v_others = 0 then
      return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'LAST_ACTIVE_PLAN', 'plan_tier', v_tier);
    end if;
  end if;

  if coalesce(v_plan.is_active, true) is distinct from p_is_active then
    update public.mentor_plans mp set is_active = p_is_active where mp.id = v_plan.id;
    v_changed := true;
  end if;

  select coalesce(array_agg(mp.plan_tier order by case mp.plan_tier when 'limited' then 1 when 'standard' then 2 else 3 end), '{}'::text[])
    into v_active_tiers
    from public.mentor_plans mp
   where mp.mentor_id = v_uid and mp.plan_tier in ('limited', 'standard', 'premium') and coalesce(mp.is_active, true);

  return jsonb_build_object('ok', true, 'contract_version', 1, 'plan_tier', v_tier, 'is_active', p_is_active,
                            'changed', v_changed, 'active_tiers', to_jsonb(v_active_tiers));
end
$function$

CREATE OR REPLACE FUNCTION api_app_v1.mentor_student_id_document_set_self(p_object_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_role text; v_status text; v_susp timestamptz; v_norm text;
  v_path text := regexp_replace(btrim(coalesce(p_object_path, '')), '^/+', '');
  v_ext text;
  v_ref text;
  v_updated timestamptz;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'AUTH_REQUIRED');
  end if;
  select u.role, u.status, u.suspended_until into v_role, v_status, v_susp from public.users u where u.id = v_uid;
  if not found or v_role is distinct from 'mentor' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROLE_NOT_MENTOR');
  end if;
  v_norm := lower(btrim(coalesce(v_status, '')));
  if v_norm = 'banned' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_BANNED');
  end if;
  if v_norm = 'suspended' and (v_susp is null or v_susp > now()) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_SUSPENDED');
  end if;
  if v_norm not in ('active', 'suspended') then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_NOT_ACTIVE');
  end if;
  if public.account_deletion_write_blocked(v_uid) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_DELETION_IN_PROGRESS');
  end if;
  if not exists (select 1 from public.mentor_profiles mp where mp.user_id = v_uid) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'MENTOR_PROFILE_NOT_FOUND');
  end if;

  -- 저장값 형식(student-id-images/…)으로 넘어와도 받는다 — 객체 경로만 남긴다
  if v_path like 'student-id-images/%' then
    v_path := substr(v_path, char_length('student-id-images/') + 1);
  end if;
  if v_path = '' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'STORAGE_PATH_REQUIRED');
  end if;
  if split_part(v_path, '/', 1) is distinct from v_uid::text
     or split_part(v_path, '/', 2) = ''
     or v_path ~ '(^|/)\.\.(/|$)'
     or v_path like '%//%' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'STORAGE_PATH_INVALID');
  end if;
  v_ext := lower(coalesce((regexp_match(v_path, '\.([A-Za-z0-9]+)$'))[1], ''));
  if v_ext not in ('jpg', 'jpeg', 'png', 'pdf') then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'STORAGE_FILE_TYPE_INVALID');
  end if;
  -- 객체 실재 + 정확한 버킷 + 소유(owner_id = auth.uid()) — 139 qna_register_attachment 동일 검증
  if not exists (select 1 from storage.objects o
                  where o.bucket_id = 'student-id-images' and o.name = v_path and o.owner_id = v_uid::text) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'STORAGE_OBJECT_NOT_OWNED');
  end if;

  v_ref := 'student-id-images/' || v_path;
  update public.mentor_profiles mp
     set student_id_image_url = v_ref
   where mp.user_id = v_uid
   returning mp.updated_at into v_updated;

  return jsonb_build_object('ok', true, 'contract_version', 1, 'stored_ref', v_ref, 'updated_at', v_updated);
end
$function$

CREATE OR REPLACE FUNCTION api_app_v1.refund_estimate(p_subscription_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
