CREATE OR REPLACE FUNCTION api_web_v1.mentor_payout_account_update_self(p_bank_name text, p_account_number text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid    uuid := (SELECT auth.uid());
  v_role   text;
  v_status text;
  v_susp   timestamptz;
  v_bank   text := btrim(coalesce(p_bank_name, ''));
  v_acct   text := btrim(coalesce(p_account_number, ''));
  v_updated timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'AUTH_REQUIRED');
  END IF;
  SELECT u.role, u.status, u.suspended_until INTO v_role, v_status, v_susp
    FROM public.users u WHERE u.id = v_uid;
  IF NOT FOUND OR v_role IS DISTINCT FROM 'mentor' THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROLE_NOT_MENTOR');
  END IF;
  IF lower(coalesce(v_status, 'active')) = 'banned' THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_BANNED');
  END IF;
  IF lower(coalesce(v_status, 'active')) = 'suspended' AND (v_susp IS NULL OR v_susp > now()) THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_SUSPENDED');
  END IF;
  IF public.account_deletion_write_blocked(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_DELETION_IN_PROGRESS');
  END IF;
  IF NOT public.individual_question_user_is_approved_mentor(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'MENTOR_NOT_APPROVED');
  END IF;

  -- 은행명 allowlist (웹 정본 BANK_OPTIONS 17종 — MentorPayoutAccountPanel.tsx)
  IF v_bank NOT IN ('KB국민은행', '신한은행', '우리은행', '하나은행', 'NH농협은행',
                    'IBK기업은행', '카카오뱅크', '토스뱅크', '케이뱅크', 'SC제일은행',
                    '씨티은행', 'KDB산업은행', '수협은행', '신협', '새마을금고', '우체국',
                    'iM뱅크') THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PAYOUT_BANK_NAME_INVALID');
  END IF;
  -- 계좌번호 숫자만·길이 8~24
  IF v_acct !~ '^[0-9]{8,24}$' THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PAYOUT_ACCOUNT_NUMBER_INVALID');
  END IF;

  UPDATE public.mentor_profiles mp
     SET payout_bank_name = v_bank,
         payout_account_number = v_acct
   WHERE mp.user_id = v_uid
   RETURNING mp.updated_at INTO v_updated;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'MENTOR_PROFILE_NOT_FOUND');
  END IF;

  -- 계좌 원문 비반환 — 끝 4자리 외 마스킹(§11.4)
  RETURN jsonb_build_object('ok', true, 'contract_version', 1, 'updated_at', v_updated,
    'account_masked', repeat('*', greatest(char_length(v_acct) - 4, 0)) || right(v_acct, 4));
END $function$

CREATE OR REPLACE FUNCTION api_web_v1.mentor_plan_prices_set_self(p_limited_cash_krw integer, p_standard_cash_krw integer, p_premium_cash_krw integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid    uuid := (SELECT auth.uid());
  v_role   text;
  v_status text;
  v_susp   timestamptz;
  -- 밴드 상수 — 정본 lib/subscribe/mentorPlanPricing.ts:13 와 동일 (T-REG-02).
  -- 잠금값 개정 시 두 정본을 같은 PR 에서 함께 변경한다(계약 §7 F8).
  v_tiers  text[]  := ARRAY['limited', 'standard', 'premium'];
  v_mins   int[]   := ARRAY[29900, 84900, 174900];
  v_maxs   int[]   := ARRAY[69900, 149900, 329900];
  -- 190: cap 가중치는 public.subscription_cap_weight() 단일 정본 — 리터럴 사본을 두지 않는다.
  v_caps   numeric[] := ARRAY[public.subscription_cap_weight('limited'),
                              public.subscription_cap_weight('standard'),
                              public.subscription_cap_weight('premium')];
  v_given  int[];
  v_i      int;
  v_amount int;
  v_old    int;
  v_updated   jsonb := '[]'::jsonb;
  v_unchanged jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'AUTH_REQUIRED');
  END IF;
  SELECT u.role, u.status, u.suspended_until INTO v_role, v_status, v_susp
    FROM public.users u WHERE u.id = v_uid;
  IF NOT FOUND OR v_role IS DISTINCT FROM 'mentor' THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROLE_NOT_MENTOR');
  END IF;
  IF lower(coalesce(v_status, 'active')) = 'banned' THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_BANNED');
  END IF;
  IF lower(coalesce(v_status, 'active')) = 'suspended' AND (v_susp IS NULL OR v_susp > now()) THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_SUSPENDED');
  END IF;
  IF public.account_deletion_write_blocked(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_DELETION_IN_PROGRESS');
  END IF;

  v_given := ARRAY[p_limited_cash_krw, p_standard_cash_krw, p_premium_cash_krw];

  -- 전건 검증 선행 → 전건 반영 또는 전건 실패 (3 tier 단일 트랜잭션 — T-CONC-07 상당)
  FOR v_i IN 1..3 LOOP
    IF v_given[v_i] IS NULL OR v_given[v_i] < 1 THEN
      RETURN jsonb_build_object('ok', false, 'contract_version', 1,
                                'code', 'PLAN_PRICE_INVALID', 'tier', v_tiers[v_i]);
    END IF;
    IF v_given[v_i] < v_mins[v_i] OR v_given[v_i] > v_maxs[v_i] THEN
      RETURN jsonb_build_object('ok', false, 'contract_version', 1,
                                'code', 'PLAN_PRICE_OUT_OF_BAND', 'tier', v_tiers[v_i],
                                'min_cash_krw', v_mins[v_i], 'max_cash_krw', v_maxs[v_i],
                                'given_cash_krw', v_given[v_i]);
    END IF;
  END LOOP;

  FOR v_i IN 1..3 LOOP
    v_amount := v_given[v_i] * 100;   -- amountCentsFromCashKrw 동일 (1캐시 = 1원 = 100 cents)
    SELECT mp.amount_cents INTO v_old FROM public.mentor_plans mp
     WHERE mp.mentor_id = v_uid AND mp.plan_tier = v_tiers[v_i];
    IF FOUND AND v_old = v_amount
       AND EXISTS (SELECT 1 FROM public.mentor_plans mp
                    WHERE mp.mentor_id = v_uid AND mp.plan_tier = v_tiers[v_i]
                      AND mp.cap_weight = v_caps[v_i]) THEN
      v_unchanged := v_unchanged || jsonb_build_object('plan_tier', v_tiers[v_i], 'amount_cents', v_amount);
    ELSE
      INSERT INTO public.mentor_plans (mentor_id, plan_tier, amount_cents, cap_weight, is_active, price_updated_at)
      VALUES (v_uid, v_tiers[v_i], v_amount, v_caps[v_i], true, now())
      ON CONFLICT (mentor_id, plan_tier) DO UPDATE
        SET amount_cents = excluded.amount_cents,
            cap_weight = excluded.cap_weight,       -- tier 고정값 강제(클라이언트 불가)
            price_updated_at = now();
      v_updated := v_updated || jsonb_build_object('plan_tier', v_tiers[v_i], 'amount_cents', v_amount);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'contract_version', 1,
                            'updated', v_updated, 'unchanged', v_unchanged);
END $function$

CREATE OR REPLACE FUNCTION api_web_v1.mentor_profile_update_self(p_university_name text, p_department_name text, p_high_school_name text, p_teaching_subjects text[], p_intro_line text, p_bio text, p_answer_style text, p_profile_image_url text, p_is_open_for_subscriptions boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid      uuid := (SELECT auth.uid());
  v_role     text;
  v_status   text;
  v_susp     timestamptz;
  v_subjects text[];
  v_avatar_path text;
  v_updated  timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'AUTH_REQUIRED');
  END IF;
  SELECT u.role, u.status, u.suspended_until INTO v_role, v_status, v_susp
    FROM public.users u WHERE u.id = v_uid;
  IF NOT FOUND OR v_role IS DISTINCT FROM 'mentor' THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROLE_NOT_MENTOR');
  END IF;
  IF lower(coalesce(v_status, 'active')) = 'banned' THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_BANNED');
  END IF;
  IF lower(coalesce(v_status, 'active')) = 'suspended' AND (v_susp IS NULL OR v_susp > now()) THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_SUSPENDED');
  END IF;
  IF public.account_deletion_write_blocked(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_DELETION_IN_PROGRESS');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.mentor_profiles mp WHERE mp.user_id = v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'MENTOR_PROFILE_NOT_FOUND');
  END IF;
  IF btrim(coalesce(p_university_name, '')) = '' THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'UNIVERSITY_NAME_REQUIRED');
  END IF;
  IF btrim(coalesce(p_department_name, '')) = '' THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'DEPARTMENT_NAME_REQUIRED');
  END IF;

  -- teaching_subjects: subjects.code 실존 값만 보존 (정본 subject 검증 방식 승계)
  SELECT coalesce(array_agg(s.code ORDER BY ord), '{}'::text[]) INTO v_subjects
    FROM unnest(coalesce(p_teaching_subjects, '{}'::text[])) WITH ORDINALITY AS t(code, ord)
    JOIN public.subjects s ON s.code = t.code;

  -- 아바타 ref: NULL 허용(해제). 값이 있으면 profile-avatars 경로 추출 +
  -- 첫 세그먼트 = 본인 uid 검증 (실측 mentorAvatarStorage.ts 추출 규칙과 동일)
  IF p_profile_image_url IS NOT NULL AND btrim(p_profile_image_url) <> '' THEN
    IF position('/profile-avatars/' IN p_profile_image_url) > 0 THEN
      v_avatar_path := split_part(split_part(
        substring(p_profile_image_url FROM position('/profile-avatars/' IN p_profile_image_url) + char_length('/profile-avatars/')),
        '?', 1), '#', 1);
    ELSIF p_profile_image_url !~ '^https?:' THEN
      v_avatar_path := regexp_replace(btrim(p_profile_image_url), '^/+', '');
    ELSE
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PROFILE_IMAGE_REF_INVALID');
    END IF;
    IF v_avatar_path IS NULL OR v_avatar_path = ''
       OR split_part(v_avatar_path, '/', 1) IS DISTINCT FROM v_uid::text
       OR split_part(v_avatar_path, '/', 2) = '' THEN
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PROFILE_IMAGE_REF_INVALID');
    END IF;
  END IF;

  UPDATE public.mentor_profiles mp
     SET university_name = btrim(p_university_name),
         department_name = btrim(p_department_name),
         high_school_name = nullif(btrim(coalesce(p_high_school_name, '')), ''),
         teaching_subjects = v_subjects,
         intro_line = nullif(btrim(coalesce(p_intro_line, '')), ''),
         bio = nullif(btrim(coalesce(p_bio, '')), ''),
         answer_style = nullif(btrim(coalesce(p_answer_style, '')), ''),
         profile_image_url = nullif(btrim(coalesce(p_profile_image_url, '')), ''),
         is_open_for_subscriptions = coalesce(p_is_open_for_subscriptions, mp.is_open_for_subscriptions)
   WHERE mp.user_id = v_uid
   RETURNING mp.updated_at INTO v_updated;

  RETURN jsonb_build_object('ok', true, 'contract_version', 1, 'updated_at', v_updated);
END $function$

CREATE OR REPLACE FUNCTION api_web_v1.record_cash_topup_v2(p_user_id uuid, p_amount_cents bigint, p_order_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_key     text;
  v_m       text[];
  v_uid     uuid;
  v_res     jsonb;
  v_balance bigint;
BEGIN
  -- 1. 입력 검증 (사전 밖 예외는 전파 — §8.2. 레거시와 동일 메시지)
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required';
  END IF;
  IF p_amount_cents IS NULL OR p_amount_cents <= 0 THEN
    RAISE EXCEPTION 'p_amount_cents must be positive';
  END IF;
  IF p_amount_cents > 1000000000 THEN
    RAISE EXCEPTION 'p_amount_too_large';
  END IF;

  -- 2. Toss 주문 참조 형식 강제 — lib/toss/tossTopupCore.ts `^cash-(.+)-(\d+)$` 동치
  v_key := nullif(trim(coalesce(p_order_ref, '')), '');
  IF v_key IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ORDER_REF_INVALID');
  END IF;
  v_m := regexp_match(v_key, '^cash-(.+)-([0-9]+)$');
  IF v_m IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ORDER_REF_INVALID');
  END IF;

  -- 3. 소유자 재검증 — parseUserIdFromCashOrderId 동치(uuid 파싱 불가 = 불일치)
  BEGIN
    v_uid := v_m[1]::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ORDER_REF_OWNER_MISMATCH');
  END;
  IF v_uid IS DISTINCT FROM p_user_id THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ORDER_REF_OWNER_MISMATCH');
  END IF;

  -- 4. 공용 원자 구현부 호출 (p_idempotency_key = p_order_ref — 별도 인자가 아니다)
  v_res := core_private.record_cash_topup_impl(p_user_id, p_amount_cents, v_key);

  -- 5. 신규 → 성공
  IF coalesce((v_res->>'inserted')::boolean, false) THEN
    SELECT w.balance_cents INTO v_balance FROM public.cash_wallets w WHERE w.user_id = p_user_id;
    RETURN jsonb_build_object('ok', true, 'contract_version', 1, 'duplicate', false,
                              'ledger_id', (v_res->>'ledger_id')::uuid,
                              'balance_cents', v_balance);
  END IF;

  -- 5. duplicate → 기존 6필드 NULL-safe 전건 대조 (일반 =·<> 는 nullable 필드에 금지)
  IF (v_res->>'user_id')::uuid IS NOT DISTINCT FROM p_user_id
     AND (v_res->>'delta_cents')::bigint IS NOT DISTINCT FROM p_amount_cents
     AND (v_res->>'reason') IS NOT DISTINCT FROM 'cash_topup'
     AND (v_res->>'ref_type') IS NOT DISTINCT FROM 'topup'
     AND (v_res->>'ref_id') IS NULL
     AND (v_res->>'idempotency_key') IS NOT NULL
     AND (v_res->>'idempotency_key') = v_key THEN
    SELECT w.balance_cents INTO v_balance FROM public.cash_wallets w WHERE w.user_id = p_user_id;
    RETURN jsonb_build_object('ok', true, 'contract_version', 1, 'duplicate', true,
                              'ledger_id', (v_res->>'ledger_id')::uuid,
                              'balance_cents', v_balance);
  END IF;
  RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'LEDGER_FIELD_MISMATCH');
END $function$

CREATE OR REPLACE FUNCTION api_web_v1.user_marketing_consent_set_self(p_agreed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_status text;
  v_susp timestamptz;
  v_norm text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;
  if p_agreed is null then
    raise exception 'CONSENT_VALUE_REQUIRED' using errcode = '22023';
  end if;

  select u.status, u.suspended_until into v_status, v_susp
    from public.users u where u.id = v_uid for update;
  if not found then
    raise exception 'ACCOUNT_NOT_ACTIVE';
  end if;
  v_norm := lower(btrim(coalesce(v_status,'')));
  if v_norm = 'banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if v_norm = 'suspended' and (v_susp is null or v_susp > now()) then raise exception 'ACCOUNT_SUSPENDED'; end if;
  if v_norm not in ('active','suspended') then raise exception 'ACCOUNT_NOT_ACTIVE'; end if;
  if public.account_deletion_write_blocked(v_uid) then raise exception 'ACCOUNT_DELETION_IN_PROGRESS'; end if;

  -- append-only 원장: 기존 행 UPDATE/DELETE 없음 (§18.2)
  -- 209(DB-5 후속 d): idempotency_key(NOT NULL · UNIQUE) 명시 — 토글 이력은 호출마다 새 행(무작위 접미)
  insert into public.user_consent_records
    (user_id, consent_type, consent_actor, consent_version, agreed_at, source, metadata, idempotency_key)
  values
    (v_uid, 'marketing', 'user', 'v1', now(), 'self_rpc', jsonb_build_object('agreed', p_agreed),
     format('self_rpc:%s:marketing:%s', v_uid, gen_random_uuid()));

  update public.users set marketing_agreed = p_agreed, updated_at = now() where id = v_uid;

  return jsonb_build_object('ok', true, 'contract_version', 1, 'marketing_agreed', p_agreed);
end
$function$

CREATE OR REPLACE FUNCTION api_web_v1.weekly_question_usage_self(p_mentor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := (SELECT auth.uid());
BEGIN
  -- 사전 검사 필수(§7 F1) — 정본의 원문 raise 가 새어 나가지 않게 선검사한다
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'AUTH_REQUIRED');
  END IF;
  IF p_mentor_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'MENTOR_ID_REQUIRED');
  END IF;
  -- 계산부는 정본 단일화 — 한도 규칙을 두 곳에 만들지 않는다(§7 F1)
  RETURN public.get_weekly_question_usage(v_uid, p_mentor_id)::jsonb
         || jsonb_build_object('ok', true, 'contract_version', 1);
END $function$

CREATE OR REPLACE FUNCTION api_web_v1.weekly_question_usage_self_batch(p_mentor_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_items jsonb := '[]'::jsonb;
  v_mid uuid;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'AUTH_REQUIRED');
  end if;
  if p_mentor_ids is null or coalesce(array_length(p_mentor_ids, 1), 0) = 0 then
    return jsonb_build_object('ok', true, 'contract_version', 1, 'items', '[]'::jsonb);
  end if;
  if array_length(p_mentor_ids, 1) > 50 then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'TOO_MANY_MENTORS');
  end if;
  for v_mid in select distinct m from unnest(p_mentor_ids) m where m is not null loop
    v_items := v_items || jsonb_build_array(
      public.get_weekly_question_usage(v_uid, v_mid)::jsonb
        || jsonb_build_object('mentor_id', v_mid));
  end loop;
  return jsonb_build_object('ok', true, 'contract_version', 1, 'items', v_items);
end $function$

CREATE OR REPLACE FUNCTION core_private.account_blocked_state(p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_status text;
  v_susp timestamptz;
  v_norm text;
begin
  if p_user_id is null then
    return 'row_missing';
  end if;
  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = p_user_id;
  if not found then
    return 'row_missing';
  end if;
  v_norm := lower(btrim(coalesce(v_status, '')));
  if v_norm = 'banned' then
    return 'banned';
  end if;
  if v_norm = 'suspended' then
    if v_susp is null or v_susp > now() then
      return 'suspended';
    end if;
    -- 만료된 정지 → 허용(앱·웹 동일)
  elsif v_norm = 'deleted' then
    return 'deleted';
  elsif v_norm <> 'active' then
    return 'status_unknown';
  end if;
  if public.account_deletion_write_blocked(p_user_id) then
    return 'deletion_in_progress';
  end if;
  return null;
end
$function$

CREATE OR REPLACE FUNCTION core_private.community_image_refs_validate(p_owner_id uuid, p_image_refs text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_refs  text[] := coalesce(p_image_refs, '{}'::text[]);
  v_ref   text;
  v_path  text;
  v_meta  jsonb;
  v_owner uuid;
BEGIN
  IF p_owner_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'AUTH_REQUIRED');
  END IF;
  IF coalesce(array_length(v_refs, 1), 0) > 5 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'IMAGE_COUNT_EXCEEDED');
  END IF;
  FOREACH v_ref IN ARRAY v_refs LOOP
    -- ① 허용 버킷 (정본 ref 형식: community-post-images/{uid}/{object} — §14.1)
    IF v_ref IS NULL OR v_ref !~ '^community-post-images/' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IMAGE_REF_INVALID');
    END IF;
    v_path := substring(v_ref FROM char_length('community-post-images/') + 1);
    IF split_part(v_path, '/', 2) = '' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IMAGE_REF_INVALID');
    END IF;
    -- ② path 첫 세그먼트 = 소유자
    IF split_part(v_path, '/', 1) IS DISTINCT FROM p_owner_id::text THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IMAGE_NOT_OWNED');
    END IF;
    -- ③ storage.objects 실존
    SELECT o.metadata, coalesce(o.owner, nullif(o.owner_id, '')::uuid)
      INTO v_meta, v_owner
      FROM storage.objects o
     WHERE o.bucket_id = 'community-post-images' AND o.name = v_path;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IMAGE_OBJECT_NOT_FOUND');
    END IF;
    -- ④ 소유자·MIME·크기 (버킷 정책 실측값 — 5 MiB · 4종 MIME)
    IF v_owner IS DISTINCT FROM p_owner_id THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IMAGE_NOT_OWNED');
    END IF;
    IF coalesce(v_meta ->> 'mimetype', '')
       NOT IN ('image/jpeg', 'image/png', 'image/webp', 'image/gif') THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IMAGE_MIME_NOT_ALLOWED');
    END IF;
    IF coalesce((v_meta ->> 'size')::bigint, 0) > 5242880 THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IMAGE_SIZE_EXCEEDED');
    END IF;
  END LOOP;
  RETURN jsonb_build_object('ok', true);
END $function$

CREATE OR REPLACE FUNCTION core_private.community_post_create_impl(p_author_id uuid, p_title text, p_body text, p_category text, p_image_refs text[], p_status text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_role     text;
  v_status   text;
  v_susp     timestamptz;
  v_nickname text;
  v_title    text;
  v_body     text;
  v_val      jsonb;
  v_id       uuid;
  v_norm     text;
BEGIN
  IF p_author_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'AUTH_REQUIRED');
  END IF;
  -- 멱등키 필수(§14.4) — 계약 밖 입력은 전파(§8.2)
  IF p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'p_idempotency_key is required';
  END IF;

  -- [replay-first — 신규 쓰기 검증보다 먼저] 기존 커밋 행 재생 (§7 F4 1~2단계)
  SELECT cp.id INTO v_id FROM public.community_posts cp
   WHERE cp.author_id = p_author_id AND cp.create_idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', true, 'post_id', v_id, 'idempotent_replay', true);
  END IF;

  -- [신규 쓰기 검증 — 역할 → 계정 → 본문 → 이미지]
  SELECT u.role, u.status, u.suspended_until, u.nickname
    INTO v_role, v_status, v_susp, v_nickname
    FROM public.users u WHERE u.id = p_author_id;
  -- S3-C 범위 A: 게시판 작성 자격 = active student + active mentor.
  -- admin·unknown role·users 행 부재는 ROLE_NOT_ALLOWED 로 거부한다.
  IF NOT FOUND OR v_role IS NULL OR v_role NOT IN ('student', 'mentor') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ROLE_NOT_ALLOWED');
  END IF;
  -- [보정 2차 §1] 계정 상태는 **positive allowlist** 다(fail-open 금지).
  --   허용: 'active' | ('suspended' 이고 suspended_until <= now() = 정지 만료)
  --   그 외(deleted·dormant·빈 문자열·NULL·미지 값)는 ACCOUNT_NOT_ACTIVE.
  --   banned·유효 suspended 는 기존 전용 코드를 유지한다(먼저 판정).
  v_norm := lower(btrim(coalesce(v_status, '')));
  IF v_norm = 'banned' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_BANNED');
  END IF;
  IF v_norm = 'suspended' AND (v_susp IS NULL OR v_susp > now()) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_SUSPENDED');
  END IF;
  IF NOT (v_norm = 'active'
          OR (v_norm = 'suspended' AND v_susp IS NOT NULL AND v_susp <= now())) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_NOT_ACTIVE');
  END IF;
  IF public.account_deletion_write_blocked(p_author_id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_DELETION_IN_PROGRESS');
  END IF;
  IF p_status NOT IN ('draft', 'published') THEN
    RAISE EXCEPTION 'p_status must be draft|published';
  END IF;
  v_title := btrim(coalesce(p_title, ''));
  IF v_title = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'TITLE_REQUIRED');
  END IF;
  IF p_category IS NULL OR p_category NOT IN ('study', 'school', 'career', 'college', 'free') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CATEGORY_INVALID');
  END IF;
  v_body := btrim(coalesce(p_body, ''));
  IF p_status = 'published' AND char_length(v_body) < 10 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'BODY_TOO_SHORT');
  END IF;

  -- [연락처 마스킹 — lib/customRequest/contactMasking.ts 정본 이식, 적용 순서 동일.
  --  제목·본문 모두 마스킹(웹 실측 동작). 금지어 검사 없음(rev 8 D — B-04 동결)]
  v_title := regexp_replace(v_title, '(^|[^0-9])(\+82[-._\s]?0?1[0-9][-._\s]?[0-9]{3,4}[-._\s]?[0-9]{4}|0(?:10|11|16|17|18|19|2|[3-6][1-5]|50|70|80)[-._\s]?[0-9]{3,4}[-._\s]?[0-9]{4})(?![0-9])', '\1[연락처 비공개]', 'g');
  v_body  := regexp_replace(v_body,  '(^|[^0-9])(\+82[-._\s]?0?1[0-9][-._\s]?[0-9]{3,4}[-._\s]?[0-9]{4}|0(?:10|11|16|17|18|19|2|[3-6][1-5]|50|70|80)[-._\s]?[0-9]{3,4}[-._\s]?[0-9]{4})(?![0-9])', '\1[연락처 비공개]', 'g');
  v_title := regexp_replace(v_title, '(공일공|영일영)[\s\-._]*[0-9공영일이삼사오육칠팔구][0-9공영일이삼사오육칠팔구\s\-._]{6,12}', '[연락처 비공개]', 'g');
  v_body  := regexp_replace(v_body,  '(공일공|영일영)[\s\-._]*[0-9공영일이삼사오육칠팔구][0-9공영일이삼사오육칠팔구\s\-._]{6,12}', '[연락처 비공개]', 'g');
  v_title := regexp_replace(v_title, '[A-Za-z0-9._%+-]+\s*[\[({（]\s*at\s*[\])}）]\s*[A-Za-z0-9.-]+\s*(?:[\[({（]\s*dot\s*[\])}）]|\.)\s*[A-Za-z]{2,}', '[연락처 비공개]', 'gi');
  v_body  := regexp_replace(v_body,  '[A-Za-z0-9._%+-]+\s*[\[({（]\s*at\s*[\])}）]\s*[A-Za-z0-9.-]+\s*(?:[\[({（]\s*dot\s*[\])}）]|\.)\s*[A-Za-z]{2,}', '[연락처 비공개]', 'gi');
  v_title := regexp_replace(v_title, '\y[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\y', '[연락처 비공개]', 'gi');
  v_body  := regexp_replace(v_body,  '\y[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\y', '[연락처 비공개]', 'gi');
  v_title := regexp_replace(v_title, '\y(?:open\.kakao\.com|kakaotalk\.com|t\.me|telegram\.me|instagram\.com|instagr\.am|linktr\.ee)(?:/[^\s<>"'']*)?', '[연락처 비공개]', 'gi');
  v_body  := regexp_replace(v_body,  '\y(?:open\.kakao\.com|kakaotalk\.com|t\.me|telegram\.me|instagram\.com|instagr\.am|linktr\.ee)(?:/[^\s<>"'']*)?', '[연락처 비공개]', 'gi');
  v_title := regexp_replace(v_title, '(카카오톡|카톡|오픈채팅|텔레그램|인스타그램|인스타|디엠)\s*[:：=]?\s*@?[A-Za-z0-9._-]{4,}', '[연락처 비공개]', 'g');
  v_body  := regexp_replace(v_body,  '(카카오톡|카톡|오픈채팅|텔레그램|인스타그램|인스타|디엠)\s*[:：=]?\s*@?[A-Za-z0-9._-]{4,}', '[연락처 비공개]', 'g');

  -- 이미지 ref 검증 (B-4 공용 검증기)
  v_val := core_private.community_image_refs_validate(p_author_id, coalesce(p_image_refs, '{}'::text[]));
  IF NOT coalesce((v_val ->> 'ok')::boolean, false) THEN
    RETURN v_val;
  END IF;

  -- INSERT (컬럼 집합 = 현행 웹 insertCommunityBoardPost 동일. author_label/role 서버 도출)
  INSERT INTO public.community_posts
    (author_id, title, body, content, category, image_urls, hashtags, status,
     author_label, author_role, create_idempotency_key)
  VALUES
    (p_author_id, v_title, v_body, v_body, p_category,
     coalesce(p_image_refs, '{}'::text[]), '{}'::text[], p_status,
     coalesce(nullif(btrim(v_nickname), ''), '쌤버십 사용자'),
     CASE WHEN v_role IN ('student', 'mentor') THEN v_role END,
     p_idempotency_key)
  ON CONFLICT (author_id, create_idempotency_key) DO NOTHING
  RETURNING id INTO v_id;

  -- 동시 경합 패자 → 재생 수렴 (T-CONC-06)
  IF v_id IS NULL THEN
    SELECT cp.id INTO v_id FROM public.community_posts cp
     WHERE cp.author_id = p_author_id AND cp.create_idempotency_key = p_idempotency_key;
    IF v_id IS NULL THEN
      RAISE EXCEPTION 'community_post_create_impl: idempotent insert not observable';
    END IF;
    RETURN jsonb_build_object('ok', true, 'post_id', v_id, 'idempotent_replay', true);
  END IF;

  RETURN jsonb_build_object('ok', true, 'post_id', v_id, 'idempotent_replay', false);
END $function$

CREATE OR REPLACE FUNCTION core_private.community_post_soft_delete_impl(p_author_id uuid, p_post_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_status  text;
  v_susp    timestamptz;
  v_deleted timestamptz;
BEGIN
  IF p_author_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'AUTH_REQUIRED');
  END IF;
  IF p_post_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'POST_NOT_FOUND_OR_NOT_OWNED');
  END IF;

  -- 소유 행 잠금 — 역할 게이트 없음(작성자 본인 soft-delete 는 학생 글 보존 규칙상 허용)
  SELECT cp.deleted_at INTO v_deleted
    FROM public.community_posts cp
   WHERE cp.id = p_post_id AND cp.author_id = p_author_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'POST_NOT_FOUND_OR_NOT_OWNED');
  END IF;

  -- 계정 쓰기 게이트 (§11.5 fail-closed)
  SELECT u.status, u.suspended_until INTO v_status, v_susp
    FROM public.users u WHERE u.id = p_author_id;
  IF lower(coalesce(v_status, 'active')) = 'banned' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_BANNED');
  END IF;
  IF lower(coalesce(v_status, 'active')) = 'suspended' AND (v_susp IS NULL OR v_susp > now()) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_SUSPENDED');
  END IF;
  IF public.account_deletion_write_blocked(p_author_id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_DELETION_IN_PROGRESS');
  END IF;

  -- 이미 삭제면 ok:true + already_deleted:true (§8.3 F6)
  IF v_deleted IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'post_id', p_post_id, 'deleted_at', v_deleted,
                              'already_deleted', true);
  END IF;

  -- soft delete — 행·이미지 참조 보존, hard delete 금지 (§14.4)
  UPDATE public.community_posts cp SET deleted_at = now()
   WHERE cp.id = p_post_id
   RETURNING cp.deleted_at INTO v_deleted;

  RETURN jsonb_build_object('ok', true, 'post_id', p_post_id, 'deleted_at', v_deleted);
END $function$

CREATE OR REPLACE FUNCTION core_private.community_post_update_impl(p_author_id uuid, p_post_id uuid, p_title text, p_body text, p_category text, p_image_refs text[], p_status text, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_role       text;
  v_status     text;
  v_susp       timestamptz;
  v_post       record;
  v_title      text;
  v_body       text;
  v_val        jsonb;
  v_removed    text[];
  v_updated_at timestamptz;
  v_norm       text;
BEGIN
  IF p_author_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'AUTH_REQUIRED');
  END IF;
  IF p_post_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'POST_NOT_FOUND_OR_NOT_OWNED');
  END IF;

  -- 소유 행 잠금 (비존재·타인 글·삭제 글 동일 코드 — §9.4)
  SELECT cp.id, cp.image_urls, cp.updated_at INTO v_post
    FROM public.community_posts cp
   WHERE cp.id = p_post_id AND cp.author_id = p_author_id AND cp.deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'POST_NOT_FOUND_OR_NOT_OWNED');
  END IF;

  -- 역할·계정 (S3-C 보정 §2: 학생 글 수정 거부 규칙 폐기 — create 와 **문자 그대로 동일** 계약)
  SELECT u.role, u.status, u.suspended_until INTO v_role, v_status, v_susp
    FROM public.users u WHERE u.id = p_author_id;
  IF NOT FOUND OR v_role IS NULL OR v_role NOT IN ('student', 'mentor') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ROLE_NOT_ALLOWED');
  END IF;
  -- [보정 2차 §1] create 와 동일한 positive allowlist (fail-open 금지)
  v_norm := lower(btrim(coalesce(v_status, '')));
  IF v_norm = 'banned' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_BANNED');
  END IF;
  IF v_norm = 'suspended' AND (v_susp IS NULL OR v_susp > now()) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_SUSPENDED');
  END IF;
  IF NOT (v_norm = 'active'
          OR (v_norm = 'suspended' AND v_susp IS NOT NULL AND v_susp <= now())) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_NOT_ACTIVE');
  END IF;
  IF public.account_deletion_write_blocked(p_author_id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_DELETION_IN_PROGRESS');
  END IF;

  -- 낙관적 충돌 검사 (§7 F5)
  IF v_post.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UPDATE_CONFLICT');
  END IF;

  IF p_status NOT IN ('draft', 'published') THEN
    RAISE EXCEPTION 'p_status must be draft|published';
  END IF;
  v_title := btrim(coalesce(p_title, ''));
  IF v_title = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'TITLE_REQUIRED');
  END IF;
  IF p_category IS NULL OR p_category NOT IN ('study', 'school', 'career', 'college', 'free') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CATEGORY_INVALID');
  END IF;
  v_body := btrim(coalesce(p_body, ''));
  IF p_status = 'published' AND char_length(v_body) < 10 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'BODY_TOO_SHORT');
  END IF;

  -- [연락처 마스킹 — B-1 과 동일 정본 이식(contactMasking.ts) · 동일 순서]
  v_title := regexp_replace(v_title, '(^|[^0-9])(\+82[-._\s]?0?1[0-9][-._\s]?[0-9]{3,4}[-._\s]?[0-9]{4}|0(?:10|11|16|17|18|19|2|[3-6][1-5]|50|70|80)[-._\s]?[0-9]{3,4}[-._\s]?[0-9]{4})(?![0-9])', '\1[연락처 비공개]', 'g');
  v_body  := regexp_replace(v_body,  '(^|[^0-9])(\+82[-._\s]?0?1[0-9][-._\s]?[0-9]{3,4}[-._\s]?[0-9]{4}|0(?:10|11|16|17|18|19|2|[3-6][1-5]|50|70|80)[-._\s]?[0-9]{3,4}[-._\s]?[0-9]{4})(?![0-9])', '\1[연락처 비공개]', 'g');
  v_title := regexp_replace(v_title, '(공일공|영일영)[\s\-._]*[0-9공영일이삼사오육칠팔구][0-9공영일이삼사오육칠팔구\s\-._]{6,12}', '[연락처 비공개]', 'g');
  v_body  := regexp_replace(v_body,  '(공일공|영일영)[\s\-._]*[0-9공영일이삼사오육칠팔구][0-9공영일이삼사오육칠팔구\s\-._]{6,12}', '[연락처 비공개]', 'g');
  v_title := regexp_replace(v_title, '[A-Za-z0-9._%+-]+\s*[\[({（]\s*at\s*[\])}）]\s*[A-Za-z0-9.-]+\s*(?:[\[({（]\s*dot\s*[\])}）]|\.)\s*[A-Za-z]{2,}', '[연락처 비공개]', 'gi');
  v_body  := regexp_replace(v_body,  '[A-Za-z0-9._%+-]+\s*[\[({（]\s*at\s*[\])}）]\s*[A-Za-z0-9.-]+\s*(?:[\[({（]\s*dot\s*[\])}）]|\.)\s*[A-Za-z]{2,}', '[연락처 비공개]', 'gi');
  v_title := regexp_replace(v_title, '\y[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\y', '[연락처 비공개]', 'gi');
  v_body  := regexp_replace(v_body,  '\y[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\y', '[연락처 비공개]', 'gi');
  v_title := regexp_replace(v_title, '\y(?:open\.kakao\.com|kakaotalk\.com|t\.me|telegram\.me|instagram\.com|instagr\.am|linktr\.ee)(?:/[^\s<>"'']*)?', '[연락처 비공개]', 'gi');
  v_body  := regexp_replace(v_body,  '\y(?:open\.kakao\.com|kakaotalk\.com|t\.me|telegram\.me|instagram\.com|instagr\.am|linktr\.ee)(?:/[^\s<>"'']*)?', '[연락처 비공개]', 'gi');
  v_title := regexp_replace(v_title, '(카카오톡|카톡|오픈채팅|텔레그램|인스타그램|인스타|디엠)\s*[:：=]?\s*@?[A-Za-z0-9._-]{4,}', '[연락처 비공개]', 'g');
  v_body  := regexp_replace(v_body,  '(카카오톡|카톡|오픈채팅|텔레그램|인스타그램|인스타|디엠)\s*[:：=]?\s*@?[A-Za-z0-9._-]{4,}', '[연락처 비공개]', 'g');

  v_val := core_private.community_image_refs_validate(p_author_id, coalesce(p_image_refs, '{}'::text[]));
  IF NOT coalesce((v_val ->> 'ok')::boolean, false) THEN
    RETURN v_val;
  END IF;

  -- 제거된 ref 차집합 (클라이언트가 commit 후 best-effort 삭제 — §14.4)
  v_removed := ARRAY(SELECT unnest(coalesce(v_post.image_urls, '{}'::text[]))
                     EXCEPT
                     SELECT unnest(coalesce(p_image_refs, '{}'::text[])));

  UPDATE public.community_posts cp
     SET title = v_title, body = v_body, content = v_body, category = p_category,
         image_urls = coalesce(p_image_refs, '{}'::text[]), status = p_status,
         updated_at = now()
   WHERE cp.id = p_post_id
   RETURNING cp.updated_at INTO v_updated_at;

  RETURN jsonb_build_object('ok', true, 'post_id', p_post_id, 'updated_at', v_updated_at,
                            'removed_image_refs', to_jsonb(coalesce(v_removed, '{}'::text[])));
END $function$

CREATE OR REPLACE FUNCTION core_private.confirm_cash_subscription_payment(p_payment_id uuid, p_plan_id uuid, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_student uuid; v_mentor uuid; v_pay_status text; v_created_at timestamptz; v_kind text;
  v_plan_mentor uuid; v_plan_tier text; v_plan_active boolean; v_amount_cents int;
  v_is_open boolean; v_sub_id uuid; v_reactivated boolean := false;
  v_status text; v_suspended_until timestamptz;
  v_l_user uuid; v_l_delta bigint; v_l_reason text; v_l_reftype text; v_l_refid uuid;
  v_succeeded_aliases text[] := array['succeeded','paid','success','complete','captured'];
  v_anom uuid; v_err text; v_errcode text;
  v_pair_student uuid; v_pair_mentor uuid; v_existing public.subscriptions%ROWTYPE; v_decided_at timestamptz;
begin
  select user_id,mentor_id into v_pair_student,v_pair_mentor from public.payments where id=p_payment_id;
  if not found then raise exception 'PAYMENT_NOT_FOUND'; end if;
  perform pg_advisory_xact_lock(hashtext(v_pair_student::text),hashtext(v_pair_mentor::text));
  select user_id, mentor_id, status, created_at, kind into v_student, v_mentor, v_pay_status, v_created_at, v_kind
    from public.payments where id = p_payment_id for update;
  if not found then raise exception 'PAYMENT_NOT_FOUND'; end if;
  if v_student is distinct from v_pair_student or v_mentor is distinct from v_pair_mentor then raise exception 'PAYMENT_PARTY_CHANGED'; end if;
  if v_student is null then raise exception 'PAYMENT_NO_USER'; end if;
  if v_mentor is null then raise exception 'PAYMENT_NO_MENTOR'; end if;
  if lower(coalesce(v_kind,'')) in ('cash_topup','topup','cash','individual_question','iq','custom_order','custom_request','deliverable') then raise exception 'PAYMENT_KIND_INVALID'; end if;
  perform pg_advisory_xact_lock(hashtext(v_student::text), hashtext(v_mentor::text));
  select * into v_existing from public.subscriptions where student_id=v_student and mentor_id=v_mentor for update;
  perform 1 from public.mentor_profiles where user_id=v_mentor for update;
  select mentor_id, plan_tier, is_active, amount_cents into v_plan_mentor, v_plan_tier, v_plan_active, v_amount_cents
    from public.mentor_plans where id = p_plan_id for update;
  if not found then raise exception 'PLAN_NOT_FOUND'; end if;
  if v_plan_mentor <> v_mentor then raise exception 'PLAN_MENTOR_MISMATCH'; end if;
  if v_amount_cents is null or v_amount_cents <= 0 then raise exception 'PLAN_AMOUNT_INVALID'; end if;
  if v_pay_status = any(v_succeeded_aliases) then
    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor;
    if v_sub_id is null then
      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
        values (p_payment_id, null, 'SUCCEEDED_NO_SUBSCRIPTION', 'succeeded payment without subscription') returning id into v_anom;
      return jsonb_build_object('ok',false,'code','SUCCEEDED_NO_SUBSCRIPTION','anomaly_id',v_anom);
    end if;
    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid
      from public.cash_ledger where idempotency_key = 'sub_debit_' || p_payment_id::text;
    if v_l_user is null then
      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
        values (p_payment_id, v_sub_id, 'SUCCEEDED_NO_LEDGER', 'succeeded payment without ledger debit') returning id into v_anom;
      return jsonb_build_object('ok',false,'code','SUCCEEDED_NO_LEDGER','anomaly_id',v_anom);
    end if;
    if v_l_user <> v_student or v_l_refid is distinct from v_sub_id or coalesce(v_l_reftype,'') <> 'subscriptions'
       or coalesce(v_l_reason,'') <> 'subscription_payment' or v_l_delta <> -v_amount_cents then
      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)
        values (p_payment_id, v_sub_id, 'LEDGER_FIELD_MISMATCH', 'idempotent re-check field mismatch',
          jsonb_build_object('user_id',v_student,'ref_id',v_sub_id,'ref_type','subscriptions','reason','subscription_payment','delta_cents',-v_amount_cents),
          jsonb_build_object('user_id',v_l_user,'ref_id',v_l_refid,'ref_type',v_l_reftype,'reason',v_l_reason,'delta_cents',v_l_delta))
        returning id into v_anom;
      return jsonb_build_object('ok',false,'code','LEDGER_FIELD_MISMATCH','anomaly_id',v_anom);
    end if;
    return jsonb_build_object('ok',true,'idempotent',true,'subscription_id',v_sub_id,'payment_status','succeeded');
  end if;
  if v_pay_status = 'processing' then raise exception 'PAYMENT_PROCESSING'; end if;
  if v_pay_status in ('failed','canceled','refunded') then raise exception 'PAYMENT_NOT_PENDING'; end if;
  if v_pay_status <> 'pending' then raise exception 'PAYMENT_STATE_UNEXPECTED'; end if;
  if v_created_at is null or now() > v_created_at + interval '30 minutes' then raise exception 'PAYMENT_STALE'; end if;
  select status, suspended_until into v_status, v_suspended_until from public.users where id = v_student for update;
  if lower(coalesce(v_status,'active')) = 'banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if lower(coalesce(v_status,'active')) = 'suspended' and (v_suspended_until is null or v_suspended_until > now()) then raise exception 'ACCOUNT_SUSPENDED'; end if;
  perform 1 from public.mentor_profiles where user_id = v_mentor for update;
  select is_open_for_subscriptions into v_is_open from public.mentor_profiles where user_id = v_mentor;
  if not coalesce(v_is_open, true) then raise exception 'MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS'; end if;
  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception 'MENTOR_NOT_APPROVED'; end if;
  if not coalesce(v_plan_active, true) then raise exception 'PLAN_INACTIVE'; end if;
  v_decided_at := clock_timestamp();
  if v_existing.id is not null and core_private.subscription_has_pending_refund(v_existing.id) then
    return jsonb_build_object('ok',false,'code','SERVICE_PERIOD_REFUND_PENDING');
  end if;
  if v_existing.funding_source='voucher' and core_private.service_period_financial_state(v_existing.current_service_period_event_id)<>'refunded' and coalesce((select period_end from public.subscription_billing_events where id=v_existing.current_service_period_event_id and voucher_redemption_id is not null),v_existing.current_period_end,'infinity'::timestamptz)>v_decided_at then
    return jsonb_build_object('ok',false,'code','SERVICE_PERIOD_ACTIVE');
  end if;
  -- Profile row is locked: count the actual weight delta on voucher/cash tier changes too.
  if public.mentor_cap_used(v_mentor) - (case when v_existing.status='active' then public.subscription_cap_weight(v_existing.plan_tier) else 0 end)
     + public.subscription_cap_weight(v_plan_tier) > public.mentor_cap_limit(v_mentor) then raise exception 'MENTOR_CAP_EXCEEDED'; end if;
  v_reactivated := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor);
  begin
    insert into public.subscriptions (student_id, mentor_id, plan_id, plan_tier, status, payment_id,
      started_at, current_period_start, current_period_end, next_billing_at, billing_cycle, cancel_at_period_end, last_payment_id, funding_source)
    values (v_student, v_mentor, p_plan_id, v_plan_tier, 'active', p_payment_id,
      now(), now(), ((now() at time zone 'Asia/Seoul' + interval '1 month') at time zone 'Asia/Seoul'), ((now() at time zone 'Asia/Seoul' + interval '1 month') at time zone 'Asia/Seoul'), 'monthly', false, p_payment_id, 'cash')
    on conflict (student_id, mentor_id) do update set
      plan_id=excluded.plan_id, plan_tier=excluded.plan_tier, status='active', payment_id=excluded.payment_id,
      last_payment_id=excluded.last_payment_id, funding_source='cash', started_at=coalesce(public.subscriptions.started_at, now()),
      current_period_start=now(), current_period_end=((now() at time zone 'Asia/Seoul' + interval '1 month') at time zone 'Asia/Seoul'), next_billing_at=((now() at time zone 'Asia/Seoul' + interval '1 month') at time zone 'Asia/Seoul'),
      cancel_at_period_end=false, cancel_requested_at=null, canceled_at=null, expired_at=null, grace_until=null,
      last_renewed_at=now(), updated_at=now()
    returning id into v_sub_id;
    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid
      from public.cash_ledger where idempotency_key = 'sub_debit_' || p_payment_id::text;
    if v_l_user is not null and (v_l_user <> v_student or v_l_refid is distinct from v_sub_id
       or coalesce(v_l_reftype,'') <> 'subscriptions' or coalesce(v_l_reason,'') <> 'subscription_payment' or v_l_delta <> -v_amount_cents) then
      raise exception 'LEDGER_FIELD_MISMATCH';
    end if;
    perform public.record_subscription_cash_debit(v_student, v_sub_id, p_payment_id, v_amount_cents::bigint);
    update public.payments set status='succeeded', plan_id=p_plan_id,
      metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object('planId',p_plan_id::text,'subscription_id',v_sub_id::text),
      updated_at=now() where id=p_payment_id;
  exception when others then
    get stacked diagnostics v_errcode = returned_sqlstate;
    v_err := sqlerrm;
  end;
  if v_err is not null then
    if v_err like '%CASH_INSUFFICIENT%' then return jsonb_build_object('ok',false,'code','CASH_INSUFFICIENT'); end if;
    insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      values (p_payment_id, v_sub_id, case when v_err like '%LEDGER_FIELD_MISMATCH%' then 'LEDGER_FIELD_MISMATCH' else 'FINANCIAL_WRITE_ERROR' end, 'cash checkout transaction failed') returning id into v_anom;
    return jsonb_build_object('ok',false,'code', case when v_err like '%LEDGER_FIELD_MISMATCH%' then 'LEDGER_FIELD_MISMATCH' else 'FINANCIAL_WRITE_ERROR' end, 'sqlstate',v_errcode,'anomaly_id',v_anom);
  end if;
  return jsonb_build_object('ok',true,'subscription_id',v_sub_id,'payment_status','succeeded','amount_cents',v_amount_cents,'reactivated',v_reactivated);
end; $function$

CREATE OR REPLACE FUNCTION core_private.ensure_student_mentor_room(p_student_id uuid, p_mentor_id uuid, p_payment_id uuid DEFAULT NULL::uuid, p_subscription_id uuid DEFAULT NULL::uuid, p_require_entitlement boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role       text;
  v_status     text;
  v_susp       timestamptz;
  v_created_at timestamptz;
  v_mrole      text;
  v_total      int;
  v_per        int;
  v_entitlement text;
  v_room       uuid;
  v_created    boolean := false;
BEGIN
  -- 필수 인자(사전에 없는 예외는 전파 — §8.2. wrapper 가 NULL 을 넘기지 않는다)
  IF p_student_id IS NULL OR p_mentor_id IS NULL THEN
    RAISE EXCEPTION 'p_student_id and p_mentor_id are required';
  END IF;

  -- ① 학생 역할 확인
  SELECT u.role, u.status, u.suspended_until, u.created_at
    INTO v_role, v_status, v_susp, v_created_at
    FROM public.users u WHERE u.id = p_student_id;
  IF NOT FOUND OR v_role IS DISTINCT FROM 'student' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ROLE_NOT_STUDENT');
  END IF;

  -- ② 계정 상태·탈퇴 write-block (판정식 §11.5 — 정본 qna_create_question_thread 동일)
  IF lower(coalesce(v_status, 'active')) = 'banned' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_BANNED');
  END IF;
  IF lower(coalesce(v_status, 'active')) = 'suspended'
     AND (v_susp IS NULL OR v_susp > now()) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_SUSPENDED');
  END IF;
  IF public.account_deletion_write_blocked(p_student_id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_DELETION_IN_PROGRESS');
  END IF;

  -- ③ 승인 멘토·상호 차단
  SELECT u.role INTO v_mrole FROM public.users u WHERE u.id = p_mentor_id;
  IF NOT FOUND OR v_mrole IS DISTINCT FROM 'mentor' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'MENTOR_NOT_FOUND');
  END IF;
  IF NOT public.individual_question_user_is_approved_mentor(p_mentor_id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'MENTOR_NOT_APPROVED');
  END IF;
  IF EXISTS (SELECT 1 FROM public.user_blocks b
              WHERE (b.blocker_id = p_student_id AND b.blocked_id = p_mentor_id)
                 OR (b.blocker_id = p_mentor_id AND b.blocked_id = p_student_id)) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'BLOCKED');
  END IF;

  -- ④ 학생 행 잠금 + 자격 확인 (동시 호출 직렬화 — T-CONC-01)
  PERFORM 1 FROM public.users u WHERE u.id = p_student_id FOR UPDATE;
  IF p_require_entitlement THEN
    IF EXISTS (SELECT 1 FROM public.subscriptions s
                WHERE s.student_id = p_student_id AND s.mentor_id = p_mentor_id
                  AND lower(coalesce(s.status, '')) = 'active') THEN
      v_entitlement := 'subscription';
    ELSE
      -- 무료질문 자격 — 정본 F3 free 분기와 동일 규칙·동일 순서(가입 7일/전역 7회/멘토별 3회)
      IF v_created_at IS NOT NULL AND now() >= v_created_at + interval '7 days' THEN
        RETURN jsonb_build_object('ok', false, 'code', 'FREE_QUOTA_EXPIRED');
      END IF;
      SELECT count(*) INTO v_total FROM public.free_question_usage f
       WHERE f.student_id = p_student_id;
      IF v_total >= 7 THEN
        RETURN jsonb_build_object('ok', false, 'code', 'FREE_QUOTA_TOTAL_EXHAUSTED');
      END IF;
      SELECT count(*) INTO v_per FROM public.free_question_usage f
       WHERE f.student_id = p_student_id AND f.mentor_id = p_mentor_id;
      IF v_per >= 3 THEN
        RETURN jsonb_build_object('ok', false, 'code', 'FREE_QUOTA_MENTOR_EXHAUSTED');
      END IF;
      v_entitlement := 'free';
    END IF;
  ELSE
    -- F12 구독 확정 경로 — 구독이 방금 확정됐으므로 자격 재검사를 건너뛴다(§7 F10)
    v_entitlement := 'subscription';
  END IF;

  -- ⑤ 기존 방 조회
  SELECT r.id INTO v_room FROM public.mentor_student_rooms r
   WHERE r.student_id = p_student_id AND r.mentor_id = p_mentor_id;

  -- ⑥ 없으면 원자 INSERT (uq_msr_pair 추론 — 동시 경합에서 방은 정확히 1개)
  IF v_room IS NULL THEN
    INSERT INTO public.mentor_student_rooms (student_id, mentor_id, payment_id, subscription_id)
    VALUES (p_student_id, p_mentor_id, p_payment_id, p_subscription_id)
    ON CONFLICT (student_id, mentor_id) DO NOTHING
    RETURNING id INTO v_room;
    v_created := v_room IS NOT NULL;
  END IF;

  -- ⑦ 최종 방 재조회 (경합 패자 경로 포함)
  IF v_room IS NULL THEN
    SELECT r.id INTO v_room FROM public.mentor_student_rooms r
     WHERE r.student_id = p_student_id AND r.mentor_id = p_mentor_id;
  END IF;
  IF v_room IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ROOM_ENSURE_FAILED');
  END IF;

  RETURN jsonb_build_object('ok', true, 'room_id', v_room, 'created', v_created,
                            'entitlement', v_entitlement);
END $function$

CREATE OR REPLACE FUNCTION core_private.finalize_subscription_terminal_impl(p_subscription_id uuid, p_expected_period_end timestamp with time zone, p_expected_last_billing_event_id uuid, p_event_type text, p_processed_at timestamp with time zone, p_legacy_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE s public.subscriptions%ROWTYPE; e public.subscription_billing_events%ROWTYPE;
 t public.subscription_terminal_transitions%ROWTYPE; v_student uuid; v_mentor uuid; v_alias text; v_key text;
 v_matching_periods integer; v_expected_period_matches boolean; v_matching_cash integer;
BEGIN
 IF p_subscription_id IS NULL OR p_processed_at IS NULL OR p_event_type IS NULL OR p_event_type NOT IN ('canceled','expired') THEN
  RETURN jsonb_build_object('ok',false,'code','invalid_transition'); END IF;
 SELECT student_id,mentor_id INTO v_student,v_mentor FROM public.subscriptions WHERE id=p_subscription_id;
 IF v_student IS NULL THEN RETURN jsonb_build_object('ok',false,'code','not_found'); END IF;
 PERFORM pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
 SELECT * INTO s FROM public.subscriptions WHERE id=p_subscription_id FOR UPDATE;
 IF s.student_id IS DISTINCT FROM v_student OR s.mentor_id IS DISTINCT FROM v_mentor THEN RAISE EXCEPTION 'SUBSCRIPTION_BINDING_MISMATCH'; END IF;
 PERFORM 1 FROM public.mentor_profiles WHERE user_id=s.mentor_id FOR UPDATE;
 IF p_legacy_key IS NOT NULL THEN
  -- Look up the historical request before inspecting the current period. A replay never mutates it.
  SELECT b.* INTO e FROM public.subscription_billing_events b
   LEFT JOIN public.subscription_terminal_transitions x ON x.terminal_event_id=b.id
   WHERE x.legacy_request_key=p_legacy_key OR b.idempotency_key=p_legacy_key;
  IF e.id IS NOT NULL THEN
   IF e.subscription_id IS DISTINCT FROM s.id OR e.student_id IS DISTINCT FROM s.student_id OR e.mentor_id IS DISTINCT FROM s.mentor_id
    OR e.event_type IS DISTINCT FROM p_event_type OR e.status<>'succeeded' THEN RAISE EXCEPTION 'BILLING_EVENT_BINDING_MISMATCH'; END IF;
   RETURN jsonb_build_object('ok',true,'code','already_succeeded','billing_event_id',e.id);
  END IF;
  p_expected_period_end:=s.current_period_end;
  p_expected_last_billing_event_id:=s.last_billing_event_id;
 ELSE
  SELECT x.* INTO t FROM public.subscription_terminal_transitions x
   JOIN public.subscription_billing_events b ON b.id=x.terminal_event_id
   WHERE x.subscription_id=s.id AND b.period_end=p_expected_period_end AND b.event_type=p_event_type
    AND (x.expected_last_event_id IS NOT DISTINCT FROM p_expected_last_billing_event_id OR x.terminal_event_id=p_expected_last_billing_event_id);
  IF t.terminal_event_id IS NOT NULL THEN
   SELECT * INTO e FROM public.subscription_billing_events WHERE id=t.terminal_event_id;
   IF e.status<>'succeeded' OR e.student_id IS DISTINCT FROM s.student_id OR e.mentor_id IS DISTINCT FROM s.mentor_id THEN RAISE EXCEPTION 'BILLING_EVENT_BINDING_MISMATCH'; END IF;
   RETURN jsonb_build_object('ok',true,'code','already_succeeded','billing_event_id',e.id);
  END IF;
  -- A terminal committed by PR138 before this delta has no transition sidecar.
  -- Acknowledge that exact completed request without creating a mapping or
  -- touching today's period. A paid-event predecessor must identify a unique
  -- verified period; equal timestamps alone cannot distinguish a rejoin.
  SELECT * INTO e FROM public.subscription_billing_events b
   WHERE b.idempotency_key=CASE p_event_type WHEN 'canceled' THEN 'sub_cancel:' ELSE 'sub_expired:' END
     ||s.id::text||':'||to_char(p_expected_period_end AT TIME ZONE 'UTC','YYYY-MM-DD')
    AND b.period_end=p_expected_period_end;
  IF e.id IS NOT NULL THEN
   IF e.subscription_id IS DISTINCT FROM s.id OR e.student_id IS DISTINCT FROM s.student_id
    OR e.mentor_id IS DISTINCT FROM s.mentor_id OR e.event_type IS DISTINCT FROM p_event_type
    OR e.status<>'succeeded' THEN RAISE EXCEPTION 'BILLING_EVENT_BINDING_MISMATCH'; END IF;
   IF p_expected_last_billing_event_id=e.id THEN
    RETURN jsonb_build_object('ok',true,'code','already_succeeded','billing_event_id',e.id);
   END IF;
   SELECT count(*),coalesce(bool_or(b.id=p_expected_last_billing_event_id),false),
     count(*) FILTER (WHERE f.kind IN ('cash','verified_legacy_cash'))
    INTO v_matching_periods,v_expected_period_matches,v_matching_cash
    FROM public.subscription_billing_events b
    CROSS JOIN LATERAL (SELECT core_private.service_period_funding(b.id) kind OFFSET 0) f
    WHERE b.subscription_id=s.id AND b.student_id=s.student_id AND b.mentor_id=s.mentor_id
     AND b.event_type IN ('initial','renewal') AND f.kind IN ('cash','verified_legacy_cash','pg','voucher')
     AND ((b.period_start=e.period_start AND core_private.service_period_effective_end(b.id)=e.period_end)
      OR (f.kind='verified_legacy_cash' AND b.period_start=date_trunc('milliseconds',b.period_start)
       AND core_private.service_period_effective_end(b.id)=date_trunc('milliseconds',core_private.service_period_effective_end(b.id))
       AND b.period_start=date_trunc('milliseconds',e.period_start)
       AND core_private.service_period_effective_end(b.id)=date_trunc('milliseconds',e.period_end)));
   IF v_matching_periods=1 AND v_expected_period_matches THEN
    RETURN jsonb_build_object('ok',true,'code','already_succeeded','billing_event_id',e.id);
   END IF;
   -- Before grace expiry the recorded last event is normally the unsuccessful
   -- next renewal, not the paid period. It is a predecessor proof only: never
   -- classify this undebited attempt as a paid service period.
   IF v_matching_periods=1 AND v_matching_cash=1 AND EXISTS(
    SELECT 1 FROM public.subscription_billing_events failed
    WHERE failed.id=p_expected_last_billing_event_id AND failed.subscription_id=s.id
     AND failed.student_id=s.student_id AND failed.mentor_id=s.mentor_id
     AND failed.event_type='renewal_failed' AND failed.status='failed'
     AND failed.failure_code='insufficient_cash' AND failed.attempt_count>=1 AND failed.amount_cents>0
     AND failed.payment_id IS NULL AND failed.ledger_id IS NULL AND failed.voucher_redemption_id IS NULL
     AND (failed.funding_source IS NULL OR failed.funding_source='cash')
     AND failed.period_start=e.period_end AND failed.period_end>failed.period_start
     AND failed.processed_at<=e.processed_at AND failed.plan_tier=e.plan_tier
     AND failed.idempotency_key='sub_renewal:'||s.id::text||':'||to_char(e.period_end AT TIME ZONE 'UTC','YYYY-MM-DD')
     AND EXISTS(SELECT 1 FROM public.mentor_plans plan WHERE plan.id=failed.plan_id
       AND plan.mentor_id=s.mentor_id AND plan.plan_tier=failed.plan_tier)
     AND NOT EXISTS(SELECT 1 FROM public.cash_ledger ledger WHERE ledger.idempotency_key=failed.idempotency_key)
   ) THEN
    RETURN jsonb_build_object('ok',true,'code','already_succeeded','billing_event_id',e.id);
   END IF;
   RETURN jsonb_build_object('ok',false,'code','stale_transition');
  END IF;
 END IF;
 v_alias:=CASE p_event_type WHEN 'canceled' THEN 'sub_cancel:' ELSE 'sub_expired:' END||s.id::text||':'||to_char(s.current_period_end AT TIME ZONE 'UTC','YYYY-MM-DD');
 IF (p_legacy_key IS NOT NULL AND p_legacy_key IS DISTINCT FROM v_alias)
  OR p_expected_period_end IS NULL OR s.current_period_end IS DISTINCT FROM p_expected_period_end
  OR s.last_billing_event_id IS DISTINCT FROM p_expected_last_billing_event_id THEN RETURN jsonb_build_object('ok',false,'code','stale_transition'); END IF;
 IF s.status NOT IN ('active','past_due') OR s.current_period_end>p_processed_at
  OR (p_event_type='canceled' AND NOT coalesce(s.cancel_at_period_end,false))
  OR (p_event_type='expired' AND (s.status<>'past_due' OR s.grace_until IS NULL OR s.grace_until>p_processed_at OR s.cancel_at_period_end))
  THEN RETURN jsonb_build_object('ok',false,'code','not_terminal_eligible'); END IF;
 IF NOT core_private.current_standard_service_period_valid(s.id) THEN RETURN jsonb_build_object('ok',false,'code','SERVICE_PERIOD_FUNDING_UNRESOLVED'); END IF;
 v_key:='sub_terminal:'||s.current_service_period_event_id::text;
 IF EXISTS(SELECT 1 FROM public.subscription_terminal_transitions WHERE legacy_request_key=v_alias)
  OR EXISTS(SELECT 1 FROM public.subscription_billing_events WHERE idempotency_key=v_alias) THEN v_alias:=NULL; END IF;
 INSERT INTO public.subscription_billing_events(subscription_id,student_id,mentor_id,event_type,status,
  period_start,period_end,billing_at,plan_tier,plan_id,idempotency_key,processed_at,funding_source)
 VALUES(s.id,s.student_id,s.mentor_id,p_event_type,'succeeded',s.current_period_start,s.current_period_end,p_processed_at,
  s.plan_tier,s.plan_id,v_key,p_processed_at,s.funding_source) RETURNING * INTO e;
 INSERT INTO public.subscription_terminal_transitions(service_period_event_id,subscription_id,terminal_event_id,expected_last_event_id,legacy_request_key)
 VALUES(s.current_service_period_event_id,s.id,e.id,s.last_billing_event_id,v_alias);
 UPDATE public.subscriptions SET status='expired',expired_at=p_processed_at,next_billing_at=NULL,
  canceled_at=CASE WHEN p_event_type='canceled' THEN p_processed_at ELSE canceled_at END,
  last_billing_event_id=e.id,updated_at=p_processed_at WHERE id=s.id;
 RETURN jsonb_build_object('ok',true,'code','succeeded','billing_event_id',e.id);
END $function$

CREATE OR REPLACE FUNCTION core_private.guard_initial_subscription_billing_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if TG_OP='INSERT' and NEW.event_type='initial' and NEW.payment_id is not null then
  NEW.idempotency_key := 'sub_initial:'||NEW.subscription_id::text||':'||NEW.payment_id::text;
  -- Old web has already committed via v2, then sends a redundant service-role upsert.
  -- A zero-row result makes that old best-effort writer stop before its pointer update.
  if current_user in ('service_role','authenticated','anon') and exists(
   select 1 from public.subscription_billing_events where payment_id=NEW.payment_id and event_type='initial') then
   return null;
  end if;
 elsif TG_OP='UPDATE' and OLD.event_type='initial' and OLD.status in ('succeeded','refunded') then
  if row(NEW.subscription_id,NEW.student_id,NEW.mentor_id,NEW.event_type,NEW.period_start,NEW.period_end,
         NEW.billing_at,NEW.amount_cents,NEW.plan_tier,NEW.plan_id,NEW.ledger_id,NEW.payment_id,NEW.idempotency_key)
   is distinct from
     row(OLD.subscription_id,OLD.student_id,OLD.mentor_id,OLD.event_type,OLD.period_start,OLD.period_end,
         OLD.billing_at,OLD.amount_cents,OLD.plan_tier,OLD.plan_id,OLD.ledger_id,OLD.payment_id,OLD.idempotency_key) then
   raise exception 'INITIAL_BILLING_EVENT_IMMUTABLE';
  end if;
 end if;
 return NEW;
end $function$

CREATE OR REPLACE FUNCTION core_private.guard_service_period_extension()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e public.subscription_billing_events%ROWTYPE; a public.mentor_activity_events%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'SERVICE_PERIOD_EXTENSION_IMMUTABLE'; END IF;
 SELECT * INTO e FROM public.subscription_billing_events WHERE id=NEW.billing_event_id;
 SELECT * INTO a FROM public.mentor_activity_events WHERE id=NEW.mentor_activity_event_id;
 IF e.id IS NULL OR a.id IS NULL OR e.mentor_id IS DISTINCT FROM a.mentor_id
    OR a.event_type IS DISTINCT FROM 'pause_started' OR e.status IS DISTINCT FROM 'succeeded'
    OR e.event_type NOT IN ('initial','renewal') OR e.period_start IS NULL OR e.period_end IS NULL
    OR e.period_start>=e.period_end OR e.voucher_redemption_id IS NOT NULL
    OR (e.funding_source IS NOT NULL AND e.funding_source NOT IN ('cash','pg'))
    OR core_private.service_period_funding(e.id) NOT IN ('cash','verified_legacy_cash','pg')
    OR core_private.service_period_financial_state(e.id) IS DISTINCT FROM 'clear' THEN
   RAISE EXCEPTION 'SERVICE_PERIOD_EXTENSION_BINDING_INVALID';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION core_private.guard_subscription_refund_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.subscription_billing_events%rowtype; v_student uuid; v_mentor uuid; v_event uuid;
begin
 if new.subscription_id is null then return new; end if;
 select student_id,mentor_id into v_student,v_mentor from public.subscriptions where id=new.subscription_id;
 if not found or new.user_id is distinct from v_student then raise exception 'REFUND_PARTY_MISMATCH'; end if;
 if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtext(v_student::text),pg_catalog.hashtext(v_mentor::text)) then
  raise exception 'REFUND_RETRY_REQUIRED' using errcode='40001';
 end if;
 if new.billing_event_id is null and new.payment_id is not null then
  select case when count(*)=1 then (array_agg(id))[1] end into v_event from public.subscription_billing_events
  where subscription_id=new.subscription_id and payment_id=new.payment_id and status='succeeded' and event_type in ('initial','renewal');
  new.billing_event_id:=v_event;
 end if;
 if new.billing_event_id is null then
  if new.status in ('rejected','canceled') then return new; end if;
  raise exception 'SERVICE_PERIOD_UNRESOLVED';
 end if;
 perform core_private.lock_service_period_finance(new.billing_event_id);
 select * into e from public.subscription_billing_events where id=new.billing_event_id;
 if e.subscription_id is distinct from new.subscription_id or e.student_id is distinct from new.user_id or e.payment_id is distinct from new.payment_id then raise exception 'REFUND_PERIOD_BINDING_MISMATCH'; end if;
 if tg_op='UPDATE' and(old.billing_event_id is not null and new.billing_event_id is distinct from old.billing_event_id or new.subscription_id is distinct from old.subscription_id or new.user_id is distinct from old.user_id or new.payment_id is distinct from old.payment_id) then raise exception 'REFUND_IDENTITY_IMMUTABLE'; end if;
 if tg_op='UPDATE' and old.status='succeeded' and (new.status is distinct from old.status or new.amount_cents is distinct from old.amount_cents or new.pg_cancellation_id is distinct from old.pg_cancellation_id or new.pg_cancelled_at is distinct from old.pg_cancelled_at) then raise exception 'FINAL_REFUND_IMMUTABLE'; end if;
 if new.amount_cents is not null and (new.amount_cents<=0 or new.amount_cents>e.amount_cents) then raise exception 'REFUND_AMOUNT_INVALID'; end if;
 if new.status='succeeded' and new.amount_cents is null then raise exception 'REFUND_AMOUNT_UNRESOLVED'; end if;
 if new.status='succeeded' and new.amount_cents+(select coalesce(sum(f.amount_cents),0) from public.refunds f where f.billing_event_id=e.id and f.status='succeeded' and f.id<>new.id)>e.amount_cents then raise exception 'REFUND_TOTAL_EXCEEDED'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION core_private.lock_service_period_finance(p_event_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare e public.subscription_billing_events%rowtype; v_entitlement uuid;
begin
 select * into e from public.subscription_billing_events where id=p_event_id;
 if not found then raise exception 'SERVICE_PERIOD_NOT_FOUND'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(e.student_id::text),pg_catalog.hashtext(e.mentor_id::text));
 if e.voucher_redemption_id is not null then
  select entitlement_id into v_entitlement from public.voucher_redemptions where id=e.voucher_redemption_id;
  perform 1 from public.voucher_entitlements where id=v_entitlement for update;
 elsif e.payment_id is not null then perform 1 from public.payments where id=e.payment_id for update; end if;
 perform 1 from public.subscriptions where id=e.subscription_id for update;
 -- profile lock precedes event/item, also freezes payout account and pause/termination state.
 perform 1 from public.mentor_profiles where user_id=e.mentor_id for update;
 perform 1 from public.subscription_billing_events where id=e.id for update;
 if e.voucher_redemption_id is not null then perform 1 from public.voucher_redemptions where id=e.voucher_redemption_id for update; end if;
end $function$

CREATE OR REPLACE FUNCTION core_private.mentor_financial_transition_impl(p_mentor_id uuid, p_action text, p_days integer, p_reason text, p_pause_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_termination_effective_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 s public.subscriptions%rowtype; e public.subscription_billing_events%rowtype;
 mp public.mentor_profiles%rowtype; v_subscription_ids uuid[];
 v_now timestamptz; v_end timestamptz; v_pause_until timestamptz; v_effective_at timestamptz;
 v_count integer:=0; v_refunds integer:=0; v_plans integer:=0; v_notified integer:=0;
 v_amount bigint; v_days integer; v_activity_id uuid; v_event_status text;
BEGIN
 IF p_action IS NULL OR p_action NOT IN ('termination_start','termination_finalize','pause','resume','abandonment') THEN
  RAISE EXCEPTION 'INVALID_MENTOR_ACTION';
 END IF;
 SELECT coalesce(array_agg(id ORDER BY id),'{}'::uuid[]) INTO v_subscription_ids
 FROM public.subscriptions WHERE mentor_id=p_mentor_id;
 -- Global pair order before retaining any shared mentor/profile lock.
 FOR s IN SELECT * FROM public.subscriptions WHERE id=ANY(v_subscription_ids) ORDER BY student_id,id LOOP
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(s.student_id::text),pg_catalog.hashtext(s.mentor_id::text));
 END LOOP;
 FOR s IN SELECT * FROM public.subscriptions WHERE id=ANY(v_subscription_ids) ORDER BY student_id,id LOOP
  IF coalesce(s.current_service_period_event_id,s.last_billing_event_id) IS NOT NULL THEN
   SELECT * INTO e FROM public.subscription_billing_events WHERE id=coalesce(s.current_service_period_event_id,s.last_billing_event_id);
   IF e.subscription_id IS DISTINCT FROM s.id OR e.student_id IS DISTINCT FROM s.student_id OR e.mentor_id IS DISTINCT FROM s.mentor_id THEN
    RAISE EXCEPTION 'SERVICE_PERIOD_UNRESOLVED';
   END IF;
   PERFORM core_private.lock_service_period_finance(e.id);
  ELSE
   PERFORM 1 FROM public.subscriptions WHERE id=s.id FOR UPDATE;
  END IF;
 END LOOP;
 SELECT * INTO mp FROM public.mentor_profiles WHERE user_id=p_mentor_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','MENTOR_PROFILE_NOT_FOUND'); END IF;
 IF EXISTS(SELECT 1 FROM public.subscriptions WHERE mentor_id=p_mentor_id AND NOT(id=ANY(v_subscription_ids))) THEN
  RAISE EXCEPTION 'MENTOR_TRANSITION_RETRY_REQUIRED' USING errcode='40001';
 END IF;
 v_now:=clock_timestamp();
 IF p_action='termination_start' THEN
  IF mp.activity_status IN ('terminating','terminated') THEN RETURN jsonb_build_object('ok',false,'code','MENTOR_ALREADY_TERMINATING'); END IF;
  v_effective_at:=greatest(coalesce(p_termination_effective_at,v_now+interval '14 days'),v_now+interval '14 days');
  IF NOT isfinite(v_effective_at) OR v_effective_at>v_now+interval '90 days' THEN RETURN jsonb_build_object('ok',false,'code','TERMINATION_DATE_TOO_FAR','max_days',90); END IF;
 ELSIF p_action='resume' THEN
  IF mp.activity_status IS DISTINCT FROM 'paused' THEN RETURN jsonb_build_object('ok',false,'code','MENTOR_NOT_PAUSED'); END IF;
 ELSIF p_action='pause' THEN
  -- The installed app treats an elapsed scheduled pause as active. Preserve that
  -- behavior while still allowing an explicit resume for a paused profile.
  IF coalesce(mp.activity_status,'active')<>'active' AND NOT coalesce(mp.activity_status='paused' AND mp.pause_until<=v_now,false) THEN
   RETURN jsonb_build_object('ok',false,'code','MENTOR_NOT_ACTIVE');
  END IF;
  IF p_reason IS NULL OR p_reason NOT IN ('rest','illness') THEN RETURN jsonb_build_object('ok',false,'code','PAUSE_REASON_INVALID'); END IF;
  IF p_reason='rest' AND mp.last_pause_at IS NOT NULL
   AND mp.last_pause_at > ((v_now AT TIME ZONE 'Asia/Seoul'-interval '6 months') AT TIME ZONE 'Asia/Seoul') THEN
   RETURN jsonb_build_object('ok',false,'code','REST_FREQUENCY_LIMIT','last_pause_at',mp.last_pause_at,
     'next_available_at',((mp.last_pause_at AT TIME ZONE 'Asia/Seoul'+interval '6 months') AT TIME ZONE 'Asia/Seoul'));
  END IF;
  IF p_pause_until IS NOT NULL THEN
   IF NOT isfinite(p_pause_until) OR p_pause_until<=v_now THEN RETURN jsonb_build_object('ok',false,'code','PAUSE_UNTIL_INVALID'); END IF;
   IF p_pause_until>v_now+interval '7 days' THEN RETURN jsonb_build_object('ok',false,'code','PAUSE_TOO_LONG','max_days',7); END IF;
   v_days:=greatest(1,ceil(extract(epoch FROM(p_pause_until-v_now))/86400.0)::integer);
   IF v_days>7 THEN RETURN jsonb_build_object('ok',false,'code','PAUSE_TOO_LONG','max_days',7); END IF;
   v_pause_until:=p_pause_until;
  ELSE
   v_days:=least(7,greatest(1,coalesce(p_days,1)));
   v_pause_until:=v_now+v_days*interval '1 day';
  END IF;
 ELSIF p_action='termination_finalize' AND (mp.termination_effective_at IS NULL OR mp.termination_effective_at>v_now) THEN
  RETURN jsonb_build_object('ok',false,'code','TERMINATION_NOT_DUE');
 END IF;
 v_event_status:=CASE WHEN p_action='abandonment' OR(p_action='pause' AND p_reason='illness') THEN 'pending_review' ELSE 'logged' END;
 INSERT INTO public.mentor_activity_events(mentor_id,event_type,reason,detail,status)
 VALUES(p_mentor_id,CASE p_action WHEN 'termination_start' THEN 'termination_requested' WHEN 'termination_finalize' THEN 'termination_finalized'
  WHEN 'pause' THEN 'pause_started' WHEN 'resume' THEN 'pause_resumed' ELSE 'abandonment_suspected' END,
  p_reason,jsonb_build_object('days',v_days,'pause_until',v_pause_until),v_event_status) RETURNING id INTO v_activity_id;
 IF p_action='termination_start' THEN
  UPDATE public.mentor_profiles SET activity_status='terminating',termination_requested_at=v_now,termination_effective_at=v_effective_at WHERE user_id=p_mentor_id;
  UPDATE public.mentor_plans SET is_active=false WHERE mentor_id=p_mentor_id AND is_active IS DISTINCT FROM false;
  GET DIAGNOSTICS v_plans=ROW_COUNT;
  SELECT count(*) INTO v_notified FROM public.subscriptions WHERE mentor_id=p_mentor_id AND status IN ('active','past_due');
 ELSIF p_action='resume' THEN
  UPDATE public.mentor_profiles SET activity_status='active',pause_until=NULL WHERE user_id=p_mentor_id;
  UPDATE public.mentor_plans SET is_active=true WHERE mentor_id=p_mentor_id AND is_active IS DISTINCT FROM true;
  GET DIAGNOSTICS v_plans=ROW_COUNT;
 ELSIF p_action='pause' THEN
  UPDATE public.mentor_profiles SET activity_status='paused',pause_started_at=v_now,pause_until=v_pause_until,pause_reason=p_reason,
   last_pause_at=CASE WHEN p_reason='rest' THEN v_now ELSE last_pause_at END WHERE user_id=p_mentor_id;
  FOR s IN SELECT * FROM public.subscriptions WHERE mentor_id=p_mentor_id AND status IN ('active','past_due') ORDER BY student_id,id LOOP
   SELECT * INTO e FROM public.subscription_billing_events WHERE id=coalesce(s.current_service_period_event_id,s.last_billing_event_id);
   v_end:=core_private.service_period_effective_end(e.id);
   IF e.id IS NULL OR e.status<>'succeeded' OR v_end IS NULL
    OR NOT core_private.service_period_matches_subscription(s.id,e.id) THEN
    RAISE EXCEPTION 'SERVICE_PERIOD_UNRESOLVED';
   END IF;
   IF e.voucher_redemption_id IS NOT NULL OR s.funding_source='voucher' THEN
    INSERT INTO public.service_period_financial_holds(billing_event_id,state,reason)
    VALUES(e.id,'hold','voucher_pause_allocation_unresolved') ON CONFLICT(billing_event_id) DO NOTHING;
   ELSE
    IF EXISTS(SELECT 1 FROM public.subscription_settlement_items WHERE billing_event_id=e.id AND status='paid') THEN
     RAISE EXCEPTION 'SERVICE_PERIOD_PAID_EXTENSION_REVIEW_REQUIRED';
    END IF;
    INSERT INTO public.service_period_extensions(billing_event_id,mentor_activity_event_id,extension_seconds)
    VALUES(e.id,v_activity_id,v_days::bigint*86400);
    UPDATE public.subscriptions SET current_period_end=core_private.service_period_effective_end(e.id),
     next_billing_at=coalesce(next_billing_at,v_end)+v_days*interval '1 day',updated_at=v_now WHERE id=s.id;
    v_count:=v_count+1;
   END IF;
  END LOOP;
 ELSE
  FOR s IN SELECT * FROM public.subscriptions WHERE mentor_id=p_mentor_id AND status IN ('active','past_due') ORDER BY student_id,id LOOP
   SELECT * INTO e FROM public.subscription_billing_events WHERE id=coalesce(s.current_service_period_event_id,s.last_billing_event_id);
   v_end:=core_private.service_period_effective_end(e.id);
   IF e.id IS NULL OR v_end IS NULL THEN RAISE EXCEPTION 'SERVICE_PERIOD_UNRESOLVED'; END IF;
   INSERT INTO public.service_period_financial_holds(billing_event_id,state,reason)
   VALUES(e.id,'hold',CASE WHEN p_action='abandonment' THEN 'mentor_abandonment_unresolved' ELSE 'mentor_termination_allocation_unresolved' END)
   ON CONFLICT(billing_event_id) DO NOTHING;
   IF NOT core_private.subscription_has_pending_refund(s.id) THEN
    -- Preserve the established cash remaining-time formula. Voucher allocation
    -- remains undecided: no invented cash value or automatic payout release.
    v_amount:=CASE WHEN e.voucher_redemption_id IS NOT NULL THEN NULL ELSE
     floor(e.amount_cents::numeric*least(1,greatest(0,extract(epoch FROM(v_end-v_now)))/nullif(extract(epoch FROM(v_end-e.period_start)),0)))::bigint END;
    IF e.voucher_redemption_id IS NOT NULL OR v_amount>0 THEN
     INSERT INTO public.refunds(user_id,subscription_id,billing_event_id,payment_id,amount_cents,status,request_type,reason)
     VALUES(e.student_id,e.subscription_id,e.id,e.payment_id,v_amount,'pending','subscription_mentor_suspended','Mentor termination: service period review required');
     v_refunds:=v_refunds+1;
    END IF;
   END IF;
   UPDATE public.subscriptions SET status='canceled',cancel_at_period_end=false,canceled_at=v_now,next_billing_at=NULL,updated_at=v_now WHERE id=s.id;
   v_count:=v_count+1;
  END LOOP;
  UPDATE public.mentor_profiles SET activity_status='terminated',abandonment_flagged_at=CASE WHEN p_action='abandonment' THEN v_now ELSE abandonment_flagged_at END WHERE user_id=p_mentor_id;
  UPDATE public.mentor_plans SET is_active=false WHERE mentor_id=p_mentor_id;
 END IF;
 UPDATE public.mentor_activity_events SET detail=jsonb_build_object('subscriptions',v_count,'refunds_created',v_refunds,'days',v_days,'pause_until',v_pause_until,'effective_at',v_effective_at) WHERE id=v_activity_id;
 -- Only this mentor's items; paid economics and period snapshots stay immutable.
 UPDATE public.subscription_settlement_items i SET
 status=CASE WHEN core_private.service_period_effective_end(be.id) IS NULL THEN 'hold'
  WHEN EXISTS(SELECT 1 FROM public.service_period_financial_holds h WHERE h.billing_event_id=be.id) THEN 'hold'
  WHEN core_private.service_period_financial_state(be.id)='refunded' THEN 'canceled'
  WHEN core_private.service_period_financial_state(be.id)<>'clear' OR p_action<>'resume' THEN 'hold'
  WHEN core_private.service_period_effective_end(be.id)>v_now THEN 'accruing' ELSE 'pending' END,
 hold_reason=CASE WHEN EXISTS(SELECT 1 FROM public.service_period_financial_holds h WHERE h.billing_event_id=be.id)
  THEN (SELECT h.reason FROM public.service_period_financial_holds h WHERE h.billing_event_id=be.id)
  WHEN core_private.service_period_effective_end(be.id) IS NULL THEN 'service_period_unresolved'
  WHEN p_action<>'resume' THEN 'mentor_activity_unresolved' ELSE NULL END,
 period_start=be.period_start,period_end=core_private.service_period_effective_end(be.id),updated_at=v_now
 FROM public.subscription_billing_events be WHERE be.id=i.billing_event_id AND i.mentor_id=p_mentor_id AND i.status<>'paid';
 RETURN jsonb_build_object('ok',true,'event_id',v_activity_id,'event_status',v_event_status,
  'summary',jsonb_build_object('refundsCreated',v_refunds,'subscriptions',v_count,'subscriptionsExtended',CASE WHEN p_action='pause' THEN v_count ELSE 0 END,
   'days',v_days,'pauseUntil',v_pause_until,'effectiveAt',v_effective_at,'plansChanged',v_plans,'notifiedSubscribers',v_notified));
END $function$

CREATE OR REPLACE FUNCTION core_private.process_subscription_renewal_impl(p_subscription_id uuid, p_period_end timestamp with time zone, p_idempotency_key text, p_processed_at timestamp with time zone DEFAULT now(), p_legacy_millisecond boolean DEFAULT false)
 RETURNS TABLE(ok boolean, code text, message text, billing_event_id uuid, ledger_id uuid, next_period_start timestamp with time zone, next_period_end timestamp with time zone, wallet_balance_cents bigint, attempt_count integer)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 s public.subscriptions%rowtype; p public.mentor_plans%rowtype;
 e public.subscription_billing_events%rowtype; l public.cash_ledger%rowtype;
 v_student uuid; v_mentor uuid; v_amount bigint; v_balance bigint; v_end timestamptz;
 v_key text; v_notice public.subscription_billing_events%rowtype;
begin
 if p_subscription_id is null or p_period_end is null or p_processed_at is null then
   return query select false,'invalid_subscription'::text,'subscription, period and time are required'::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;
 end if;
 v_key := 'sub_renewal:'||p_subscription_id::text||':'||to_char(p_period_end at time zone 'UTC','YYYY-MM-DD');
 if p_idempotency_key is distinct from v_key or char_length(p_idempotency_key)>128 then
   return query select false,'invalid_idempotency_key'::text,'key must identify this subscription period'::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;
 end if;
 -- Match checkout's pair mutex before row locks. No stale client snapshot decides eligibility.
 select student_id,mentor_id into v_student,v_mentor from public.subscriptions where id=p_subscription_id;
 if v_student is null then
   return query select false,'not_found'::text,'subscription not found'::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;
 end if;
 perform pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
 select * into s from public.subscriptions where id=p_subscription_id for update;
 if s.id is null or s.student_id is distinct from v_student or s.mentor_id is distinct from v_mentor then
   raise exception 'SUBSCRIPTION_BINDING_MISMATCH';
 end if;
 perform 1 from public.mentor_profiles where user_id=s.mentor_id for update;
 select * into e from public.subscription_billing_events where idempotency_key=v_key for update;
 -- Older web normalizes timestamps through JS Date (millisecond precision). Bind
 -- to the locked subscription, or the original event on replay, without rounding
 -- stored financial periods. A different millisecond is still a stale request.
 if p_legacy_millisecond then
 if e.id is not null and e.subscription_id=s.id
    and date_trunc('milliseconds',e.period_start)=date_trunc('milliseconds',p_period_end) then
  p_period_end := e.period_start;
 elsif e.id is null
    and date_trunc('milliseconds',s.current_period_end)=date_trunc('milliseconds',p_period_end) then
  p_period_end := s.current_period_end;
 end if;
 end if;
 if e.id is not null then
   if e.subscription_id is distinct from s.id or e.student_id is distinct from s.student_id
      or e.mentor_id is distinct from s.mentor_id or e.period_start is distinct from p_period_end
      or e.event_type not in ('renewal','renewal_failed') then
     raise exception 'BILLING_EVENT_BINDING_MISMATCH';
   end if;
   if e.status='succeeded' then
     select * into l from public.cash_ledger where id=e.ledger_id;
     if l.id is null or l.delta_cents is distinct from -e.amount_cents::bigint
        or l.user_id is distinct from s.student_id or l.ref_id is distinct from s.id
        or l.idempotency_key is distinct from v_key or l.reason is distinct from 'subscription_renewal' then
       raise exception 'LEDGER_BINDING_MISMATCH';
     end if;
     return query select true,'already_succeeded'::text,'renewal already processed'::text,e.id,l.id,e.period_start,e.period_end,null::bigint,e.attempt_count; return;
   end if;
   if e.status not in ('failed','skipped') then
     return query select false,'already_processing'::text,'renewal is already processing'::text,e.id,e.ledger_id,e.period_start,e.period_end,null::bigint,e.attempt_count; return;
   end if;
 end if;
 if s.funding_source is not null and s.funding_source<>'cash' then
   return query select false,'not_cash_subscription'::text,'cash renewal is unavailable for this funding source'::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,0; return;
 end if;
 if not core_private.current_cash_service_period_valid(s.id) then
   return query select false,'SERVICE_PERIOD_FUNDING_UNRESOLVED'::text,'service period funding must be verified'::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,0; return;
 end if;
 if s.status not in ('active','past_due') or s.cancel_at_period_end
    or (s.status='past_due' and s.grace_until is not null and s.grace_until<=p_processed_at)
    or s.current_period_end is distinct from p_period_end or s.next_billing_at is null
    or s.next_billing_at>p_processed_at or p_period_end>p_processed_at then
   return query select false,'not_renewal_eligible'::text,'subscription state or period changed'::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;
 end if;
 select * into p from public.mentor_plans where id=s.plan_id for share;
 if p.id is null or p.mentor_id is distinct from s.mentor_id or p.plan_tier is distinct from s.plan_tier
    or p.amount_cents is null or p.amount_cents<=0 or p.amount_cents%100<>0 then
   e := core_private.record_subscription_renewal_block(s.id,'price_unavailable',v_key,p_processed_at);
   return query select false,'price_unavailable'::text,'plan price or binding unavailable'::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;
 end if;
 -- is_active controls NEW subscriptions only. Existing subscriptions may renew.
 v_amount := p.amount_cents;
 select * into v_notice from public.subscription_billing_events
  where idempotency_key='sub_renewal_notice:'||s.id::text||':'||to_char(p_period_end at time zone 'UTC','YYYY-MM-DD');
 if v_notice.id is not null and (v_notice.amount_cents is distinct from v_amount
    or v_notice.plan_id is distinct from p.id or v_notice.plan_tier is distinct from p.plan_tier) then
   e := core_private.record_subscription_renewal_block(s.id,'price_changed_since_notice',v_key,p_processed_at);
   return query select false,'price_changed_since_notice'::text,'renewal price differs from the sent notice'::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;
 end if;
 if exists(select 1 from public.cash_ledger where idempotency_key=v_key) then
   raise exception 'LEDGER_WITHOUT_SUCCEEDED_EVENT';
 end if;
 v_end := ((p_period_end at time zone 'Asia/Seoul' + interval '1 month') at time zone 'Asia/Seoul');
 if e.id is null then
   insert into public.subscription_billing_events
    (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,
     amount_cents,plan_tier,plan_id,idempotency_key,attempt_count,created_at,funding_source)
   values(s.id,s.student_id,s.mentor_id,'renewal','processing',p_period_end,v_end,p_processed_at,
          v_amount,p.plan_tier,p.id,v_key,1,p_processed_at,'cash') returning * into e;
 else
   update public.subscription_billing_events b set event_type='renewal',status='processing',funding_source='cash',
     amount_cents=v_amount,plan_id=p.id,plan_tier=p.plan_tier,billing_at=p_processed_at,
     attempt_count=b.attempt_count+1,processed_at=null,failure_code=null,failure_message=null
   where b.id=e.id returning b.* into e;
 end if;
 insert into public.cash_wallets(user_id,balance_cents) values(s.student_id,0) on conflict(user_id) do nothing;
 update public.cash_wallets w set balance_cents=w.balance_cents-v_amount
   where w.user_id=s.student_id and w.balance_cents>=v_amount returning w.balance_cents into v_balance;
 if not found then
   update public.subscription_billing_events b set event_type='renewal_failed',status='failed',
     failure_code='insufficient_cash',failure_message='CASH_INSUFFICIENT',processed_at=p_processed_at where b.id=e.id;
   update public.subscriptions set status='past_due',grace_until=coalesce(grace_until,p_processed_at+interval '2 days'),
     updated_at=p_processed_at,last_billing_event_id=e.id where id=s.id;
   return query select false,'insufficient_cash'::text,'CASH_INSUFFICIENT'::text,e.id,null::uuid,p_period_end,v_end,null::bigint,e.attempt_count; return;
 end if;
 insert into public.cash_ledger(user_id,delta_cents,reason,ref_type,ref_id,idempotency_key,created_at)
 values(s.student_id,-v_amount,'subscription_renewal','subscriptions',s.id,v_key,p_processed_at) returning * into l;
 update public.subscription_billing_events b set event_type='renewal',status='succeeded',ledger_id=l.id,
   processed_at=p_processed_at,failure_code=null,failure_message=null where b.id=e.id;
 update public.subscriptions set status='active',funding_source='cash',current_period_start=p_period_end,current_period_end=v_end,
   next_billing_at=v_end,last_renewed_at=p_processed_at,last_billing_event_id=e.id,current_service_period_event_id=e.id,grace_until=null,updated_at=p_processed_at where id=s.id;
 return query select true,'succeeded'::text,'renewal processed'::text,e.id,l.id,p_period_end,v_end,v_balance,e.attempt_count;
end $function$

CREATE OR REPLACE FUNCTION core_private.qna_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_thread uuid;
BEGIN
 IF TG_TABLE_NAME='question_threads' THEN
   IF TG_OP='UPDATE' AND (NEW.service_period_event_id IS DISTINCT FROM OLD.service_period_event_id OR NEW.mentor_student_room_id IS DISTINCT FROM OLD.mentor_student_room_id) THEN RAISE EXCEPTION 'SERVICE_PERIOD_IMMUTABLE'; END IF;
   IF TG_OP='INSERT' AND public.qna_is_direct_untrusted_writer() AND (NEW.service_period_event_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.mentor_student_rooms r JOIN public.subscriptions v ON v.student_id=r.student_id AND v.mentor_id=r.mentor_id WHERE r.id=NEW.mentor_student_room_id AND (v.funding_source='voucher' OR v.current_service_period_event_id IS NOT NULL))) THEN RAISE EXCEPTION 'QNA_USE_RPC'; END IF;
   IF TG_OP='INSERT' AND NEW.service_period_event_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.subscription_billing_events e JOIN public.mentor_student_rooms r ON r.student_id=e.student_id AND r.mentor_id=e.mentor_id WHERE e.id=NEW.service_period_event_id AND r.id=NEW.mentor_student_room_id) THEN RAISE EXCEPTION 'SERVICE_PERIOD_PARTY_INVALID'; END IF;
 ELSE
   IF TG_OP='UPDATE' AND NEW.thread_id IS DISTINCT FROM OLD.thread_id THEN RAISE EXCEPTION 'THREAD_BINDING_IMMUTABLE'; END IF;
   v_thread:=NEW.thread_id;
   IF public.qna_is_direct_untrusted_writer() AND EXISTS(SELECT 1 FROM public.question_threads WHERE id=v_thread AND service_period_event_id IS NOT NULL) THEN RAISE EXCEPTION 'QNA_USE_RPC'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION core_private.qna_lock_thread_write(p_thread uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_student uuid; v_mentor uuid; v_sub uuid; v_event uuid; v_redemption uuid; v_entitlement uuid; v_payment uuid; v_status text; v_at timestamptz; v_code text; v_actor uuid:=auth.uid();
BEGIN
 SELECT r.student_id,r.mentor_id,t.service_period_event_id INTO v_student,v_mentor,v_event
 FROM public.question_threads t JOIN public.mentor_student_rooms r ON r.id=t.mentor_student_room_id WHERE t.id=p_thread;
 IF NOT FOUND THEN RAISE EXCEPTION 'THREAD_NOT_FOUND'; END IF;
 IF v_actor IS NULL OR v_actor NOT IN(v_student,v_mentor) THEN RAISE EXCEPTION 'NOT_ROOM_PARTY'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
 IF v_event IS NOT NULL THEN
   -- The shared finance adapter owns the global row-lock order.
   PERFORM core_private.lock_service_period_finance(v_event);
 ELSE
   SELECT id INTO v_sub FROM public.subscriptions WHERE student_id=v_student AND mentor_id=v_mentor AND status='active' ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
   PERFORM 1 FROM public.mentor_profiles WHERE user_id=v_mentor FOR UPDATE;
 END IF;
 SELECT status INTO v_status FROM public.question_threads WHERE id=p_thread FOR UPDATE;
 v_at := clock_timestamp();
 IF v_status NOT IN('pending','open','answered') THEN RAISE EXCEPTION 'THREAD_LOCKED'; END IF;
 v_code := core_private.qna_pair_write_eligibility(v_student,v_mentor,v_actor,v_at);
 IF v_code<>'allowed' THEN RAISE EXCEPTION '%',v_code; END IF;
 IF v_event IS NOT NULL THEN
   v_code := core_private.service_period_eligibility(v_event,v_actor,p_action,v_at);
   IF v_code<>'allowed' THEN RAISE EXCEPTION '%',v_code; END IF;
 ELSIF v_sub IS NOT NULL THEN
   IF public.qna_subscription_has_live_refund(v_sub) THEN RAISE EXCEPTION 'SUBSCRIPTION_REFUND_PENDING'; END IF;
 ELSIF NOT EXISTS(SELECT 1 FROM public.free_question_usage WHERE thread_id=p_thread AND student_id=v_student) THEN
   -- Historical unbound cash threads retain existing completion behavior; voucher never has NULL binding.
   IF EXISTS(SELECT 1 FROM public.voucher_redemptions WHERE student_id=v_student AND mentor_id=v_mentor) THEN RAISE EXCEPTION 'SERVICE_PERIOD_UNBOUND'; END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION core_private.qna_pair_write_eligibility(p_student uuid, p_mentor uuid, p_actor uuid, p_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF p_actor IS NULL OR p_actor NOT IN (p_student,p_mentor) THEN RETURN 'NOT_ROOM_PARTY'; END IF;
 IF EXISTS(SELECT 1 FROM public.users WHERE id=p_actor AND status='banned') THEN RETURN 'ACCOUNT_BANNED'; END IF;
 IF EXISTS(SELECT 1 FROM public.users WHERE id=p_actor AND status='suspended' AND (suspended_until IS NULL OR suspended_until>p_at)) THEN RETURN 'ACCOUNT_SUSPENDED'; END IF;
 IF EXISTS(SELECT 1 FROM public.users WHERE id IN(p_student,p_mentor) AND (lower(coalesce(status,'')) NOT IN('active','suspended') OR (status='suspended' AND (suspended_until IS NULL OR suspended_until>p_at)))) THEN RETURN 'ACCOUNT_NOT_ACTIVE'; END IF;
 IF (SELECT count(*) FROM public.users WHERE id IN(p_student,p_mentor))<>2 THEN RETURN 'ACCOUNT_NOT_ACTIVE'; END IF;
 IF public.account_deletion_write_blocked(p_actor) THEN RETURN 'ACCOUNT_DELETION_IN_PROGRESS'; END IF;
 IF public.qna_users_blocked(p_student,p_mentor) THEN RETURN 'BLOCKED'; END IF;
 IF NOT public.individual_question_user_is_approved_mentor(p_mentor) THEN RETURN 'MENTOR_NOT_APPROVED'; END IF;
 RETURN 'allowed';
END $function$

CREATE OR REPLACE FUNCTION core_private.qna_voucher_weekly_usage(p_event uuid, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_start timestamptz; v_end timestamptz; v_week timestamptz; v_used integer;
BEGIN
 SELECT r.service_start,r.service_end INTO v_start,v_end FROM public.subscription_billing_events e JOIN public.voucher_redemptions r ON r.id=e.voucher_redemption_id WHERE e.id=p_event;
 IF NOT FOUND OR p_at IS NULL OR p_at<v_start THEN RAISE EXCEPTION 'SERVICE_PERIOD_INVALID'; END IF;
 v_week:=v_start+floor(extract(epoch from(least(p_at,v_end-interval '1 microsecond')-v_start))/604800)::integer*interval '7 days';
 SELECT count(*) INTO v_used FROM public.question_threads WHERE service_period_event_id=p_event AND created_at>=v_week AND created_at<least(v_week+interval '7 days',v_end);
 RETURN jsonb_build_object('used',v_used,'limit',9,'remaining',case when p_at<v_end then greatest(0,9-v_used) else 0 end,'can_ask',p_at<v_end and v_used<9,'week_start',v_week,'week_end',least(v_week+interval '7 days',v_end));
END $function$

CREATE OR REPLACE FUNCTION core_private.record_cash_topup_impl(p_user_id uuid, p_amount_cents bigint, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_idem   text;
  v_new_id uuid;
  v_wu     int;
  v_id     uuid;
  v_user   uuid;
  v_delta  bigint;
  v_reason text;
  v_rtype  text;
  v_rid    uuid;
  v_key    text;
BEGIN
  -- 검증 4종 — 020 레거시와 동일 메시지·동일 순서(2층 관측 계약 불변)
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required';
  END IF;
  v_idem := nullif(trim(coalesce(p_idempotency_key, '')), '');
  IF v_idem IS NULL OR length(v_idem) = 0 THEN
    RAISE EXCEPTION 'p_idempotency_key is required';
  END IF;
  IF p_amount_cents IS NULL OR p_amount_cents <= 0 THEN
    RAISE EXCEPTION 'p_amount_cents must be positive';
  END IF;
  IF p_amount_cents > 1000000000 THEN
    RAISE EXCEPTION 'p_amount_too_large';
  END IF;

  -- ① 원자 판정 — 사전 SELECT 로 신규/duplicate 를 추정하는 구현은 금지(§7 F11 1층)
  INSERT INTO public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
  VALUES (p_user_id, p_amount_cents, 'cash_topup', 'topup', NULL, v_idem)
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_new_id;

  IF v_new_id IS NOT NULL THEN
    -- ② 신규 INSERT 일 때만 지갑 upsert·잔액 가산 (row_count=0 → 예외 — 부분 실패 전파)
    INSERT INTO public.cash_wallets (user_id, balance_cents)
    VALUES (p_user_id, 0)
    ON CONFLICT (user_id) DO NOTHING;
    UPDATE public.cash_wallets w
       SET balance_cents = w.balance_cents + p_amount_cents
     WHERE w.user_id = p_user_id;
    GET DIAGNOSTICS v_wu = ROW_COUNT;
    IF coalesce(v_wu, 0) = 0 THEN
      RAISE EXCEPTION 'CASH_WALLET_UPSERT_FAILED' USING ERRCODE = 'P0001';
    END IF;
    RETURN jsonb_build_object(
      'ledger_id', v_new_id, 'inserted', true, 'user_id', p_user_id,
      'delta_cents', p_amount_cents, 'reason', 'cash_topup', 'ref_type', 'topup',
      'ref_id', NULL, 'idempotency_key', v_idem);
  END IF;

  -- ③ duplicate: 지갑 갱신 금지 ④ 기존 행 FOR UPDATE 재조회 ⑤ 8필드 내부 형상 반환
  SELECT l.id, l.user_id, l.delta_cents, l.reason, l.ref_type, l.ref_id, l.idempotency_key
    INTO v_id, v_user, v_delta, v_reason, v_rtype, v_rid, v_key
    FROM public.cash_ledger l
   WHERE l.idempotency_key = v_idem
   FOR UPDATE;
  RETURN jsonb_build_object(
    'ledger_id', v_id, 'inserted', false, 'user_id', v_user,
    'delta_cents', v_delta, 'reason', v_reason, 'ref_type', v_rtype,
    'ref_id', v_rid, 'idempotency_key', v_key);
END $function$

CREATE OR REPLACE FUNCTION core_private.record_initial_subscription_billing_event(p_payment_id uuid, p_subscription_id uuid, p_set_latest boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  p public.payments%rowtype; s public.subscriptions%rowtype; l public.cash_ledger%rowtype;
  e public.subscription_billing_events%rowtype;
  v_tier text; v_key text := 'sub_initial:' || p_subscription_id::text || ':' || p_payment_id::text;
  v_start timestamptz; v_end timestamptz;
begin
  select * into strict p from public.payments where id = p_payment_id;
  select * into strict s from public.subscriptions where id = p_subscription_id for update;
  select * into l from public.cash_ledger where idempotency_key = 'sub_debit_' || p_payment_id::text;
  if l.id is null or l.user_id is distinct from p.user_id or l.ref_id is distinct from s.id
     or l.ref_type is distinct from 'subscriptions' or l.reason is distinct from 'subscription_payment'
     or l.delta_cents is distinct from -(p.amount * 100)::bigint
     or s.student_id is distinct from p.user_id or s.mentor_id is distinct from p.mentor_id
     or p.status not in ('succeeded','paid','success','complete','captured') then
    raise exception 'BILLING_EVENT_BINDING_MISMATCH';
  end if;
  select plan_tier into v_tier from public.mentor_plans where id = p.plan_id and mentor_id = p.mentor_id;
  if v_tier is null then raise exception 'PLAN_BINDING_MISMATCH'; end if;
  select * into e from public.subscription_billing_events
    where payment_id = p.id and event_type = 'initial' order by created_at, id limit 1;
  if e.id is not null then
    if e.subscription_id is distinct from s.id or e.ledger_id is distinct from l.id
       or e.amount_cents is distinct from -l.delta_cents or e.plan_id is distinct from p.plan_id
       or e.status not in ('succeeded', 'refunded') then
      raise exception 'BILLING_EVENT_BINDING_MISMATCH';
    end if;
    return e.id;
  end if;
  -- Checkout and its debit both use transaction now(). Never infer an old payment's
  -- period from subscriptions.current_period_*: cash renewals do not change last_payment_id.
  v_start := l.created_at;
  v_end := ((v_start at time zone 'Asia/Seoul' + interval '1 month') at time zone 'Asia/Seoul');
  insert into public.subscription_billing_events
    (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,
     amount_cents,plan_tier,plan_id,idempotency_key,ledger_id,payment_id,processed_at,funding_source)
  values (s.id,p.user_id,p.mentor_id,'initial','succeeded',v_start,v_end,l.created_at,
          -l.delta_cents,v_tier,p.plan_id,v_key,l.id,p.id,l.created_at,'cash')
  returning * into e;
  if p_set_latest and s.last_payment_id = p.id then
    update public.subscriptions set last_billing_event_id = e.id, current_service_period_event_id=e.id where id = s.id;
  end if;
  return e.id;
end $function$

CREATE OR REPLACE FUNCTION core_private.record_subscription_renewal_notice_impl(p_subscription_id uuid, p_period_end timestamp with time zone, p_at timestamp with time zone, p_legacy_millisecond boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE s public.subscriptions%ROWTYPE; p public.mentor_plans%ROWTYPE;
 e public.subscription_billing_events%ROWTYPE; v_key text; v_student uuid; v_mentor uuid;
BEGIN
 IF p_subscription_id IS NULL OR p_period_end IS NULL OR p_at IS NULL THEN RETURN jsonb_build_object('ok',false,'code','not_notice_eligible'); END IF;
 SELECT student_id,mentor_id INTO v_student,v_mentor FROM public.subscriptions WHERE id=p_subscription_id;
 IF v_student IS NULL THEN RETURN jsonb_build_object('ok',false,'code','not_notice_eligible'); END IF;
 PERFORM pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
 SELECT * INTO s FROM public.subscriptions WHERE id=p_subscription_id FOR UPDATE;
 IF s.student_id IS DISTINCT FROM v_student OR s.mentor_id IS DISTINCT FROM v_mentor THEN RAISE EXCEPTION 'SUBSCRIPTION_BINDING_MISMATCH'; END IF;
 PERFORM 1 FROM public.mentor_profiles WHERE user_id=s.mentor_id FOR UPDATE;
 v_key:='sub_renewal_notice:'||s.id::text||':'||to_char(p_period_end AT TIME ZONE 'UTC','YYYY-MM-DD');
 SELECT * INTO e FROM public.subscription_billing_events WHERE idempotency_key=v_key FOR UPDATE;
 IF p_legacy_millisecond THEN
  IF e.id IS NOT NULL AND date_trunc('milliseconds',e.period_end)=date_trunc('milliseconds',p_period_end) THEN p_period_end:=e.period_end;
  ELSIF e.id IS NULL AND date_trunc('milliseconds',s.current_period_end)=date_trunc('milliseconds',p_period_end) THEN p_period_end:=s.current_period_end; END IF;
 END IF;
 IF e.id IS NOT NULL THEN
  IF ROW(e.subscription_id,e.student_id,e.mentor_id,e.period_end,e.event_type,e.status,e.failure_code)
   IS DISTINCT FROM ROW(s.id,s.student_id,s.mentor_id,p_period_end,'renewal'::text,'skipped'::text,'pre_renewal_notice_sent'::text)
   THEN RAISE EXCEPTION 'BILLING_EVENT_BINDING_MISMATCH'; END IF;
  RETURN jsonb_build_object('ok',true,'code','already','billing_event_id',e.id,'amount_cents',e.amount_cents,
   'plan_id',e.plan_id,'plan_tier',e.plan_tier,'period_end',e.period_end);
 END IF;
 IF s.status<>'active' OR s.cancel_at_period_end OR s.current_period_end IS DISTINCT FROM p_period_end
  OR s.next_billing_at IS NULL OR s.next_billing_at<=p_at THEN RETURN jsonb_build_object('ok',false,'code','not_notice_eligible'); END IF;
 IF NOT core_private.current_cash_service_period_valid(s.id) THEN RETURN jsonb_build_object('ok',false,'code','SERVICE_PERIOD_FUNDING_UNRESOLVED'); END IF;
 SELECT * INTO p FROM public.mentor_plans WHERE id=s.plan_id FOR SHARE;
 IF p.id IS NULL OR p.mentor_id IS DISTINCT FROM s.mentor_id OR p.plan_tier IS DISTINCT FROM s.plan_tier
  OR p.amount_cents IS NULL OR p.amount_cents<=0 OR p.amount_cents%100<>0 THEN RETURN jsonb_build_object('ok',false,'code','price_unavailable'); END IF;
 INSERT INTO public.subscription_billing_events
  (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,amount_cents,plan_tier,plan_id,
   idempotency_key,failure_code,failure_message,attempt_count,created_at,processed_at,funding_source)
 VALUES(s.id,s.student_id,s.mentor_id,'renewal','skipped',s.current_period_start,s.current_period_end,s.next_billing_at,p.amount_cents,p.plan_tier,p.id,
  v_key,'pre_renewal_notice_sent','pre-renewal notice marker',0,p_at,p_at,'cash') RETURNING * INTO e;
 RETURN jsonb_build_object('ok',true,'code','sent','billing_event_id',e.id,'amount_cents',e.amount_cents,
  'plan_id',e.plan_id,'plan_tier',e.plan_tier,'period_end',e.period_end);
END $function$

CREATE OR REPLACE FUNCTION core_private.service_period_effective_end(p_event_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e public.subscription_billing_events%ROWTYPE; v_seconds bigint;
BEGIN
 SELECT * INTO e FROM public.subscription_billing_events WHERE id=p_event_id;
 IF NOT FOUND OR e.event_type NOT IN ('initial','renewal') OR e.period_start IS NULL
    OR e.period_end IS NULL OR e.period_start>=e.period_end THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM public.service_period_extensions x
   JOIN public.mentor_activity_events a ON a.id=x.mentor_activity_event_id
   WHERE x.billing_event_id=e.id AND (a.mentor_id IS DISTINCT FROM e.mentor_id
     OR a.event_type IS DISTINCT FROM 'pause_started' OR e.funding_source='voucher'
     OR e.voucher_redemption_id IS NOT NULL)) THEN RETURN NULL; END IF;
 SELECT coalesce(sum(extension_seconds),0) INTO v_seconds FROM public.service_period_extensions WHERE billing_event_id=e.id;
 RETURN e.period_end+v_seconds*interval '1 second';
END $function$

CREATE OR REPLACE FUNCTION core_private.service_period_eligibility(p_event_id uuid, p_actor_id uuid, p_action text, p_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  e public.subscription_billing_events%ROWTYPE;
  s public.subscriptions%ROWTYPE;
  r public.voucher_redemptions%ROWTYPE;
  ent public.voucher_entitlements%ROWTYPE;
  financial_state text;
  v_effective_end timestamptz;
BEGIN
  IF p_actor_id IS NULL THEN RETURN 'AUTH_REQUIRED'; END IF;
  IF p_event_id IS NULL OR p_at IS NULL THEN RETURN 'SERVICE_PERIOD_REQUIRED'; END IF;
  IF p_action IS NULL OR p_action NOT IN ('new_question','quota','message','attachment') THEN
    RETURN 'SERVICE_PERIOD_ACTION_INVALID';
  END IF;
  -- Private helper; wrappers pass the authenticated actor, service callers pass
  -- only a server-verified actor. A client cannot select another actor by UUID.
  IF auth.uid() IS NOT NULL AND auth.uid() IS DISTINCT FROM p_actor_id
     AND (auth.jwt()->>'role') IS DISTINCT FROM 'service_role' THEN
    RETURN 'NOT_ROOM_PARTY';
  END IF;
  SELECT * INTO e FROM public.subscription_billing_events WHERE id=p_event_id;
  IF NOT FOUND THEN RETURN 'SERVICE_PERIOD_NOT_FOUND'; END IF;
  IF p_actor_id IS DISTINCT FROM e.student_id AND p_actor_id IS DISTINCT FROM e.mentor_id THEN
    RETURN 'NOT_ROOM_PARTY';
  END IF;
  IF e.status IS DISTINCT FROM 'succeeded' OR e.event_type NOT IN ('initial','renewal')
     OR e.period_start IS NULL OR e.period_end IS NULL OR e.period_start>=e.period_end THEN
    RETURN 'SERVICE_PERIOD_INVALID';
  END IF;
  SELECT * INTO s FROM public.subscriptions WHERE id=e.subscription_id;
  IF NOT FOUND OR s.student_id IS DISTINCT FROM e.student_id OR s.mentor_id IS DISTINCT FROM e.mentor_id THEN
    RETURN 'SERVICE_PERIOD_PARTY_INVALID';
  END IF;
  IF p_action IN ('new_question','quota') THEN
    IF p_action='new_question' AND p_actor_id IS DISTINCT FROM e.student_id THEN RETURN 'MENTOR_CANNOT_CREATE_THREAD'; END IF;
    IF s.current_service_period_event_id IS DISTINCT FROM e.id OR s.status IS DISTINCT FROM 'active' THEN
      RETURN 'SERVICE_PERIOD_NOT_CURRENT';
    END IF;
    IF NOT core_private.service_period_matches_subscription(s.id,e.id) THEN RETURN 'SERVICE_PERIOD_INVALID'; END IF;
  END IF;
  financial_state := core_private.service_period_financial_state(e.id);
  CASE financial_state
    WHEN 'clear' THEN NULL;
    WHEN 'pending' THEN
      -- Preserve cash's existing pending-refund contract: students cannot add
      -- usage; mentors can complete their outstanding response.
      IF p_action IN ('new_question','quota') OR p_actor_id=e.student_id THEN
        RETURN 'SUBSCRIPTION_REFUND_PENDING';
      END IF;
    WHEN 'refunded' THEN RETURN 'SERVICE_PERIOD_REFUNDED';
    WHEN 'hold' THEN RETURN 'SERVICE_PERIOD_ON_HOLD';
    WHEN 'adjustment_required' THEN RETURN 'SERVICE_PERIOD_ADJUSTMENT_REQUIRED';
    ELSE RETURN 'SERVICE_PERIOD_FINANCIAL_UNRESOLVED';
  END CASE;
  IF e.funding_source='voucher' THEN
    IF e.voucher_redemption_id IS NULL OR e.payment_id IS NOT NULL OR e.ledger_id IS NOT NULL THEN
      RETURN 'VOUCHER_EVENT_INVALID';
    END IF;
    SELECT * INTO r FROM public.voucher_redemptions WHERE id=e.voucher_redemption_id;
    IF NOT FOUND OR r.status IS DISTINCT FROM 'active'
       OR r.subscription_id IS DISTINCT FROM e.subscription_id
       OR r.student_id IS DISTINCT FROM e.student_id OR r.mentor_id IS DISTINCT FROM e.mentor_id
       OR r.service_start IS DISTINCT FROM e.period_start OR r.service_end IS DISTINCT FROM e.period_end
       OR r.gross_cents IS DISTINCT FROM 11500000 OR r.platform_fee_cents IS DISTINCT FROM 1725000
       OR r.mentor_amount_cents IS DISTINCT FROM 9775000 OR r.weekly_question_limit IS DISTINCT FROM 9
       OR r.plan_tier IS DISTINCT FROM 'standard' OR e.amount_cents IS DISTINCT FROM r.gross_cents
       OR e.plan_tier IS DISTINCT FROM r.plan_tier THEN RETURN 'VOUCHER_ENTITLEMENT_INVALID'; END IF;
    SELECT * INTO ent FROM public.voucher_entitlements WHERE id=r.entitlement_id;
    IF NOT FOUND OR ent.status IS DISTINCT FROM 'redeemed' THEN RETURN 'VOUCHER_ENTITLEMENT_INVALID'; END IF;
  ELSIF e.voucher_redemption_id IS NOT NULL
        OR (e.funding_source IS NOT NULL AND e.funding_source NOT IN ('cash','pg')) THEN
    RETURN 'SERVICE_PERIOD_FUNDING_INVALID';
  END IF;
  v_effective_end:=core_private.service_period_effective_end(e.id);
  IF v_effective_end IS NULL THEN RETURN 'SERVICE_PERIOD_INVALID'; END IF;
  IF p_at<e.period_start THEN RETURN 'SERVICE_PERIOD_NOT_STARTED'; END IF;
  IF p_action IN ('new_question','quota') AND p_at>=v_effective_end THEN RETURN 'SERVICE_PERIOD_EXPIRED'; END IF;
  -- Open-thread message/attachment continuation intentionally survives expiry.
  -- Thread status/account/block checks are shared by the C thread adapter.
  RETURN 'allowed';
END $function$

CREATE OR REPLACE FUNCTION core_private.service_period_financial_state(p_event_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.subscription_billing_events%rowtype; v text; r public.voucher_redemptions%rowtype;
begin
 select * into e from public.subscription_billing_events where id=p_event_id;
 if not found or e.status<>'succeeded' or e.event_type not in ('initial','renewal') then return 'hold'; end if;
 if core_private.service_period_funding(e.id)='unknown' then return 'hold'; end if;
 select state into v from public.service_period_financial_holds where billing_event_id=e.id;
 if v='adjustment_required' then return v; end if;
 if exists(select 1 from public.refunds f where f.status='succeeded' and core_private.refund_matches_service_period(f,e)) then return 'refunded'; end if;
 if exists(select 1 from public.refunds f where f.status='pending' and (core_private.refund_matches_service_period(f,e) or (f.billing_event_id is null and f.subscription_id=e.subscription_id))) then return 'pending'; end if;
 if v='hold' then return v; end if;
 if exists(select 1 from public.refunds f where f.status='succeeded' and f.billing_event_id is null and f.subscription_id=e.subscription_id and (f.payment_id is null or f.payment_id=e.payment_id) and not core_private.refund_matches_service_period(f,e)) then return 'hold'; end if;
 if e.voucher_redemption_id is not null then
  select * into r from public.voucher_redemptions where id=e.voucher_redemption_id;
  if not found or r.status<>'active' or r.subscription_id<>e.subscription_id or r.student_id<>e.student_id or r.mentor_id<>e.mentor_id then return 'hold'; end if;
  if not exists(select 1 from public.voucher_entitlements t where t.id=r.entitlement_id and t.status='redeemed') then return 'hold'; end if;
 elsif e.payment_id is not null then
  if not exists(select 1 from public.payments p where p.id=e.payment_id and coalesce(p.student_id,p.payer_id,p.user_id)=e.student_id and p.mentor_id=e.mentor_id and p.status in ('succeeded','paid','success','complete','captured') and p.amount*100=e.amount_cents) then return 'hold'; end if;
 elsif e.ledger_id is null then return 'hold'; end if;
 if e.ledger_id is not null and not exists(select 1 from public.cash_ledger l where l.id=e.ledger_id and l.user_id=e.student_id and l.delta_cents=-e.amount_cents) then return 'hold'; end if;
 return 'clear';
end $function$

CREATE OR REPLACE FUNCTION core_private.service_period_funding(p_event_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e public.subscription_billing_events%ROWTYPE; p public.payments%ROWTYPE;
 l public.cash_ledger%ROWTYPE; s public.subscriptions%ROWTYPE; r public.voucher_redemptions%ROWTYPE;
BEGIN
 SELECT * INTO e FROM public.subscription_billing_events WHERE id=p_event_id;
 IF NOT FOUND OR e.event_type NOT IN ('initial','renewal') OR e.status NOT IN ('succeeded','refunded')
  OR e.amount_cents IS NULL OR e.amount_cents<=0 OR e.period_start IS NULL OR e.period_end IS NULL OR e.period_start>=e.period_end THEN RETURN 'unknown'; END IF;
 SELECT * INTO s FROM public.subscriptions WHERE id=e.subscription_id;
 IF s.id IS NULL OR s.student_id IS DISTINCT FROM e.student_id OR s.mentor_id IS DISTINCT FROM e.mentor_id THEN RETURN 'unknown'; END IF;
 IF e.funding_source='voucher' THEN
  SELECT * INTO r FROM public.voucher_redemptions WHERE id=e.voucher_redemption_id;
  IF r.id IS NULL OR e.payment_id IS NOT NULL OR e.ledger_id IS NOT NULL
    OR ROW(r.subscription_id,r.student_id,r.mentor_id,r.service_start,r.service_end,r.gross_cents,r.plan_tier)
     IS DISTINCT FROM ROW(e.subscription_id,e.student_id,e.mentor_id,e.period_start,e.period_end,e.amount_cents,e.plan_tier)
    OR NOT EXISTS(SELECT 1 FROM public.voucher_entitlements WHERE id=r.entitlement_id)
    OR r.gross_cents<>11500000 OR r.platform_fee_cents<>1725000 OR r.mentor_amount_cents<>9775000
    OR r.plan_tier<>'standard' OR r.weekly_question_limit<>9 THEN RETURN 'unknown'; END IF;
  RETURN 'voucher';
 END IF;
 IF e.voucher_redemption_id IS NOT NULL OR (e.funding_source IS NOT NULL AND e.funding_source NOT IN ('cash','pg')) THEN RETURN 'unknown'; END IF;
 IF e.payment_id IS NOT NULL THEN
  SELECT * INTO p FROM public.payments WHERE id=e.payment_id;
  IF p.id IS NULL OR coalesce(p.student_id,p.payer_id,p.user_id) IS DISTINCT FROM e.student_id
    OR p.mentor_id IS DISTINCT FROM e.mentor_id OR p.plan_id IS DISTINCT FROM e.plan_id
    OR p.status NOT IN ('succeeded','paid','success','complete','captured','refunded')
    OR p.amount*100 IS DISTINCT FROM e.amount_cents::numeric THEN RETURN 'unknown'; END IF;
 END IF;
 IF e.funding_source='pg' THEN
  IF e.payment_id IS NULL OR e.ledger_id IS NOT NULL THEN RETURN 'unknown'; END IF;
  RETURN 'pg';
 END IF;
 SELECT * INTO l FROM public.cash_ledger WHERE id=e.ledger_id;
 IF l.id IS NULL OR l.user_id IS DISTINCT FROM e.student_id OR l.ref_id IS DISTINCT FROM e.subscription_id
  OR l.ref_type IS DISTINCT FROM 'subscriptions' OR l.delta_cents IS DISTINCT FROM -e.amount_cents::bigint THEN RETURN 'unknown'; END IF;
 IF e.event_type='initial' THEN
  IF p.id IS NULL OR l.reason IS DISTINCT FROM 'subscription_payment'
   OR l.idempotency_key IS DISTINCT FROM 'sub_debit_'||p.id::text
   OR e.idempotency_key IS DISTINCT FROM 'sub_initial:'||e.subscription_id::text||':'||p.id::text
   OR (l.created_at IS DISTINCT FROM e.period_start AND NOT (
     e.funding_source IS NULL AND e.period_start=date_trunc('milliseconds',e.period_start)
     AND e.period_start=date_trunc('milliseconds',l.created_at))) THEN RETURN 'unknown'; END IF;
 ELSIF l.reason IS DISTINCT FROM 'subscription_renewal' OR l.idempotency_key IS DISTINCT FROM e.idempotency_key
       OR e.payment_id IS NOT NULL THEN RETURN 'unknown'; END IF;
 RETURN CASE WHEN e.funding_source IS NULL THEN 'verified_legacy_cash' ELSE 'cash' END;
END $function$

CREATE OR REPLACE FUNCTION core_private.set_subscription_cancel_impl(p_subscription_id uuid, p_cancel boolean, p_student_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE s public.subscriptions%ROWTYPE; v_mentor uuid; v_student uuid; v_was boolean;
BEGIN
 IF p_student_id IS NULL THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','AUTH_REQUIRED'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=p_student_id AND role='student') THEN
  RETURN jsonb_build_object('ok',false,'contract_version',1,'code','ROLE_NOT_STUDENT'); END IF;
 IF p_cancel IS NULL THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','INVALID_CANCEL_REQUEST'); END IF;
 SELECT student_id,mentor_id INTO v_student,v_mentor FROM public.subscriptions WHERE id=p_subscription_id;
 IF v_student IS NULL THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','SUBSCRIPTION_NOT_FOUND'); END IF;
 IF v_student IS DISTINCT FROM p_student_id THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','NOT_SUBSCRIPTION_OWNER'); END IF;
 PERFORM pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
 SELECT * INTO s FROM public.subscriptions WHERE id=p_subscription_id FOR UPDATE;
 IF s.student_id IS DISTINCT FROM p_student_id OR s.mentor_id IS DISTINCT FROM v_mentor THEN RAISE EXCEPTION 'SUBSCRIPTION_BINDING_MISMATCH'; END IF;
 PERFORM 1 FROM public.mentor_profiles WHERE user_id=s.mentor_id FOR UPDATE;
 IF s.status NOT IN ('active','past_due') THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','SUBSCRIPTION_NOT_CURRENT','status',s.status); END IF;
 IF s.funding_source='voucher' THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','VOUCHER_EXTERNAL_REFUND_REQUIRED'); END IF;
 IF NOT core_private.current_standard_service_period_valid(s.id) THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','SERVICE_PERIOD_FUNDING_UNRESOLVED'); END IF;
 v_was:=coalesce(s.cancel_at_period_end,false);
 IF v_was IS DISTINCT FROM p_cancel THEN
  UPDATE public.subscriptions SET cancel_at_period_end=p_cancel,cancel_requested_at=CASE WHEN p_cancel THEN now() ELSE NULL END
   WHERE id=s.id RETURNING * INTO s;
 END IF;
 RETURN jsonb_build_object('ok',true,'code',CASE WHEN v_was=p_cancel THEN 'already_succeeded' ELSE 'succeeded' END,
  'contract_version',1,'subscription_id',s.id,'cancel_at_period_end',s.cancel_at_period_end,'already_scheduled',v_was AND p_cancel,
  'was_scheduled',v_was,'cancel_requested_at',s.cancel_requested_at,'current_period_end',s.current_period_end,'next_billing_at',s.next_billing_at);
END $function$

CREATE OR REPLACE FUNCTION core_private.subscription_checkout_confirm_impl(p_payment_id uuid, p_plan_id uuid, p_expected_amount_cents integer, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_succeeded    constant text[] := array['succeeded','paid','success','complete','captured'];
  -- 정본 confirm_subscription_checkout raise 17종(§9.8 — 동명 envelope 변환)
  v_canon_raises constant text[] := array[
    'PAYMENT_NOT_FOUND','PAYMENT_NO_USER','PAYMENT_NO_MENTOR','PAYMENT_KIND_INVALID',
    'PLAN_NOT_FOUND','PLAN_MENTOR_MISMATCH','PLAN_AMOUNT_INVALID',
    'PAYMENT_PROCESSING','PAYMENT_NOT_PENDING','PAYMENT_STATE_UNEXPECTED','PAYMENT_STALE',
    'ACCOUNT_BANNED','ACCOUNT_SUSPENDED',
    'MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS','MENTOR_NOT_APPROVED','PLAN_INACTIVE','MENTOR_CAP_EXCEEDED'];
  p_rec          record;      -- P = 이번 호출 payment
  v_sub          record;      -- 잠근 subscription
  v_led          record;      -- P 자신의 sub_debit_ 원장 행
  v_c            record;      -- C = subscription.last_payment_id 가 가리키는 payment
  v_room         record;
  v_intent       bigint;      -- 결제 시점 불변 동의 금액 = payments.amount × 100
  v_plan_amount  integer;
  v_anom         uuid;
  v_canon        jsonb;
  v_roomres      jsonb;
  v_room_id      uuid;
  v_sub_id       uuid;
  v_room_found   boolean := false;
  v_room_new_sub uuid;        -- Phase 2 보정 후보(subscription_id)
  v_room_new_pay uuid;        -- Phase 2 보정 후보(payment_id)
  v_room_dirty   boolean := false;
  v_pair_student uuid; v_pair_mentor uuid; v_old_event uuid;
BEGIN
  IF p_payment_id IS NULL OR p_plan_id IS NULL OR p_expected_amount_cents IS NULL THEN
    RAISE EXCEPTION 'p_payment_id, p_plan_id, p_expected_amount_cents are required';
  END IF;

  SELECT user_id,mentor_id INTO v_pair_student,v_pair_mentor FROM public.payments WHERE id=p_payment_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','PAYMENT_NOT_FOUND'); END IF;
  PERFORM pg_advisory_xact_lock(hashtext(v_pair_student::text),hashtext(v_pair_mentor::text));
  -- 1) payments FOR UPDATE — §12.2/[C3]: 레거시와 동일하게 payments 를 먼저 잠근다
  SELECT p.id, p.user_id, p.mentor_id, p.status, p.kind, p.amount, p.currency, p.plan_id
    INTO p_rec
    FROM public.payments p WHERE p.id = p_payment_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PAYMENT_NOT_FOUND');
  END IF;
  IF p_rec.user_id IS DISTINCT FROM v_pair_student OR p_rec.mentor_id IS DISTINCT FROM v_pair_mentor THEN
    RAISE EXCEPTION 'PAYMENT_PARTY_CHANGED' USING ERRCODE='40001'; END IF;
  IF p_rec.user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PAYMENT_NO_USER');
  END IF;
  IF p_rec.mentor_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PAYMENT_NO_MENTOR');
  END IF;
  -- 결제 시점 불변 동의 금액 검증(§7 F12 — 구현 결정: 사전 동명 재사용, anomaly 미기록)
  IF p_rec.kind IS DISTINCT FROM 'subscription' THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PAYMENT_KIND_INVALID');
  END IF;
  IF p_rec.currency IS DISTINCT FROM 'KRW'
     OR p_rec.amount IS NULL OR p_rec.amount <= 0 OR p_rec.amount <> trunc(p_rec.amount) THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PAYMENT_STATE_UNEXPECTED');
  END IF;
  v_intent := (p_rec.amount * 100)::bigint;

  -- 2) 재생 판정 — succeeded 계열이면 재생 계약(Phase 1/2)으로 분기(정본 재호출 금지)
  IF p_rec.status = ANY(v_succeeded) THEN
    -- ── Phase 1: 검증 전용 (business-state 쓰기 금지 · anomaly INSERT 만 허용) ──
    -- 1·2. subscription 행 확인·잠금 (최신 결제 정본은 오직 last_payment_id — 추론 금지)
    SELECT s.id, s.student_id, s.mentor_id, s.last_payment_id, s.funding_source, s.current_service_period_event_id
      INTO v_sub
      FROM public.subscriptions s
     WHERE s.student_id = p_rec.user_id AND s.mentor_id = p_rec.mentor_id
     FOR UPDATE;
    IF NOT FOUND THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, NULL, 'SUCCEEDED_NO_SUBSCRIPTION', 'F12 replay: succeeded payment without subscription')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUCCEEDED_NO_SUBSCRIPTION', 'anomaly_id', v_anom);
    END IF;
    -- 3. P 자신의 원장 행 확인
    SELECT l.user_id, l.delta_cents, l.reason, l.ref_type, l.ref_id
      INTO v_led
      FROM public.cash_ledger l
     WHERE l.idempotency_key = 'sub_debit_' || p_payment_id::text;
    IF NOT FOUND THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub.id, 'SUCCEEDED_NO_LEDGER', 'F12 replay: succeeded payment without ledger debit')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUCCEEDED_NO_LEDGER', 'anomaly_id', v_anom);
    END IF;
    -- 4. P 의 payment–plan 결속 (필수 관계 — NULL 은 일치가 아니라 명시 거부)
    IF p_rec.plan_id IS NULL OR p_rec.plan_id <> p_plan_id THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)
      VALUES (p_payment_id, v_sub.id, 'PLAN_BINDING_MISMATCH', 'F12 replay: payments.plan_id <> p_plan_id',
              jsonb_build_object('plan_id', p_plan_id), jsonb_build_object('plan_id', p_rec.plan_id))
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PLAN_BINDING_MISMATCH', 'anomaly_id', v_anom);
    END IF;
    -- 5. P 의 payment–subscription 당사자 결속
    IF p_rec.user_id <> v_sub.student_id OR p_rec.mentor_id <> v_sub.mentor_id THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub.id, 'PARTY_BINDING_MISMATCH', 'F12 replay: P party mismatch')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PARTY_BINDING_MISMATCH', 'anomaly_id', v_anom);
    END IF;
    -- 6. ledger–subscription 결속 (필수 관계 — NULL 명시 거부)
    IF v_led.user_id IS NULL OR v_led.user_id <> p_rec.user_id
       OR v_led.ref_id IS NULL OR v_led.ref_id <> v_sub.id THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)
      VALUES (p_payment_id, v_sub.id, 'LEDGER_BINDING_MISMATCH', 'F12 replay: ledger user/ref binding mismatch',
              jsonb_build_object('user_id', p_rec.user_id, 'ref_id', v_sub.id),
              jsonb_build_object('user_id', v_led.user_id, 'ref_id', v_led.ref_id))
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'LEDGER_BINDING_MISMATCH', 'anomaly_id', v_anom);
    END IF;
    -- 7. 원장 필드값 대조 — 기준은 결제 시점 불변 동의 금액(payments.amount×100).
    --    현재 플랜 가격을 읽지 않는다(가격 변경 후 정당한 재시도 오탐 금지 — T-CONC-09).
    IF v_led.delta_cents IS DISTINCT FROM -v_intent
       OR coalesce(v_led.reason, '') <> 'subscription_payment'
       OR coalesce(v_led.ref_type, '') <> 'subscriptions' THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)
      VALUES (p_payment_id, v_sub.id, 'LEDGER_FIELD_MISMATCH', 'F12 replay: ledger field mismatch vs intent amount',
              jsonb_build_object('user_id', p_rec.user_id, 'ref_id', v_sub.id, 'ref_type', 'subscriptions',
                                 'reason', 'subscription_payment', 'delta_cents', -v_intent),
              jsonb_build_object('user_id', v_led.user_id, 'ref_id', v_led.ref_id, 'ref_type', v_led.ref_type,
                                 'reason', v_led.reason, 'delta_cents', v_led.delta_cents))
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'LEDGER_FIELD_MISMATCH', 'anomaly_id', v_anom);
    END IF;
    -- A past cash checkout replay during a voucher period returns its immutable
    -- event without replacing current period/room/payment pointers.
    IF v_sub.funding_source='voucher' THEN
      SELECT id INTO v_old_event FROM public.subscription_billing_events
       WHERE payment_id=p_payment_id AND subscription_id=v_sub.id AND event_type='initial';
      IF v_old_event IS NULL THEN RAISE EXCEPTION 'BILLING_EVENT_BINDING_MISMATCH'; END IF;
      PERFORM core_private.record_initial_subscription_billing_event(p_payment_id,v_sub.id,false);
      SELECT id INTO v_room_id FROM public.mentor_student_rooms WHERE student_id=v_sub.student_id AND mentor_id=v_sub.mentor_id AND subscription_id=v_sub.id;
      IF v_room_id IS NULL THEN RETURN jsonb_build_object('ok',false,'code','ROOM_REF_MISMATCH'); END IF;
      RETURN jsonb_build_object('ok',true,'contract_version',1,'idempotent',true,'subscription_id',v_sub.id,
       'payment_status','succeeded','room_id',v_room_id,'billing_event_id',v_old_event);
    END IF;
    -- 8. C = subscription.last_payment_id 유효성 (detail 은 anomaly 에만 — 코드는 1종 고정)
    IF v_sub.last_payment_id IS NULL THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub.id, 'SUBSCRIPTION_REF_INVALID', 'LAST_PAYMENT_ID_NULL')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUBSCRIPTION_REF_INVALID', 'anomaly_id', v_anom);
    END IF;
    SELECT p2.id, p2.user_id, p2.mentor_id, p2.status
      INTO v_c FROM public.payments p2 WHERE p2.id = v_sub.last_payment_id;
    IF NOT FOUND THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub.id, 'SUBSCRIPTION_REF_INVALID', 'LAST_PAYMENT_NOT_FOUND')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUBSCRIPTION_REF_INVALID', 'anomaly_id', v_anom);
    END IF;
    IF NOT (v_c.status = ANY(v_succeeded)) THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub.id, 'SUBSCRIPTION_REF_INVALID', 'LAST_PAYMENT_NOT_SUCCEEDED')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUBSCRIPTION_REF_INVALID', 'anomaly_id', v_anom);
    END IF;
    -- C 당사자 불일치는 8단계 PARTY_BINDING_MISMATCH (LEDGER_BINDING 으로 뭉개지 않는다)
    IF v_c.user_id IS NULL OR v_c.user_id <> v_sub.student_id
       OR v_c.mentor_id IS NULL OR v_c.mentor_id <> v_sub.mentor_id THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub.id, 'PARTY_BINDING_MISMATCH', 'F12 replay: C party mismatch')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PARTY_BINDING_MISMATCH', 'anomaly_id', v_anom);
    END IF;
    -- 9. room 참조 판정 (쓰기 없음 — 보정 예정값 후보만 계산)
    SELECT r.id, r.subscription_id, r.payment_id
      INTO v_room
      FROM public.mentor_student_rooms r
     WHERE r.student_id = v_sub.student_id AND r.mentor_id = v_sub.mentor_id
     FOR UPDATE;
    v_room_found := FOUND;
    IF v_room_found THEN
      IF v_room.subscription_id IS NULL THEN
        v_room_new_sub := v_sub.id; v_room_dirty := true;
      ELSIF v_room.subscription_id <> v_sub.id THEN
        INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)
        VALUES (p_payment_id, v_sub.id, 'ROOM_REF_MISMATCH', 'F12 replay: room.subscription_id conflict',
                jsonb_build_object('subscription_id', v_sub.id),
                jsonb_build_object('subscription_id', v_room.subscription_id))
        RETURNING id INTO v_anom;
        RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROOM_REF_MISMATCH', 'anomaly_id', v_anom);
      ELSE
        v_room_new_sub := v_room.subscription_id;
      END IF;
      IF v_room.payment_id IS NULL THEN
        v_room_new_pay := v_sub.last_payment_id; v_room_dirty := true;                  -- NULL → C 로 복구 후보
      ELSIF v_room.payment_id = v_sub.last_payment_id THEN
        v_room_new_pay := v_room.payment_id;                                            -- C 동일 → 유지
      ELSIF v_room.payment_id = p_payment_id AND p_payment_id <> v_sub.last_payment_id THEN
        v_room_new_pay := v_sub.last_payment_id; v_room_dirty := true;                  -- stale → C 로 교체 후보
      ELSE
        INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)
        VALUES (p_payment_id, v_sub.id, 'ROOM_REF_MISMATCH', 'F12 replay: room.payment_id references third payment',
                jsonb_build_object('payment_id_c', v_sub.last_payment_id, 'payment_id_p', p_payment_id),
                jsonb_build_object('payment_id', v_room.payment_id))
        RETURNING id INTO v_anom;
        RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROOM_REF_MISMATCH', 'anomaly_id', v_anom);
      END IF;
    END IF;

    -- ── Phase 2: 검증 전부 통과 후에만 room 확보·보정 (참조 복구 — 자금 반복 0) ──
    BEGIN
      IF NOT v_room_found THEN
        v_roomres := core_private.ensure_student_mentor_room(
                       v_sub.student_id, v_sub.mentor_id,
                       p_payment_id => v_sub.last_payment_id,
                       p_subscription_id => v_sub.id,
                       p_require_entitlement => false);
        IF NOT coalesce((v_roomres->>'ok')::boolean, false) THEN
          RAISE EXCEPTION 'S2_M9_ROOM_STEP_FAILED';
        END IF;
        v_room_id := (v_roomres->>'room_id')::uuid;
        -- 동시 생성 경합 포함 재확인: NULL 참조만 채운다(F10 은 기존 방 참조를 덮어쓰지 않음)
        UPDATE public.mentor_student_rooms r
           SET subscription_id = coalesce(r.subscription_id, v_sub.id),
               payment_id      = coalesce(r.payment_id, v_sub.last_payment_id)
         WHERE r.id = v_room_id;
      ELSE
        v_room_id := v_room.id;
        IF v_room_dirty THEN
          UPDATE public.mentor_student_rooms r
             SET subscription_id = v_room_new_sub,
                 payment_id      = v_room_new_pay
           WHERE r.id = v_room_id;
        END IF;
      END IF;
      PERFORM core_private.record_initial_subscription_billing_event(p_payment_id, v_sub.id, false);
    EXCEPTION WHEN OTHERS THEN
      IF SQLERRM = 'BILLING_EVENT_BINDING_MISMATCH' THEN RAISE; END IF;
      -- 운영 오류(9단계와 별도): 자금·원장·구독·결제 성공 상태는 건드리지 않고,
      -- room 부분 변경은 이 블록에서 롤백되며, 재시도 가능하다(§7 F12 재생 결과)
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROOM_ENSURE_FAILED');
    END;

    RETURN jsonb_build_object('ok', true, 'contract_version', 1, 'idempotent', true,
                              'subscription_id', v_sub.id, 'payment_status', 'succeeded',
                              'room_id', v_room_id);
  END IF;

  -- ── 최초 실행 경로 ──
  -- 3) advisory (정본과 동일 인자 형식 — 전환기 잠금 순서 일치 [C3])
  PERFORM pg_advisory_xact_lock(hashtext(p_rec.user_id::text), hashtext(p_rec.mentor_id::text));
  PERFORM 1 FROM public.subscriptions WHERE student_id=p_rec.user_id AND mentor_id=p_rec.mentor_id FOR UPDATE;
  PERFORM 1 FROM public.mentor_profiles WHERE user_id=p_rec.mentor_id FOR UPDATE;
  -- 4) mentor_plans FOR UPDATE — 5)~6) 내내 유지되어 TOCTOU 차단(멘토 UPDATE 대기, T-CONC-04)
  SELECT mp.amount_cents INTO v_plan_amount
    FROM public.mentor_plans mp WHERE mp.id = p_plan_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PLAN_NOT_FOUND');
  END IF;
  -- 5) 3자 일치: payments.amount×100 = p_expected_amount_cents = 잠근 amount_cents
  IF v_intent <> p_expected_amount_cents OR v_intent <> v_plan_amount THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PLAN_AMOUNT_CHANGED',
                              'expected_amount_cents', p_expected_amount_cents,
                              'actual_amount_cents', v_plan_amount);
  END IF;
  -- 6)~7) 정본 호출 + 방 확보 — 한 subtransaction: 방 확보 실패 시 자금·원장·구독·
  --       결제 변경 전부 롤백(rev 8 A-2 §3). 정본 raise 는 잡아 동명 envelope 변환.
  BEGIN
    v_canon := core_private.confirm_cash_subscription_payment(p_payment_id, p_plan_id, p_idempotency_key);
    IF NOT coalesce((v_canon->>'ok')::boolean, false) THEN
      -- 정본 envelope 실패(CASH_INSUFFICIENT·anomaly 계열): 금융 변경은 정본 내부에서
      -- 이미 롤백됨 — anomaly 행만 유지한 채 그대로 승격 반환
      RETURN v_canon || jsonb_build_object('contract_version', 1);
    END IF;
    v_sub_id := (v_canon->>'subscription_id')::uuid;
    v_roomres := core_private.ensure_student_mentor_room(
                   p_rec.user_id, p_rec.mentor_id,
                   p_payment_id => p_payment_id,
                   p_subscription_id => v_sub_id,
                   p_require_entitlement => false);
    IF NOT coalesce((v_roomres->>'ok')::boolean, false) THEN
      RAISE EXCEPTION 'S2_M9_ROOM_STEP_FAILED';
    END IF;
    v_room_id := (v_roomres->>'room_id')::uuid;
    -- room 참조 규칙(신규 결제 — §7 F12 표): pair 불변 · subscription_id NULL 이면
    -- 채움/다른 값이면 거부 · payment_id 는 현재 결제로 갱신(최신 참조 의미론)
    SELECT r.id, r.subscription_id, r.payment_id INTO v_room
      FROM public.mentor_student_rooms r WHERE r.id = v_room_id FOR UPDATE;
    IF v_room.subscription_id IS NOT NULL AND v_room.subscription_id <> v_sub_id THEN
      RAISE EXCEPTION 'S2_M9_ROOM_REF_CONFLICT';
    END IF;
    UPDATE public.mentor_student_rooms r
       SET subscription_id = coalesce(r.subscription_id, v_sub_id),
           payment_id      = p_payment_id
     WHERE r.id = v_room_id;
    PERFORM core_private.record_initial_subscription_billing_event(p_payment_id, v_sub_id, true);
  EXCEPTION WHEN OTHERS THEN
    IF sqlerrm LIKE '%S2_M9_ROOM_REF_CONFLICT%' THEN
      -- 초기 경로 room 참조 충돌 = 거부(§7 F12 표) — 자금 변경은 위 블록에서 전부 롤백됨
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub_id, 'ROOM_REF_MISMATCH', 'F12 initial: room.subscription_id conflict')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROOM_REF_MISMATCH', 'anomaly_id', v_anom);
    ELSIF sqlerrm LIKE '%S2_M9_ROOM_STEP_FAILED%' THEN
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROOM_ENSURE_FAILED');
    ELSIF sqlerrm = ANY(v_canon_raises) THEN
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', sqlerrm);
    ELSE
      RAISE;  -- 사전 밖 예외는 그대로 전파(§8.2)
    END IF;
  END;

  -- 8) 성공: 기존 정본 반환 + contract_version + room_id (§8.3 F12 행)
  RETURN v_canon || jsonb_build_object('contract_version', 1, 'room_id', v_room_id);
END $function$

CREATE OR REPLACE FUNCTION core_private.subscription_refund_estimate_impl(p_subscription_id uuid, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_sub record;
  v_ev record;
  v_room uuid;
  v_now timestamptz;
  v_start timestamptz;
  v_end timestamptz;
  v_amount bigint;
  v_usage boolean;
  v_total_ms numeric;
  v_elapsed_ms numeric;
  v_remaining_ms numeric;
  v_refund bigint;
  v_bracket text;
  v_rule text;
begin
  if p_subscription_id is null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUBSCRIPTION_NOT_FOUND');
  end if;
  select s.id, s.student_id, s.mentor_id, s.status, s.current_period_start, s.current_period_end, s.payment_id, s.last_billing_event_id, s.current_service_period_event_id
    into v_sub from public.subscriptions s where s.id = p_subscription_id;
  if not found then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUBSCRIPTION_NOT_FOUND');
  end if;

  select e.id,e.amount_cents,e.payment_id,e.period_start,e.period_end,e.voucher_redemption_id into v_ev
  from public.subscription_billing_events e where e.id=coalesce(v_sub.current_service_period_event_id,v_sub.last_billing_event_id)
  and e.subscription_id=v_sub.id and e.student_id=v_sub.student_id and e.mentor_id=v_sub.mentor_id and e.status='succeeded' and e.event_type in ('initial','renewal');
  if not found then return jsonb_build_object('ok',false,'contract_version',1,'code','SERVICE_PERIOD_UNRESOLVED'); end if;
  if v_ev.voucher_redemption_id is not null then return jsonb_build_object('ok',false,'contract_version',1,'code','VOUCHER_EXTERNAL_REFUND_REQUIRED'); end if;
  if core_private.service_period_financial_state(v_ev.id)<>'clear' then return jsonb_build_object('ok',false,'contract_version',1,'code','SERVICE_PERIOD_FINANCIAL_BLOCKED'); end if;
  v_start:=v_ev.period_start; v_end:=core_private.service_period_effective_end(v_ev.id);
  if v_end is null then return jsonb_build_object('ok',false,'contract_version',1,'code','SERVICE_PERIOD_UNRESOLVED'); end if;
  v_amount := greatest(0, coalesce(v_ev.amount_cents, 0));

  -- 이용 개시(첫 질문 작성) — 웹 hasSubscriptionUsageStartedForPair 동일 순서
  if v_sub.mentor_id is null then
    v_usage := true;   -- 멘토 미상(이상 데이터)은 보수적으로 개시로 본다(웹 동일)
  elsif v_start is null then
    v_usage := false;
  else
    select r.id into v_room from public.mentor_student_rooms r
     where r.student_id = v_sub.student_id and r.mentor_id = v_sub.mentor_id limit 1;
    if v_room is null then
      v_usage := false;
    else
      v_usage := exists (select 1 from public.question_threads t
                          where t.mentor_student_room_id = v_room and (t.service_period_event_id=v_ev.id or (t.service_period_event_id is null and t.created_at >= v_start and t.created_at < v_end)));
    end if;
  end if;

  -- JS Date 는 ms 정밀도 — 동일하게 ms 로 절단한다
  v_now := date_trunc('milliseconds', coalesce(p_now, now()));
  v_start := date_trunc('milliseconds', v_start);
  v_end := date_trunc('milliseconds', v_end);

  if v_amount = 0 or v_start is null or v_end is null or v_end <= v_start then
    return jsonb_build_object('ok', true, 'contract_version', 1, 'subscription_id', v_sub.id,
      'refundable_cents', 0, 'amount_cents', v_amount, 'rule', '계산 불가', 'bracket_reason', 'invalid',
      'usage_started', v_usage, 'elapsed_days', 0, 'period_days', 0, 'remaining_days', 0,
      'remaining_ratio', 0, 'elapsed_ratio', 0, 'period_start', v_start, 'period_end', v_end,
      'billing_event_id', v_ev.id, 'billing_payment_id', v_ev.payment_id, 'as_of', v_now);
  end if;

  v_total_ms := (extract(epoch from v_end) - extract(epoch from v_start)) * 1000;
  v_elapsed_ms := greatest(0, (extract(epoch from v_now) - extract(epoch from v_start)) * 1000);
  v_remaining_ms := greatest(0, (extract(epoch from v_end) - extract(epoch from v_now)) * 1000);

  if v_usage = false then
    v_refund := v_amount; v_bracket := 'before_usage'; v_rule := '이용 개시 전';
  elsif v_elapsed_ms * 3 < v_total_ms then
    v_refund := (v_amount * 2) / 3; v_bracket := 'lt_1_3'; v_rule := '1/3 전';
  elsif v_elapsed_ms * 2 < v_total_ms then
    v_refund := v_amount / 2; v_bracket := 'lt_1_2'; v_rule := '1/2 전';
  else
    v_refund := 0; v_bracket := 'ge_1_2'; v_rule := '1/2 후';
  end if;

  return jsonb_build_object('ok', true, 'contract_version', 1, 'subscription_id', v_sub.id,
    'refundable_cents', v_refund, 'amount_cents', v_amount, 'rule', v_rule, 'bracket_reason', v_bracket,
    'usage_started', v_usage,
    'elapsed_days', floor(v_elapsed_ms / 86400000)::int,
    'period_days', greatest(1, ceil(v_total_ms / 86400000)::int),
    'remaining_days', ceil(v_remaining_ms / 86400000)::int,
    'remaining_ratio', round(least(1, v_remaining_ms / v_total_ms), 6),
    'elapsed_ratio', round(least(1, v_elapsed_ms / v_total_ms), 6),
    'period_start', v_start, 'period_end', v_end,
    'billing_event_id', v_ev.id, 'billing_payment_id', v_ev.payment_id, 'as_of', v_now);
end
$function$

CREATE OR REPLACE FUNCTION core_private.user_consent_signup_impl(p_user_id uuid, p_meta jsonb, p_source text DEFAULT 'signup'::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  m jsonb := coalesce(p_meta, '{}'::jsonb);
  v_role text;
  v_birth_date date;
  v_is_minor boolean := false;
  v_version text;
  v_agreed_at timestamptz := now();
  v_metadata jsonb;
  v_source text := coalesce(nullif(btrim(p_source), ''), 'signup');
begin
  if p_user_id is null then
    raise exception 'USER_ID_REQUIRED' using errcode = '22023';
  end if;
  v_role := lower(coalesce(nullif(trim(m->>'app_role'), ''), 'student'));
  v_version := coalesce(nullif(trim(m->>'consent_version'), ''), 'legal-placeholder-2026-06-20');

  begin
    v_birth_date := nullif(trim(m->>'birth_date'), '')::date;
  exception when others then
    v_birth_date := null;
  end;

  v_is_minor := coalesce(
    nullif(trim(m->>'is_minor'), '')::boolean,
    case when v_birth_date is not null
         then ((now() at time zone 'Asia/Seoul')::date < (v_birth_date + interval '14 years')::date)
         else false end
  );

  v_metadata := jsonb_build_object(
    'role', v_role,
    'birth_date', case when v_birth_date is not null then v_birth_date::text else null end,
    'age_gate_checked_at', nullif(trim(m->>'age_gate_checked_at'), ''),
    'verification_method', coalesce(nullif(trim(m->>'guardian_verification_method'), ''), 'legal_review_pending')
  );

  if (m->>'terms_agreed') = 'true' then
    insert into public.user_consent_records (
      user_id, consent_type, consent_actor, is_minor, guardian_consent,
      consent_version, agreed_at, source, metadata, idempotency_key
    ) values (
      p_user_id, 'terms', 'user', v_is_minor, false,
      v_version, v_agreed_at, v_source, v_metadata, 'signup:' || p_user_id::text || ':terms:' || v_version
    ) on conflict (idempotency_key) do nothing;
  end if;

  if (m->>'privacy_agreed') = 'true' then
    insert into public.user_consent_records (
      user_id, consent_type, consent_actor, is_minor, guardian_consent,
      consent_version, agreed_at, source, metadata, idempotency_key
    ) values (
      p_user_id, 'privacy', 'user', v_is_minor, false,
      v_version, v_agreed_at, v_source, v_metadata, 'signup:' || p_user_id::text || ':privacy:' || v_version
    ) on conflict (idempotency_key) do nothing;
  end if;

  if (m->>'marketing_agreed') = 'true' then
    insert into public.user_consent_records (
      user_id, consent_type, consent_actor, is_minor, guardian_consent,
      consent_version, agreed_at, source, metadata, idempotency_key
    ) values (
      p_user_id, 'marketing', 'user', v_is_minor, false,
      v_version, v_agreed_at, v_source, v_metadata, 'signup:' || p_user_id::text || ':marketing:' || v_version
    ) on conflict (idempotency_key) do nothing;
  end if;

  if v_is_minor and (m->>'guardian_consent') = 'true' then
    insert into public.user_consent_records (
      user_id, consent_type, consent_actor, is_minor, guardian_consent,
      consent_version, guardian_ref, agreed_at, source, metadata, idempotency_key
    ) values (
      p_user_id, 'minor_guardian_consent', 'guardian', true, true,
      v_version, nullif(trim(m->>'guardian_ref'), ''), v_agreed_at, v_source, v_metadata,
      'signup:' || p_user_id::text || ':minor_guardian_consent:' || v_version
    ) on conflict (idempotency_key) do nothing;
  end if;
end
$function$

CREATE OR REPLACE FUNCTION core_private.user_profile_update_self_impl(p_user_id uuid, p_nickname text, p_grade_level text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_role text;
  v_status text;
  v_susp timestamptz;
  v_norm text;
  v_nick text;
  v_grade text;
  v_set_grade boolean := false;
  v_updated_at timestamptz;
  v_out_nick text;
  v_out_grade text;
begin
  if p_user_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  select u.role, u.status, u.suspended_until
    into v_role, v_status, v_susp
    from public.users u where u.id = p_user_id
    for update;
  if not found then
    raise exception 'ACCOUNT_NOT_ACTIVE';
  end if;

  -- 206(DB-5 B): role NULL(소셜 가입 · 완성 전)은 `not in` 을 NULL 로 통과하므로 명시적으로 거부한다(그 외 원문 그대로).
  if v_role is null or v_role not in ('student','mentor') then
    raise exception 'ROLE_NOT_ALLOWED';
  end if;

  -- 계정 상태 게이트 (Build 13 UGC 게이트와 동일 판정: banned 차단 · 유효 suspended
  -- 차단 · 만료 suspended 허용 · unknown/deleted/빈 status 차단)
  v_norm := lower(btrim(coalesce(v_status, '')));
  if v_norm = 'banned' then
    raise exception 'ACCOUNT_BANNED';
  end if;
  if v_norm = 'suspended' and (v_susp is null or v_susp > now()) then
    raise exception 'ACCOUNT_SUSPENDED';
  end if;
  if v_norm not in ('active','suspended') then
    raise exception 'ACCOUNT_NOT_ACTIVE';
  end if;
  if public.account_deletion_write_blocked(p_user_id) then
    raise exception 'ACCOUNT_DELETION_IN_PROGRESS';
  end if;

  -- nickname: null=유지 · trim 후 빈 값=오류 · 최대 30자
  if p_nickname is not null then
    v_nick := btrim(p_nickname);
    if v_nick = '' then
      raise exception 'NICKNAME_REQUIRED' using errcode = '22023';
    end if;
    if char_length(v_nick) > 30 then
      raise exception 'NICKNAME_TOO_LONG' using errcode = '22023';
    end if;
  end if;

  -- grade_level: null=유지 · ''=값 제거 · 학생만 · 자유 텍스트 최대 20자
  if p_grade_level is not null then
    if v_role <> 'student' then
      raise exception 'GRADE_LEVEL_NOT_ALLOWED' using errcode = '22023';
    end if;
    v_grade := nullif(btrim(p_grade_level), '');
    if v_grade is not null and char_length(v_grade) > 20 then
      raise exception 'GRADE_LEVEL_TOO_LONG' using errcode = '22023';
    end if;
    v_set_grade := true;
  end if;

  update public.users u
     set nickname    = coalesce(v_nick, u.nickname),
         grade_level = case when v_set_grade then v_grade else u.grade_level end,
         updated_at  = now()
   where u.id = p_user_id
   returning u.updated_at, u.nickname, u.grade_level
     into v_updated_at, v_out_nick, v_out_grade;

  return jsonb_build_object(
    'ok', true,
    'contract_version', 1,
    'nickname', v_out_nick,
    'grade_level', v_out_grade,
    'updated_at', v_updated_at
  );
end
$function$

CREATE OR REPLACE FUNCTION public._cro_transition_is_terminal(o custom_request_orders)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_terminal text[] := array[
    'completed', 'accepted', 'closed', 'finished', 'cancelled', 'canceled',
    'refunded', 'rejected', 'done', 'resolved', 'dispute_resolved'
  ];
begin
  if lower(btrim(coalesce(o.status, ''))) = any(v_terminal) then
    return true;
  elsif lower(btrim(coalesce(o.state, ''))) = any(v_terminal) then
    return true;
  elsif lower(btrim(coalesce(o.order_status, ''))) = any(v_terminal) then
    return true;
  elsif lower(btrim(coalesce(o.stage, ''))) = any(v_terminal) then
    return true;
  elsif o.completed_at is not null or o.closed_at is not null or o.finished_at is not null then
    return true;
  end if;
  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public._cro_transition_payment_confirmed(o custom_request_orders)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_confirmed text[] := array['paid', 'succeeded', 'escrowed', 'completed', 'complete', 'success', 'captured', 'paid_out'];
begin
  if lower(btrim(coalesce(o.payment_status, ''))) = any(v_confirmed) then
    return true;
  end if;
  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public._cro_transition_primary_status_col(o custom_request_orders)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
begin
  if o.status is not null and btrim(o.status) <> '' then
    return 'status';
  elsif o.state is not null and btrim(o.state) <> '' then
    return 'state';
  elsif o.order_status is not null and btrim(o.order_status) <> '' then
    return 'order_status';
  elsif o.stage is not null and btrim(o.stage) <> '' then
    return 'stage';
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public._cro_transition_primary_status_norm(o custom_request_orders)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_col text;
begin
  v_col := public._cro_transition_primary_status_col(o);
  if v_col = 'status' then
    return lower(btrim(o.status));
  elsif v_col = 'state' then
    return lower(btrim(o.state));
  elsif v_col = 'order_status' then
    return lower(btrim(o.order_status));
  elsif v_col = 'stage' then
    return lower(btrim(o.stage));
  end if;
  return '';
end;
$function$

CREATE OR REPLACE FUNCTION public._pick_custom_order_gross_won(o custom_request_orders, app custom_request_applications)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    public._positive_int_from_numeric((o).agreed_price),
    public._positive_int_from_numeric((o).proposed_price),
    public._positive_int_from_numeric((o).price),
    public._positive_int_from_numeric((o).amount),
    public._positive_int_from_numeric((app).proposed_price),
    public._positive_int_from_numeric((app).bid_amount),
    public._positive_int_from_numeric((app).price)
  );
$function$

CREATE OR REPLACE FUNCTION public.accept_custom_order_deliverable_atomic(p_order_id uuid, p_student_id uuid, p_require_payment boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o public.custom_request_orders%rowtype;
  app public.custom_request_applications%rowtype;
  v_norm text;
  v_pay text;
  v_dispute_cnt integer;
  v_deliverable_cnt integer;
  v_existing_settlement uuid;
  v_gross integer;
  v_platform_fee integer;
  v_mentor_amount integer;
  v_settlement_id uuid;
  v_settlement_created boolean := false;
  v_payout_done boolean := false;
  v_now timestamptz := now();
  v_fee_rate numeric := 0.05;  -- 252: 맞춤의뢰 수수료 5%
begin
  if p_order_id is null then
    return jsonb_build_object('ok', false, 'message', 'orderId가 필요합니다.');
  end if;
  if p_student_id is null then
    return jsonb_build_object('ok', false, 'message', '학생 ID가 필요합니다.');
  end if;

  select * into o
  from public.custom_request_orders
  where id = p_order_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'message', '주문을 찾을 수 없어요.');
  end if;

  if o.student_id is distinct from p_student_id then
    return jsonb_build_object('ok', false, 'message', '의뢰자(학생) 본인만 납품을 수락할 수 있습니다.');
  end if;

  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''), '')));
  -- escrowed(예치 완료) 또는 paid(멱등·수리) 만 허용. unpaid 등 레거시 무예치 차단.
  if p_require_payment and v_pay not in ('paid', 'escrowed') then
    return jsonb_build_object('ok', false, 'message', '결제(예치)가 완료되지 않은 주문은 수락할 수 없습니다.');
  end if;

  if o.completed_at is not null
     or o.closed_at is not null
     or o.finished_at is not null
     or lower(trim(coalesce(o.status, ''))) in (
       'completed','accepted','closed','finished','cancelled','canceled',
       'refunded','rejected','done','resolved','dispute_resolved'
     )
     or lower(trim(coalesce(o.state, ''))) in (
       'completed','accepted','closed','finished','cancelled','canceled',
       'refunded','rejected','done','resolved','dispute_resolved'
     )
     or lower(trim(coalesce(o.order_status, ''))) in (
       'completed','accepted','closed','finished','cancelled','canceled',
       'refunded','rejected','done','resolved','dispute_resolved'
     )
  then
    return jsonb_build_object('ok', false, 'message', '이미 완료된 주문입니다.');
  end if;

  v_norm := public._order_primary_status_norm(o);
  if v_norm = '' then
    return jsonb_build_object('ok', false, 'message', '주문 상태를 확인할 수 없어 수락할 수 없습니다.');
  end if;

  if v_norm not in (
    'delivered','delivered_pending_review','waiting_review','pending_review',
    'redelivered','delivery_submitted','in_review'
  ) then
    return jsonb_build_object(
      'ok', false,
      'message', format('현재 상태(%s)에서는 납품 수락을 할 수 없습니다.', v_norm)
    );
  end if;

  select count(*)::integer into v_dispute_cnt
  from public.disputes d
  where d.custom_request_order_id = p_order_id
    and d.status in ('open', 'under_review', 'escalated');

  if v_dispute_cnt > 0 then
    return jsonb_build_object('ok', false, 'message', '진행 중인 분쟁이 있어 납품 수락을 할 수 없습니다.');
  end if;

  select count(*)::integer into v_deliverable_cnt
  from public.custom_order_deliverables d
  where d.custom_request_order_id = p_order_id;

  if v_deliverable_cnt < 1 then
    return jsonb_build_object('ok', false, 'message', '등록된 납품이 없어 수락할 수 없습니다.');
  end if;

  select id into v_existing_settlement
  from public.custom_order_settlement_items s
  where s.custom_request_order_id = p_order_id;

  select a.* into app
  from public.custom_request_applications a
  where a.id = coalesce(o.application_id, o.custom_request_application_id, o.selected_application_id)
  limit 1;

  if v_existing_settlement is null then
    v_gross := public._pick_custom_order_gross_won(o, app);
    if v_gross is not null and v_gross > 0 then
      v_platform_fee := floor(v_gross * v_fee_rate)::integer;
      v_mentor_amount := v_gross - v_platform_fee;

      insert into public.custom_order_settlement_items (
        custom_request_order_id,
        mentor_id,
        student_id,
        gross_amount,
        platform_fee_amount,
        mentor_amount,
        fee_rate,
        status
      ) values (
        p_order_id,
        o.mentor_id,
        o.student_id,
        v_gross,
        v_platform_fee,
        v_mentor_amount,
        v_fee_rate,
        'pending'
      )
      returning id into v_settlement_id;

      v_settlement_created := true;
    end if;
  else
    v_settlement_id := v_existing_settlement;
  end if;

  update public.custom_request_orders
  set
    status = 'completed',
    state = 'completed',
    order_status = 'completed',
    accepted_at = coalesce(accepted_at, v_now),
    completed_at = coalesce(completed_at, v_now),
    updated_at = v_now
  where id = p_order_id;

  if v_settlement_id is not null then
    perform public.record_custom_order_escrow_payout(p_order_id);
    v_payout_done := true;
  end if;

  return jsonb_build_object(
    'ok', true,
    'settlement_created', v_settlement_created,
    'settlement_id', v_settlement_id,
    'gross', v_gross,
    'fee_rate', v_fee_rate,
    'payout_done', v_payout_done
  );
exception
  when others then
    if sqlstate = '23505' then
      select id into v_existing_settlement
      from public.custom_order_settlement_items s
      where s.custom_request_order_id = p_order_id;

      update public.custom_request_orders
      set
        status = 'completed',
        state = 'completed',
        order_status = 'completed',
        accepted_at = coalesce(accepted_at, v_now),
        completed_at = coalesce(completed_at, v_now),
        updated_at = v_now
      where id = p_order_id;

      if v_existing_settlement is not null then
        perform public.record_custom_order_escrow_payout(p_order_id);
        v_payout_done := true;
      end if;

      return jsonb_build_object(
        'ok', true,
        'settlement_created', false,
        'settlement_id', v_existing_settlement,
        'payout_done', v_payout_done,
        'reason', 'already_exists'
      );
    end if;
    raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.account_deletion_advance(p_user_id uuid, p_from text, p_to text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rows int := 0; v_col text; v_id uuid;
begin
  if p_from='pending' and p_to='locked' then
    raise exception 'USE_BEGIN_LOCKED: pending->locked must go through account_deletion_begin_locked'
      using errcode = '42501';
  end if;

  v_id := public.account_deletion_active_job_id(p_user_id);
  if v_id is null then return false; end if;

  if not (
    (p_from='locked' and p_to='purging') or
    (p_from='purging' and p_to='storage_purged') or
    (p_from='storage_purged' and p_to='finalized') or
    (p_from='finalized' and p_to='auth_soft_deleted') or
    (p_from='auth_soft_deleted' and p_to='completed')
  ) then
    raise exception 'INVALID_TRANSITION % -> %', p_from, p_to;
  end if;

  v_col := p_to || '_at';
  execute format(
    'update public.account_deletion_jobs set state=$2, %I=now(), updated_at=now() where id=$1 and state=$3',
    v_col
  ) using v_id, p_to, p_from;
  get diagnostics v_rows = row_count;
  return v_rows > 0;
end $function$

CREATE OR REPLACE FUNCTION public.account_deletion_begin_locked(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid; v_state text; v_cancelable timestamptz;
  v_consent_at timestamptz; v_consented bigint; v_balance bigint; v_rows int;
begin
  v_id := public.account_deletion_active_job_id(p_user_id);
  if v_id is null then return jsonb_build_object('ok',false,'code','JOB_NOT_FOUND'); end if;

  select j.state, j.cancelable_until, j.forfeit_consent_at, j.consented_balance_cents
    into v_state, v_cancelable, v_consent_at, v_consented
    from public.account_deletion_jobs j where j.id = v_id for update;
  if not found then return jsonb_build_object('ok',false,'code','JOB_NOT_FOUND'); end if;
  if v_state <> 'pending' then
    return jsonb_build_object('ok',false,'code','NOT_PENDING','state',v_state);
  end if;
  if v_cancelable is not null and now() < v_cancelable then
    return jsonb_build_object('ok',false,'code','CANCEL_WINDOW_OPEN','cancelable_until',v_cancelable);
  end if;

  select coalesce(w.balance_cents, 0) into v_balance
    from public.cash_wallets w where w.user_id = p_user_id for update;
  v_balance := coalesce(v_balance, 0);

  if v_balance > 0 then
    if v_consent_at is null then
      return jsonb_build_object('ok',false,'code','FORFEIT_CONSENT_REQUIRED','current_balance_cents',v_balance);
    end if;
    if v_balance > coalesce(v_consented, 0) then
      return jsonb_build_object('ok',false,'code','FORFEIT_CONSENT_STALE',
        'consented_balance_cents', v_consented, 'current_balance_cents', v_balance);
    end if;
  end if;

  update public.account_deletion_jobs
    set state='locked', locked_at=now(), updated_at=now()
    where id = v_id and state='pending';
  get diagnostics v_rows = row_count;
  if v_rows = 0 then return jsonb_build_object('ok',false,'code','NOT_PENDING'); end if;

  return jsonb_build_object('ok',true,'state','locked','job_id',v_id,'balance_cents',v_balance);
end $function$

CREATE OR REPLACE FUNCTION public.account_deletion_cancel(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_state text; v_cancelable timestamptz; v_rows int;
begin
  v_id := public.account_deletion_active_job_id(p_user_id);
  if v_id is null then return jsonb_build_object('ok',false,'code','NOT_FOUND'); end if;

  select j.state, j.cancelable_until into v_state, v_cancelable
    from public.account_deletion_jobs j where j.id = v_id for update;
  if not found then return jsonb_build_object('ok',false,'code','NOT_FOUND'); end if;
  if v_state <> 'pending' then return jsonb_build_object('ok',false,'code','NOT_CANCELABLE','state',v_state); end if;
  if v_cancelable is not null and now() > v_cancelable then
    return jsonb_build_object('ok',false,'code','CANCEL_WINDOW_PASSED');
  end if;

  update public.account_deletion_jobs
    set state='canceled', canceled_at=now(), updated_at=now()
    where id = v_id and state = 'pending';
  get diagnostics v_rows = row_count;
  if v_rows = 0 then return jsonb_build_object('ok',false,'code','NOT_CANCELABLE'); end if;
  return jsonb_build_object('ok',true,'state','canceled','job_id',v_id);
end $function$

CREATE OR REPLACE FUNCTION public.account_deletion_cancel_self()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('account_deletion_self:' || v_uid::text, 0));
  return public.account_deletion_cancel(v_uid);
end;
