CREATE OR REPLACE FUNCTION public.account_deletion_revoke_sessions(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_sessions int := 0; v_tokens int := 0;
begin
  if p_user_id is null then
    return jsonb_build_object('ok', false, 'code', 'USER_REQUIRED');
  end if;

  delete from auth.refresh_tokens rt
   where rt.session_id in (select s.id from auth.sessions s where s.user_id = p_user_id)
      or rt.user_id = p_user_id::text;
  get diagnostics v_tokens = row_count;

  delete from auth.sessions s where s.user_id = p_user_id;
  get diagnostics v_sessions = row_count;

  return jsonb_build_object(
    'ok', true,
    'sessions_deleted', v_sessions,
    'refresh_tokens_deleted', v_tokens
  );
end $function$

CREATE OR REPLACE FUNCTION public.account_deletion_self_response(p_user_id uuid, p_raw jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_job_id uuid; v_state text; v_cancelable timestamptz; v_dry boolean;
begin
  if coalesce((p_raw ->> 'ok')::boolean, false) is not true then
    return p_raw;
  end if;
  v_job_id := nullif(p_raw ->> 'job_id','')::uuid;
  select j.state, j.cancelable_until, j.dry_run into v_state, v_cancelable, v_dry
    from public.account_deletion_jobs j where j.id = v_job_id;
  return jsonb_build_object(
    'ok', true,
    'existing', coalesce((p_raw ->> 'existing')::boolean, true),
    'job_id', v_job_id,
    'state', v_state,
    'cancelable_until', v_cancelable,
    'dry_run', v_dry
  );
end $function$

CREATE OR REPLACE FUNCTION public.account_deletion_status_self()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_id uuid;
  v_job record;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;

  v_id := coalesce(public.account_deletion_active_job_id(v_uid), public.account_deletion_latest_job_id(v_uid));
  if v_id is null then
    return jsonb_build_object(
      'ok', true, 'exists', false, 'state', null,
      'cancelable_until', null, 'write_blocked', false, 'can_cancel', false);
  end if;

  select j.state, j.cancelable_until into v_job
    from public.account_deletion_jobs j where j.id = v_id;

  return jsonb_build_object(
    'ok', true,
    'exists', true,
    'state', v_job.state,
    'cancelable_until', v_job.cancelable_until,
    'write_blocked', v_job.state in
      ('locked','purging','storage_purged','finalized','auth_soft_deleted'),
    'can_cancel', v_job.state = 'pending'
      and (v_job.cancelable_until is null or now() <= v_job.cancelable_until)
  );
end $function$

CREATE OR REPLACE FUNCTION public.account_deletion_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_col text := TG_ARGV[0]; v_uid uuid;
begin
  if current_setting('ssambership.deletion_worker', true) = 'on' then
    return NEW;
  end if;
  v_uid := (to_jsonb(NEW) ->> v_col)::uuid;
  -- ★ account_deletion_write_blocked 가 아니라 내부 상태 함수를 쓴다.
  --   행 소유자가 세션 사용자와 다른 정당한 쓰기(멘토 정산 입금 등)를
  --   self-probe 제한이 막아버리던 회귀를 해소한다.
  if v_uid is not null and public.account_deletion_state_blocked(v_uid) then
    raise exception 'ACCOUNT_DELETION_IN_PROGRESS';
  end if;
  return NEW;
end $function$

CREATE OR REPLACE FUNCTION public.add_individual_question_attachment(p_question_id uuid, p_storage_path text, p_file_name text, p_mime_type text, p_message_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid  uuid := (select auth.uid());
  v_path text;
  v_id   uuid;
  v_existing_message_id uuid;
  v_created boolean := false;
  v_status text; v_susp timestamptz; v_norm text;
  v_obj_owner text;
  v_obj_meta jsonb;
  v_obj_found boolean := false;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  v_path := btrim(coalesce(p_storage_path, ''));
  if v_path = '' then
    raise exception 'INVALID_INPUT: storage_path is required' using errcode = '22023';
  end if;

  if not public.user_is_individual_question_party(p_question_id) then
    raise exception 'NOT_QUESTION_PARTY' using errcode = '42501';
  end if;

  if split_part(v_path, '/', 1) <> p_question_id::text then
    raise exception 'STORAGE_PATH_MISMATCH' using errcode = '22023';
  end if;

  if p_message_id is not null and not exists (
    select 1
    from public.individual_question_messages m
    where m.id = p_message_id
      and m.question_id = p_question_id
  ) then
    raise exception 'MESSAGE_NOT_IN_QUESTION' using errcode = '22023';
  end if;

  -- 메시지 작성자 = 호출자 가드(20260804113000): 상대방 메시지에 내 첨부를
  -- 연결하는 것을 막는다 — 타임라인 표시 방향은 연결 메시지 작성자가 정본이라
  -- 위장으로 이어진다. 자기 메시지 연결(정상 흐름 전부)은 그대로 통과한다.
  if p_message_id is not null and not exists (
    select 1
    from public.individual_question_messages m
    where m.id = p_message_id
      and m.author_id = v_uid
  ) then
    raise exception 'MESSAGE_AUTHOR_MISMATCH' using errcode = '42501';
  end if;

  -- 멱등 선조회: 이미 등록된 (question_id, storage_path) 는 기존 계약 그대로 반환
  -- (legacy 객체 읽기·기존 등록 행을 깨지 않는다 — 신규 등록만 아래에서 fail-closed)
  select a.id, a.message_id
    into v_id, v_existing_message_id
  from public.individual_question_attachments a
  where a.question_id = p_question_id
    and a.storage_path = v_path;

  if v_id is null then
    -- === 신규 등록 검증 (수렴 M2 §12.6) ===
    -- 계정 상태 4종 + 삭제 진행
    select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = v_uid;
    if not found then raise exception 'ACCOUNT_NOT_ACTIVE'; end if;
    v_norm := lower(btrim(coalesce(v_status,'')));
    if v_norm = 'banned' then raise exception 'ACCOUNT_BANNED'; end if;
    if v_norm = 'suspended' and (v_susp is null or v_susp > now()) then raise exception 'ACCOUNT_SUSPENDED'; end if;
    if v_norm not in ('active','suspended') then raise exception 'ACCOUNT_NOT_ACTIVE'; end if;
    if public.account_deletion_write_blocked(v_uid) then raise exception 'ACCOUNT_DELETION_IN_PROGRESS'; end if;

    -- Storage object 존재·소유·MIME·크기 (bucket=individual-question-attachments 고정)
    select o.owner_id, o.metadata into v_obj_owner, v_obj_meta
      from storage.objects o
     where o.bucket_id = 'individual-question-attachments'
       and o.name = v_path;
    v_obj_found := found;
    if not v_obj_found then
      raise exception 'STORAGE_OBJECT_NOT_FOUND' using errcode = '22023';
    end if;
    if v_obj_owner is null or v_obj_owner <> v_uid::text then
      raise exception 'STORAGE_OBJECT_NOT_OWNED' using errcode = '42501';
    end if;
    if v_obj_meta ? 'mimetype'
       and coalesce(nullif(btrim(p_mime_type), ''), '(none)') <> (v_obj_meta->>'mimetype') then
      raise exception 'MIME_MISMATCH' using errcode = '22023';
    end if;
    if p_mime_type is not null and btrim(p_mime_type) <> '' and not exists (
      select 1 from storage.buckets b
       where b.id = 'individual-question-attachments'
         and (b.allowed_mime_types is null or btrim(p_mime_type) = any (b.allowed_mime_types))
    ) then
      raise exception 'MIME_NOT_ALLOWED' using errcode = '22023';
    end if;
    if v_obj_meta ? 'size' and (v_obj_meta->>'size')::bigint > 20971520 then
      raise exception 'SIZE_EXCEEDED' using errcode = '22023';
    end if;

    insert into public.individual_question_attachments
      (question_id, message_id, storage_path, file_name, mime_type, author_id)
    values
      (p_question_id, p_message_id, v_path, p_file_name, p_mime_type, v_uid)
    on conflict (question_id, storage_path) do nothing
    returning id into v_id;

    if v_id is not null then
      v_created := true;
    else
      select a.id, a.message_id
        into v_id, v_existing_message_id
      from public.individual_question_attachments a
      where a.question_id = p_question_id
        and a.storage_path = v_path;

      if v_id is null then
        raise exception 'REGISTER_CONFLICT_UNRESOLVED' using errcode = '40001';
      end if;
    end if;
  end if;

  return jsonb_build_object(
    'ok',            true,
    'status',        case when v_created then 'created' else 'existing' end,
    'idempotent_hit', not v_created,
    'attachment_id', v_id,
    'question_id',   p_question_id,
    'storage_path',  v_path,
    'message_id_mismatch',
      case when v_created then false
           else coalesce(v_existing_message_id, '00000000-0000-0000-0000-000000000000'::uuid)
                is distinct from coalesce(p_message_id, '00000000-0000-0000-0000-000000000000'::uuid)
      end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_issue_user_warning(p_user_id uuid, p_reason text, p_severity text DEFAULT 'normal'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_is_service boolean := (coalesce((select auth.role()), '') = 'service_role');
  v_target_role text;
  v_reason text;
  v_severity text;
  v_warning_id uuid;
  v_active_count integer;
  v_auto_suspended boolean := false;
  v_suspended_until timestamptz;
begin
  -- caller: admin 세션 또는 service_role
  if not v_is_service and not coalesce((select public.is_admin()), false) then
    raise exception 'ADMIN_ONLY' using errcode = '42501';
  end if;
  if p_user_id is null then
    raise exception 'TARGET_REQUIRED' using errcode = '22023';
  end if;
  if v_actor is not null and v_actor = p_user_id then
    raise exception 'SELF_WARNING_FORBIDDEN' using errcode = '42501';
  end if;

  v_reason := nullif(btrim(coalesce(p_reason, '')), '');
  if v_reason is null then
    raise exception 'REASON_REQUIRED' using errcode = '22023';
  end if;
  v_severity := lower(btrim(coalesce(p_severity, 'normal')));
  if v_severity not in ('normal','severe') then
    raise exception 'SEVERITY_INVALID' using errcode = '22023';
  end if;

  select u.role into v_target_role from public.users u where u.id = p_user_id for update;
  if not found then
    raise exception 'TARGET_NOT_FOUND' using errcode = 'P0001';
  end if;
  if v_target_role = 'admin' then
    raise exception 'ADMIN_TARGET_FORBIDDEN' using errcode = '42501';
  end if;

  insert into public.user_warnings (user_id, issued_by, reason, severity, source, is_active)
  values (p_user_id, v_actor, v_reason, v_severity, 'admin', true)
  returning id into v_warning_id;

  select count(*) into v_active_count
    from public.user_warnings w
   where w.user_id = p_user_id and w.is_active = true;

  -- 3회 이상 → 7일 suspended (경고 INSERT 와 동일 트랜잭션 — 부분 성공 불가)
  if v_active_count >= 3 then
    v_suspended_until := now() + interval '7 days';
    update public.users
       set status = 'suspended',
           suspended_until = v_suspended_until,
           status_reason = 'auto_suspend_warnings_' || v_active_count,
           status_changed_at = now(),
           status_changed_by = v_actor,
           updated_at = now()
     where id = p_user_id;
    v_auto_suspended := true;
  end if;

  return jsonb_build_object(
    'ok', true,
    'contract_version', 1,
    'warning_id', v_warning_id,
    'active_warning_count', v_active_count,
    'auto_suspended', v_auto_suspended,
    'suspended_until', v_suspended_until
  );
end
$function$

CREATE OR REPLACE FUNCTION public.answer_individual_question(p_question_id uuid, p_body text)
 RETURNS SETOF individual_questions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_question public.individual_questions%rowtype;
  v_mentor_id uuid;
  v_status text; v_susp timestamptz; v_norm text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  if coalesce(btrim(p_body), '') = '' then
    raise exception 'INVALID_INPUT: body is required' using errcode = '22023';
  end if;

  select *
    into v_question
  from public.individual_questions
  where id = p_question_id
  for update;

  if not found then
    raise exception 'QUESTION_NOT_FOUND' using errcode = 'P0001';
  end if;

  -- payout 과 동일한 멘토 해석(open=claimed, direct=designated).
  v_mentor_id := coalesce(v_question.claimed_mentor_id, v_question.designated_mentor_id);
  if v_mentor_id is null or v_mentor_id <> v_uid then
    raise exception 'NOT_QUESTION_MENTOR' using errcode = '42501';
  end if;

  -- 계정 상태 4종 + 삭제 진행 + 상호 차단 + 멘토 승인 (수렴 M2 — iq_append_message 동일 게이트)
  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = v_uid;
  if not found then raise exception 'ACCOUNT_NOT_ACTIVE'; end if;
  v_norm := lower(btrim(coalesce(v_status,'')));
  if v_norm = 'banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if v_norm = 'suspended' and (v_susp is null or v_susp > now()) then raise exception 'ACCOUNT_SUSPENDED'; end if;
  if v_norm not in ('active','suspended') then raise exception 'ACCOUNT_NOT_ACTIVE'; end if;
  if public.account_deletion_write_blocked(v_uid) then raise exception 'ACCOUNT_DELETION_IN_PROGRESS'; end if;
  if public.qna_users_blocked(v_question.student_id, v_mentor_id) then raise exception 'BLOCKED'; end if;
  if not public.individual_question_user_is_approved_mentor(v_mentor_id) then
    raise exception 'MENTOR_NOT_APPROVED';
  end if;

  if v_question.status not in ('claimed', 'assigned') then
    raise exception 'NOT_ANSWERABLE_STATUS:%', v_question.status using errcode = 'P0001';
  end if;

  insert into public.individual_question_messages (question_id, author_id, body)
  values (p_question_id, v_uid, p_body);

  update public.individual_questions
  set status = 'answered',
      answered_at = coalesce(answered_at, now())
  where id = p_question_id
  returning * into v_question;

  return next v_question;
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_mentor_school_verification_admin(p_verification_id uuid, p_university_name text, p_university_id text, p_department_name text, p_major_category text, p_school_tier text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin uuid := (select auth.uid());
  v_row public.mentor_school_verifications;
  v_superseded integer := 0;
  v_correction boolean := false;
  v_previous jsonb := null;
begin
  -- (a) 관리자 전용. mentor·student·anon 은 여기서 종료된다.
  if not coalesce(public.is_admin(), false) then
    raise exception 'NOT_ADMIN' using errcode = '42501';
  end if;

  if p_verification_id is null then
    raise exception 'INVALID_INPUT: verification_id is required' using errcode = '22023';
  end if;
  if btrim(coalesce(p_university_name, '')) = ''
     or btrim(coalesce(p_university_id, '')) = ''
     or btrim(coalesce(p_department_name, '')) = ''
     or btrim(coalesce(p_major_category, '')) = ''
     or btrim(coalesce(p_school_tier, '')) = '' then
    raise exception 'INVALID_INPUT: university/department/major/tier are required' using errcode = '22023';
  end if;

  -- (b) mentor 단위 직렬화 — 같은 멘토의 서로 다른 요청이 동시에 승인되지 않도록.
  select * into v_row from public.mentor_school_verifications where id = p_verification_id;
  if not found then
    raise exception 'VERIFICATION_NOT_FOUND' using errcode = 'P0002';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('msv_approve:' || v_row.mentor_id::text, 0));

  -- 락 획득 후 재조회(대기 중 다른 트랜잭션이 상태를 바꿨을 수 있다).
  select * into v_row from public.mentor_school_verifications
   where id = p_verification_id for update;
  -- 193: 확정 가능 = 심사 대상(pending·resubmit_required) 또는 approved(잠정·확정 무관 — 확정된 행은 "정정").
  if v_row.status not in ('pending', 'resubmit_required', 'approved') then
    raise exception 'NOT_REVIEWABLE: %', v_row.status using errcode = '22023';
  end if;

  -- (c) 192: 서류 유무·경로·객체 실재는 확정 조건이 아니다 — 서류는 판단 재료이며 화면이 '서류 없음'을 보여준다.

  -- 193: 이미 확정된 approved 행(reviewed_by NOT NULL)의 재확정 = 정정. 이전 값을 감사 로그 상세에 남긴다.
  v_correction := (v_row.status = 'approved' and v_row.reviewed_by is not null);
  if v_correction then
    v_previous := jsonb_build_object(
      'school_tier', v_row.school_tier,
      'verified_major_category', v_row.verified_major_category,
      'verified_university_name', v_row.verified_university_name,
      'verified_university_id', v_row.verified_university_id,
      'verified_department_name', v_row.verified_department_name,
      'reviewed_by', v_row.reviewed_by,
      'reviewed_at', v_row.reviewed_at
    );
  end if;

  -- (d) 재승인 수명주기 — 같은 트랜잭션에서 기존 approved 를 먼저 종료시킨다.
  update public.mentor_school_verifications
     set status = 'superseded',
         updated_at = now()
   where mentor_id = v_row.mentor_id
     and status = 'approved'
     and id <> v_row.id;
  get diagnostics v_superseded = row_count;

  -- (e) 대상 행 확정(정정 시 reviewed_by · reviewed_at 이 새로 채워진다).
  update public.mentor_school_verifications
     set status = 'approved',
         verified_university_name = btrim(p_university_name),
         verified_university_id = btrim(p_university_id),
         verified_department_name = btrim(p_department_name),
         verified_major_category = btrim(p_major_category),
         school_tier = btrim(p_school_tier),
         reviewed_by = v_admin,
         reviewed_at = now(),
         reject_reason = null
   where id = v_row.id;

  -- (f) 193: 정정 감사 로그 — 이전 등급 · 이전 확정자(웹 액션의 mentor_school_verification_approve 기록과 별개).
  if v_correction then
    insert into public.admin_action_logs (admin_id, action_type, target_type, target_id, detail)
    values (
      v_admin,
      'school_tier_corrected',
      'mentor_school_verification',
      v_row.id,
      jsonb_build_object(
        'mentor_id', v_row.mentor_id,
        'previous', v_previous,
        'next', jsonb_build_object(
          'school_tier', btrim(p_school_tier),
          'verified_major_category', btrim(p_major_category),
          'verified_university_name', btrim(p_university_name),
          'verified_university_id', btrim(p_university_id),
          'verified_department_name', btrim(p_department_name),
          'reviewed_by', v_admin
        ),
        'note', '확정된 학교 등급 정정(193 A-2) — 이전 등급·이전 확정자 보존'
      )
    );
  end if;

  -- 감사 가능 최소 정보만 반환한다(서류 내용·signed URL·토큰 미포함). corrected · previous_* 는 193 additive 키.
  return jsonb_build_object(
    'verification_id', v_row.id,
    'mentor_id', v_row.mentor_id,
    'status', 'approved',
    'superseded_count', v_superseded,
    'reviewed_by', v_admin,
    'corrected', v_correction,
    'previous_school_tier', case when v_correction then v_row.school_tier end,
    'previous_reviewed_by', case when v_correction then v_row.reviewed_by end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_refund_request_admin(p_refund_id uuid, p_admin_id uuid, p_admin_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  e public.subscription_billing_events%rowtype; v_event uuid;
  r public.refunds%rowtype; v_amount bigint; v_settlement_status text;
  v_idem text := 'refund_credit:' || p_refund_id::text; v_ledger_id uuid; v_existing_delta bigint; v_wu int; v_admin_ok boolean;
begin
  if coalesce(auth.role(),'')<>'service_role' and auth.uid() is distinct from p_admin_id then raise exception 'ADMIN_REQUIRED'; end if;
  if p_refund_id is null then return jsonb_build_object('ok', false, 'message', '환불 ID가 필요합니다.'); end if;
  if p_admin_id is null then return jsonb_build_object('ok', false, 'message', '관리자 ID가 필요합니다.'); end if;
  select exists(select 1 from public.users u where u.id = p_admin_id and u.role = 'admin') into v_admin_ok;
  if not coalesce(v_admin_ok, false) then raise exception 'ADMIN_REQUIRED'; end if;
  select * into r from public.refunds where id=p_refund_id;
  if r.subscription_id is not null then
    v_event:=r.billing_event_id;
    if v_event is null and r.payment_id is not null then
      select case when count(*)=1 then (array_agg(id))[1] end into v_event from public.subscription_billing_events where payment_id=r.payment_id and subscription_id=r.subscription_id and status='succeeded' and event_type in ('initial','renewal');
    end if;
    if v_event is null then return jsonb_build_object('ok',false,'code','SERVICE_PERIOD_UNRESOLVED'); end if;
    perform core_private.lock_service_period_finance(v_event);
    select * into e from public.subscription_billing_events where id=v_event;
    select * into r from public.refunds where id=p_refund_id for update;
    if r.status<>'pending' then return jsonb_build_object('ok',true,'noop',true,'refund_id',r.id,'status',r.status); end if;
    if not core_private.refund_matches_service_period(r,e) or r.user_id<>e.student_id then raise exception 'REFUND_PERIOD_BINDING_MISMATCH'; end if;
    if e.voucher_redemption_id is not null then return jsonb_build_object('ok',false,'code','VOUCHER_EXTERNAL_REFUND_REQUIRED'); end if;
    if r.amount_cents is null or r.amount_cents<=0 or r.amount_cents>e.amount_cents then raise exception 'REFUND_AMOUNT_INVALID'; end if;
    if exists(select 1 from public.subscription_settlement_items where billing_event_id=e.id and status='paid') then
      insert into public.service_period_financial_holds(billing_event_id,state,reason) values(e.id,'adjustment_required','refund_after_payout') on conflict(billing_event_id) do update set state='adjustment_required',reason='refund_after_payout',updated_at=now();
      return jsonb_build_object('ok',false,'code','ADJUSTMENT_REQUIRED');
    end if;
    if e.funding_source='pg' or exists(select 1 from public.payments p where p.id=e.payment_id and p.pg_tx_id is not null) then
      -- A trusted adapter must record the confirmed provider cancellation before finalization.
      if r.pg_cancellation_id is null or r.pg_cancelled_at is null then return jsonb_build_object('ok',false,'code','PG_REFUND_CONFIRMATION_REQUIRED'); end if;
    else
      insert into public.cash_ledger(user_id,delta_cents,reason,ref_type,ref_id,idempotency_key)
      values(r.user_id,r.amount_cents,'refund_approved','refunds',r.id,v_idem) on conflict(idempotency_key) do nothing returning id into v_ledger_id;
      if v_ledger_id is null then
        if not exists(select 1 from public.cash_ledger where idempotency_key=v_idem and delta_cents=r.amount_cents and user_id=r.user_id and ref_id=r.id) then raise exception 'REFUND_LEDGER_BINDING_MISMATCH'; end if;
      else
        insert into public.cash_wallets(user_id,balance_cents) values(r.user_id,0) on conflict(user_id) do nothing;
        update public.cash_wallets set balance_cents=balance_cents+r.amount_cents where user_id=r.user_id;
      end if;
    end if;
    update public.refunds set billing_event_id=e.id,status='succeeded',processed_at=clock_timestamp(),processed_by=p_admin_id,admin_note=p_admin_note where id=r.id;
    -- Only this period's immutable payment; never the subscription's newer payment reference.
    if e.payment_id is not null then update public.payments set status='refunded',updated_at=now() where id=e.payment_id; end if;
    if r.amount_cents=e.amount_cents then delete from public.service_period_financial_holds where billing_event_id=e.id and state='hold'; end if;
    if r.amount_cents<e.amount_cents then
      insert into public.service_period_financial_holds(billing_event_id,state,reason) values(e.id,'hold','partial_refund_allocation_unresolved') on conflict(billing_event_id) do nothing;
    end if;
    return jsonb_build_object('ok',true,'noop',false,'refund_id',r.id,'amount_cents',r.amount_cents);
  end if;
  select * into r from public.refunds where id = p_refund_id for update;
  if not found then return jsonb_build_object('ok', false, 'message', '환불 요청을 찾을 수 없습니다.'); end if;
  if r.status is distinct from 'pending' then
    return jsonb_build_object('ok', true, 'noop', true, 'refund_id', p_refund_id, 'message', '이미 처리되었거나 대기 상태가 아닙니다.', 'status', r.status);
  end if;
  if r.custom_request_order_id is not null then
    select s.status into v_settlement_status from public.custom_order_settlement_items s where s.custom_request_order_id = r.custom_request_order_id limit 1;
    if found and v_settlement_status = 'paid' then
      return jsonb_build_object('ok', false, 'message', '이미 정산 지급이 완료된 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.');
    end if;
  end if;
  if r.payment_id is not null and (r.subscription_id is not null or coalesce(r.request_type, '') = 'subscription_prorated') then
    select s.status into v_settlement_status from public.subscription_settlement_items s where s.payment_id = r.payment_id and s.status = 'paid' limit 1;
    if found then return jsonb_build_object('ok', false, 'message', '이미 멘토 정산 지급이 완료된 구독 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.'); end if;
  end if;
  if r.custom_request_order_id is not null then
    perform public.record_custom_order_escrow_refund(r.custom_request_order_id);
    update public.refunds set status='succeeded', processed_at=now(), processed_by=p_admin_id, admin_note=p_admin_note, updated_at=now() where id=r.id;
    return jsonb_build_object('ok', true, 'noop', false, 'refund_id', r.id, 'kind', 'custom_order_escrow', 'message', '맞춤의뢰 환불이 승인되었습니다.');
  end if;
  if r.amount_cents is null or r.amount_cents <= 0 then raise exception '환불 금액이 설정되지 않아 자동 승인할 수 없습니다.'; end if;
  v_amount := r.amount_cents;
  if v_amount > 1000000000 then return jsonb_build_object('ok', false, 'message', '환불 금액이 허용 한도를 초과합니다.'); end if;
  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
  values (r.user_id, v_amount, 'refund_approved', 'refunds', r.id, v_idem) on conflict (idempotency_key) do nothing returning id into v_ledger_id;
  if v_ledger_id is null then
    select cl.delta_cents into v_existing_delta from public.cash_ledger cl where cl.idempotency_key = v_idem limit 1;
    if not found then raise exception 'REFUND_LEDGER_IDEMPOTENT_MISS' using errcode = 'P0001'; end if;
    if v_existing_delta is distinct from v_amount then raise exception 'REFUND_LEDGER_AMOUNT_MISMATCH' using errcode = 'P0001'; end if;
  end if;
  if v_ledger_id is not null then
    insert into public.cash_wallets (user_id, balance_cents) values (r.user_id, 0) on conflict (user_id) do nothing;
    update public.cash_wallets w set balance_cents = w.balance_cents + v_amount where w.user_id = r.user_id;
    get diagnostics v_wu = row_count;
    if coalesce(v_wu, 0) = 0 then raise exception 'CASH_WALLET_UPDATE_FAILED' using errcode = 'P0001'; end if;
  end if;
  update public.refunds set status='succeeded', processed_at=now(), processed_by=p_admin_id, admin_note=p_admin_note, updated_at=now() where id=r.id;
  if r.payment_id is not null then update public.payments p set status='refunded', updated_at=now() where p.id = r.payment_id; end if;
  if r.payment_id is not null then update public.subscriptions s set status='canceled', updated_at=now() where s.payment_id = r.payment_id and s.status is distinct from 'canceled'; end if;
  return jsonb_build_object('ok', true, 'noop', false, 'refund_id', r.id, 'ledger_inserted', (v_ledger_id is not null), 'amount_cents', v_amount, 'message', '환불이 승인되었습니다.');
end; $function$

CREATE OR REPLACE FUNCTION public.cc_sync_board_delete_to_canonical()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rows int;
begin
  if public.comment_sync_in_progress() then return old; end if;
  perform set_config('app.comment_sync', '1', true);

  if old.canonical_comment_id is not null then
    update public.comments
       set is_deleted = true,
           deleted_at = coalesce(deleted_at, old.deleted_at, now()),
           deleted_by = coalesce(deleted_by, old.deleted_by)
     where id = old.canonical_comment_id;
  else
    update public.comments
       set is_deleted = true,
           deleted_at = coalesce(deleted_at, old.deleted_at, now()),
           deleted_by = coalesce(deleted_by, old.deleted_by)
     where legacy_comment_id = old.id;
  end if;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    raise exception 'COMMENT_BRIDGE_TARGET_MISSING';
  end if;

  perform set_config('app.comment_sync', '0', true);
  return old;
end;
$function$

CREATE OR REPLACE FUNCTION public.cc_sync_board_to_canonical()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_canonical uuid;
  v_target public.comments;
begin
  if public.comment_sync_in_progress() then return new; end if;
  perform set_config('app.comment_sync', '1', true);

  if new.canonical_comment_id is not null then
    select * into v_target from public.comments
    where id = new.canonical_comment_id for update;
    if not found then
      raise exception 'COMMENT_BRIDGE_TARGET_MISSING';
    end if;
    if v_target.post_id is distinct from new.post_id then
      raise exception 'COMMENT_BRIDGE_POST_MISMATCH';
    end if;
    if v_target.author_id is distinct from new.author_id then
      raise exception 'COMMENT_BRIDGE_AUTHOR_MISMATCH';
    end if;
    update public.comments
      set content = new.body,
          deleted_at = new.deleted_at,
          deleted_by = new.deleted_by,
          is_deleted = (new.status <> 'visible' or new.deleted_at is not null)
    where id = new.canonical_comment_id;
  else
    insert into public.comments (post_id, author_id, content, is_deleted, created_at, legacy_comment_id, deleted_at, deleted_by)
    values (new.post_id, new.author_id, new.body, (new.status <> 'visible' or new.deleted_at is not null), new.created_at, new.id,
            new.deleted_at, new.deleted_by)
    on conflict (legacy_comment_id) where legacy_comment_id is not null
    do update set content = excluded.content, is_deleted = excluded.is_deleted,
                  deleted_at = excluded.deleted_at, deleted_by = excluded.deleted_by
    returning id into v_canonical;
    if v_canonical is null then
      select id into v_canonical from public.comments where legacy_comment_id = new.id;
    end if;
    update public.community_comments set canonical_comment_id = v_canonical where id = new.id;
  end if;

  perform set_config('app.comment_sync', '0', true);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.cc_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if public.comment_sync_in_progress() then return new; end if;
  if current_user not in ('authenticated', 'anon') then return new; end if;

  if tg_op = 'INSERT' then
    if new.canonical_comment_id is not null then
      raise exception 'CC_CANONICAL_ID_FORBIDDEN';
    end if;
    return new;
  end if;

  if new.canonical_comment_id is distinct from old.canonical_comment_id
     or new.id is distinct from old.id
     or new.post_id is distinct from old.post_id
     or new.post_type is distinct from old.post_type
     or new.author_id is distinct from old.author_id
     or new.created_at is distinct from old.created_at then
    raise exception 'CC_PROTECTED_FIELDS_IMMUTABLE';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.check_free_question_usage_limits()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  per_mentor_count integer;
  total_count integer;
  signup_at timestamptz;
begin
  select created_at
  into signup_at
  from public.users
  where id = new.student_id;

  if signup_at is null then
    raise exception 'FREE_QUESTION_STUDENT_NOT_FOUND'
      using errcode = 'P0003';
  end if;

  if signup_at + interval '7 days' < now() then
    raise exception 'FREE_QUESTION_EXPIRED'
      using errcode = 'P0003';
  end if;

  select count(*)::integer
  into per_mentor_count
  from public.free_question_usage
  where student_id = new.student_id
    and mentor_id = new.mentor_id;

  if per_mentor_count >= 3 then
    raise exception 'FREE_QUESTION_PER_MENTOR_LIMIT'
      using errcode = 'P0001';
  end if;

  select count(*)::integer
  into total_count
  from public.free_question_usage
  where student_id = new.student_id;

  if total_count >= 7 then
    raise exception 'FREE_QUESTION_TOTAL_LIMIT'
      using errcode = 'P0002';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_individual_question(p_question_id uuid, p_mentor_id uuid)
 RETURNS individual_question_escrow_result
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_question public.individual_questions%rowtype;
begin
  if p_question_id is null or p_mentor_id is null then
    return (false, 'invalid_input', 'question_id and mentor_id are required', p_question_id, null, null, null)::public.individual_question_escrow_result;
  end if;

  if not public.individual_question_user_is_approved_mentor(p_mentor_id) then
    return (false, 'mentor_not_approved', 'mentor is not approved for individual questions', p_question_id, null, null, null)::public.individual_question_escrow_result;
  end if;

  update public.individual_questions
  set
    claimed_mentor_id = p_mentor_id,
    claimed_at = now(),
    status = 'claimed'
  where id = p_question_id
    and question_type = 'open'
    and status = 'open'
    and claimed_mentor_id is null
    and (expires_at is null or expires_at > now())
    and student_id <> p_mentor_id
  returning * into v_question;

  if not found then
    return (false, 'not_available', 'question is already claimed, expired, or unavailable', p_question_id, null, null, null)::public.individual_question_escrow_result;
  end if;

  return (true, 'claimed', 'individual question claimed', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_individual_question_as_mentor(p_question_id uuid)
 RETURNS individual_question_escrow_result
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_res public.individual_question_escrow_result;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  if p_question_id is null then
    raise exception 'INVALID_INPUT: question_id is required' using errcode = '22023';
  end if;

  -- 🔴 v2 코어 호출(자격 게이트 일관). 멘토 = auth.uid() 강제.
  v_res := public.claim_individual_question_v2(p_question_id, v_uid);

  if not v_res.ok then
    raise exception 'INDIVIDUAL_QUESTION_CLAIM_FAILED:%:%', v_res.code, v_res.message
      using errcode = 'P0001';
  end if;

  return v_res;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_individual_question_v2(p_question_id uuid, p_mentor_id uuid)
 RETURNS individual_question_escrow_result
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_question public.individual_questions%rowtype;
  v_required_school_tier text;
  v_required_major_category text;
  v_verified_school_tier text;
  v_verified_major_category text;
  v_question_subject text;
  v_mentor_subjects text[];
begin
  if p_question_id is null or p_mentor_id is null then
    return (false, 'invalid_input', 'question_id and mentor_id are required', p_question_id, null, null, null)::public.individual_question_escrow_result;
  end if;

  if not public.individual_question_user_is_approved_mentor(p_mentor_id) then
    return (false, 'mentor_not_approved', 'mentor is not approved for individual questions', p_question_id, null, null, null)::public.individual_question_escrow_result;
  end if;

  select
    q.required_school_tier,
    q.required_major_category,
    q.subject
    into v_required_school_tier, v_required_major_category, v_question_subject
  from public.individual_questions q
  where q.id = p_question_id
    and q.question_type = 'open'
    and q.status = 'open'
    and q.claimed_mentor_id is null
    and (q.expires_at is null or q.expires_at > now())
    and q.student_id <> p_mentor_id;

  if not found then
    return (false, 'not_available', 'question is already claimed, expired, or unavailable', p_question_id, null, null, null)::public.individual_question_escrow_result;
  end if;

  -- [과목 게이트] 멘토 담당 과목(teaching_subjects)이 아닌 질문은 맡을 수 없다. 과목 없는(null) 질문은 허용.
  if v_question_subject is not null then
    select mp.teaching_subjects into v_mentor_subjects
    from public.mentor_profiles mp
    where mp.user_id = p_mentor_id;

    if not (v_question_subject = any(coalesce(v_mentor_subjects, array[]::text[]))) then
      return (false, 'mentor_subject_not_met', 'mentor does not teach this subject', p_question_id, null, null, null)::public.individual_question_escrow_result;
    end if;
  end if;

  if v_required_school_tier is not null or v_required_major_category is not null then
    select
      msv.school_tier,
      msv.verified_major_category
      into v_verified_school_tier, v_verified_major_category
    from public.mentor_school_verifications msv
    where msv.mentor_id = p_mentor_id
      and msv.status = 'approved'
    order by coalesce(msv.reviewed_at, msv.updated_at, msv.created_at) desc, msv.created_at desc
    limit 1;

    if not found then
      return (false, 'mentor_school_verification_required', 'mentor school verification is required for this question', p_question_id, null, null, null)::public.individual_question_escrow_result;
    end if;

    if v_required_school_tier is not null
       and coalesce(v_verified_school_tier, '') <> v_required_school_tier then
      return (false, 'mentor_qualification_not_met', 'mentor school tier does not match this question requirement', p_question_id, null, null, null)::public.individual_question_escrow_result;
    end if;

    if v_required_major_category is not null
       and coalesce(v_verified_major_category, '') <> v_required_major_category then
      return (false, 'mentor_qualification_not_met', 'mentor major category does not match this question requirement', p_question_id, null, null, null)::public.individual_question_escrow_result;
    end if;
  end if;

  update public.individual_questions
  set
    claimed_mentor_id = p_mentor_id,
    claimed_at = now(),
    status = 'claimed'
  where id = p_question_id
    and question_type = 'open'
    and status = 'open'
    and claimed_mentor_id is null
    and (expires_at is null or expires_at > now())
    and student_id <> p_mentor_id
  returning * into v_question;

  if not found then
    return (false, 'not_available', 'question is already claimed, expired, or unavailable', p_question_id, null, null, null)::public.individual_question_escrow_result;
  end if;

  return (true, 'claimed', 'individual question claimed', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.com_notify_new_order_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_student uuid;
  v_mentor uuid;
  v_recipient uuid;
  v_sender_role text;
begin
  select o.student_id, o.mentor_id into v_student, v_mentor
  from public.custom_request_orders o where o.id = NEW.custom_request_order_id;
  if NEW.author_id = v_student then
    v_recipient := v_mentor; v_sender_role := 'student';
  elsif NEW.author_id = v_mentor then
    v_recipient := v_student; v_sender_role := 'mentor';
  else
    v_recipient := null;
  end if;
  if v_recipient is not null and v_recipient is distinct from NEW.author_id then
    perform public.record_domain_notification(
      v_recipient,
      'new_order_message:' || NEW.id::text,
      'new_order_message:' || NEW.id::text,
      'new_order_message',
      '주문방에 새 메시지가 왔어요',
      public.notification_display_name(NEW.author_id) || '님이 메시지를 보냈습니다.',
      '/custom-request/orders/' || NEW.custom_request_order_id::text,
      jsonb_build_object('order_id', NEW.custom_request_order_id, 'sender_id', NEW.author_id,
        'sender_role', v_sender_role, 'message_id', NEW.id),
      jsonb_build_object('order_id', NEW.custom_request_order_id, 'message_id', NEW.id));
  end if;
  return NEW;
end $function$

CREATE OR REPLACE FUNCTION public.comments_mirror_delete_to_legacy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.comment_sync_in_progress() then return old; end if;
  perform set_config('app.comment_sync', '1', true);
  update public.community_comments
     set status = 'hidden',
         deleted_at = coalesce(deleted_at, old.deleted_at, now()),
         deleted_by = coalesce(deleted_by, old.deleted_by)
  where canonical_comment_id = old.id
     or (old.legacy_comment_id is not null and id = old.legacy_comment_id);
  perform set_config('app.comment_sync', '0', true);
  return old;
end;
$function$

CREATE OR REPLACE FUNCTION public.comments_mirror_to_legacy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_body text;
  v_rows int;
  v_status text;
begin
  if public.comment_sync_in_progress() then return new; end if;
  perform set_config('app.comment_sync', '1', true);

  v_body := left(coalesce(new.content, ''), 1000);
  -- 194: 숨김(is_deleted 이면서 삭제는 아님)만 hidden. 삭제는 deleted_at 으로만 전달한다.
  v_status := case when coalesce(new.is_deleted, false) and new.deleted_at is null then 'hidden' else 'visible' end;

  if new.legacy_comment_id is not null then
    if char_length(btrim(v_body)) >= 1 then
      update public.community_comments
        set body = v_body,
            status = v_status,
            deleted_at = new.deleted_at,
            deleted_by = new.deleted_by,
            canonical_comment_id = new.id
      where id = new.legacy_comment_id
        and (canonical_comment_id = new.id or canonical_comment_id is null);
    else
      update public.community_comments
        set status = v_status,
            deleted_at = new.deleted_at,
            deleted_by = new.deleted_by,
            canonical_comment_id = new.id
      where id = new.legacy_comment_id
        and (canonical_comment_id = new.id or canonical_comment_id is null);
    end if;
    get diagnostics v_rows = row_count;
    if v_rows = 0 then
      raise exception 'COMMENT_BRIDGE_LEGACY_MISSING';
    end if;
  else
    if char_length(btrim(v_body)) >= 1 then
      insert into public.community_comments (post_id, post_type, author_id, body, status, created_at, canonical_comment_id, deleted_at, deleted_by)
      values (new.post_id, 'board', new.author_id, v_body, v_status,
              coalesce(new.created_at, now()), new.id, new.deleted_at, new.deleted_by)
      on conflict (canonical_comment_id) where canonical_comment_id is not null
      do update set body = excluded.body, status = excluded.status,
                    deleted_at = excluded.deleted_at, deleted_by = excluded.deleted_by;
    end if;
  end if;

  perform set_config('app.comment_sync', '0', true);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.comments_set_author_label()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_nickname text;
  v_role     text;
BEGIN
  IF tg_op = 'UPDATE' THEN
    -- snapshot(author_label·author_role) 변조 명시 거부 — silent no-op 금지 (§10.4 ③).
    -- 식별자는 163 보호필드 정본(COMMENT_PROTECTED_FIELDS_IMMUTABLE) 재사용 — 헤더 참조.
    RAISE EXCEPTION 'COMMENT_PROTECTED_FIELDS_IMMUTABLE';
  END IF;
  -- INSERT: 클라이언트·브리지 입력을 신뢰하지 않고 서버 규칙으로 무조건 덮어쓴다.
  SELECT u.nickname, u.role INTO v_nickname, v_role
    FROM public.users u WHERE u.id = new.author_id;
  IF FOUND THEN
    new.author_label := coalesce(nullif(btrim(v_nickname), ''), '쌤버십 사용자');
    new.author_role  := CASE WHEN v_role IN ('student', 'mentor') THEN v_role END;
  ELSE
    -- 사용자 행 부재(이론상 FK 로 차단되나 규칙을 코드로 고정) → fallback.
    new.author_label := '쌤버십 사용자';
    new.author_role  := NULL;
  END IF;
  RETURN new;
END $function$

CREATE OR REPLACE FUNCTION public.comments_sync_deleted_flag()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  -- 브리지 안에서는 브리지가 is_deleted 를 (숨김 OR 삭제) 로 직접 계산한다.
  if public.comment_sync_in_progress() then return new; end if;

  if tg_op = 'INSERT' then
    if new.deleted_at is not null then new.is_deleted := true; end if;
    return new;
  end if;

  if new.deleted_at is distinct from old.deleted_at then
    -- 삭제/복원이 명시된 갱신: 플래그가 결과를 따른다(복원 = 다시 보임).
    new.is_deleted := (new.deleted_at is not null);
  elsif new.deleted_at is not null then
    -- 삭제된 행은 숨김 플래그를 풀어도 계속 안 보인다(삭제가 숨김보다 강하다).
    new.is_deleted := true;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.comments_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_parent public.comments;
begin
  if public.comment_sync_in_progress() then
    return coalesce(new, old);
  end if;
  if current_user not in ('authenticated', 'anon') then
    return coalesce(new, old);
  end if;

  if tg_op = 'DELETE' then
    if coalesce((select public.is_admin()), false) then return old; end if;
    raise exception 'COMMENT_HARD_DELETE_FORBIDDEN';
  end if;

  if tg_op = 'INSERT' then
    if new.legacy_comment_id is not null then
      raise exception 'COMMENT_LEGACY_ID_FORBIDDEN';
    end if;
    if new.parent_id is not null then
      select * into v_parent from public.comments where id = new.parent_id;
      if not found then raise exception 'COMMENT_PARENT_NOT_FOUND'; end if;
      if v_parent.post_id is distinct from new.post_id then
        raise exception 'COMMENT_PARENT_POST_MISMATCH';
      end if;
      if v_parent.parent_id is not null then
        raise exception 'COMMENT_DEPTH_EXCEEDED';
      end if;
    end if;
    return new;
  end if;

  if new.id is distinct from old.id
     or new.post_id is distinct from old.post_id
     or new.author_id is distinct from old.author_id
     or new.parent_id is distinct from old.parent_id
     or new.created_at is distinct from old.created_at
     or new.legacy_comment_id is distinct from old.legacy_comment_id
     or new.like_count is distinct from old.like_count then
    raise exception 'COMMENT_PROTECTED_FIELDS_IMMUTABLE';
  end if;
  -- 194: deleted_by = auth.uid() 만 · 복원은 관리자만 · deleted_by 단독 변경 금지(RLS 가 작성자 직접 soft delete 를 먼저 거부하므로 심층 방어)
  if new.deleted_at is distinct from old.deleted_at then
    if new.deleted_at is null then
      if not coalesce((select public.is_admin()), false) then
        raise exception 'COMMENT_RESTORE_ADMIN_ONLY';
      end if;
    elsif new.deleted_by is distinct from (select auth.uid()) then
      raise exception 'COMMENT_DELETED_BY_MISMATCH';
    end if;
  elsif new.deleted_by is distinct from old.deleted_by then
    raise exception 'COMMENT_PROTECTED_FIELDS_IMMUTABLE';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.community_comment_soft_delete_self(p_comment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_row public.community_comments%rowtype;
  v_status text;
  v_susp timestamptz;
  v_norm text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  select * into v_row from public.community_comments where id = p_comment_id for update;
  if not found then
    raise exception 'COMMENT_NOT_FOUND' using errcode = 'P0001';
  end if;
  if v_row.post_type <> 'shortform' then
    raise exception 'COMMENT_TYPE_NOT_SUPPORTED' using errcode = '22023';
  end if;
  if v_row.author_id is distinct from v_uid then
    raise exception 'COMMENT_NOT_OWNED' using errcode = '42501';
  end if;

  -- 계정 게이트 (Build 13 판정과 동일: banned·유효 suspended·unknown/deleted·삭제 진행 차단)
  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = v_uid;
  if not found then raise exception 'ACCOUNT_NOT_ACTIVE'; end if;
  v_norm := lower(btrim(coalesce(v_status,'')));
  if v_norm = 'banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if v_norm = 'suspended' and (v_susp is null or v_susp > now()) then raise exception 'ACCOUNT_SUSPENDED'; end if;
  if v_norm not in ('active','suspended') then raise exception 'ACCOUNT_NOT_ACTIVE'; end if;
  if public.account_deletion_write_blocked(v_uid) then raise exception 'ACCOUNT_DELETION_IN_PROGRESS'; end if;

  -- 194: 삭제 = deleted_at/deleted_by (구 본문이 status 에 쓰던 삭제 값은 status CHECK(visible·hidden)가 막던 경로)
  if v_row.deleted_at is not null then
    return jsonb_build_object('ok', true, 'contract_version', 1, 'comment_id', p_comment_id, 'idempotent_hit', true);
  end if;
  if v_row.status <> 'visible' then
    -- 관리자 hidden 처리된 댓글은 본인이 삭제로 덮지 못한다 (moderation 유지)
    raise exception 'COMMENT_MODERATED' using errcode = '42501';
  end if;

  update public.community_comments set deleted_at = now(), deleted_by = v_uid where id = p_comment_id;

  return jsonb_build_object('ok', true, 'contract_version', 1, 'comment_id', p_comment_id, 'idempotent_hit', false);
end
$function$

CREATE OR REPLACE FUNCTION public.community_comments_set_author_label()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_nickname text;
BEGIN
  IF tg_op = 'UPDATE' THEN
    -- board 행 snapshot(author_label) 변조 명시 거부 — 식별자는 164 정본 재사용.
    RAISE EXCEPTION 'CC_PROTECTED_FIELDS_IMMUTABLE';
  END IF;
  -- INSERT(post_type='board' 한정 — 트리거 WHEN): 서버 규칙 덮어쓰기.
  SELECT u.nickname INTO v_nickname
    FROM public.users u WHERE u.id = new.author_id;
  IF FOUND THEN
    new.author_label := coalesce(nullif(btrim(v_nickname), ''), '쌤버십 사용자');
  ELSE
    -- community_comments.author_id 는 auth.users FK — public.users 행 부재 가능 → fallback.
    new.author_label := '쌤버십 사용자';
  END IF;
  RETURN new;
END $function$

CREATE OR REPLACE FUNCTION public.community_post_view_record_v2(p_post_id uuid, p_event_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_inserted boolean := false;
begin
  if p_post_id is null or p_event_key is null then
    raise exception 'INVALID_INPUT' using errcode = '22023';
  end if;
  -- 게시 상태 공개 글만 계수(숏폼 v2 와 동일 규약)
  if not exists (select 1 from public.community_posts cp
                  where cp.id = p_post_id and cp.status = 'published'
                    and cp.deleted_at is null) then
    raise exception 'POST_NOT_FOUND' using errcode = 'P0001';
  end if;

  insert into public.community_post_view_events (post_id, event_key, viewer_user_id)
  values (p_post_id, p_event_key, v_uid)
  on conflict (post_id, event_key) do nothing;
  v_inserted := found;

  if v_inserted then
    update public.community_posts
       set view_count = view_count + 1
     where id = p_post_id;
  end if;

  -- 중복 key 는 idempotent success (계수 증가 없음)
  return jsonb_build_object('ok', true, 'contract_version', 1, 'incremented', v_inserted);
end
$function$

CREATE OR REPLACE FUNCTION public.community_refresh_post_comment_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  pid uuid;
begin
  pid := coalesce(new.post_id, old.post_id);
  update public.community_posts p
  set comment_count = (
    select count(*)::int from public.comments c
    where c.post_id = pid and c.is_deleted = false and c.deleted_at is null
