 SELECT (amount*100)::bigint INTO v_amount FROM public.payments WHERE id=p_payment_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PAYMENT_NOT_FOUND'; END IF;
 IF v_amount IS NULL OR v_amount<=0 OR v_amount>2147483647 THEN RAISE EXCEPTION 'PLAN_AMOUNT_INVALID'; END IF;
 RETURN core_private.subscription_checkout_confirm_impl(p_payment_id,p_plan_id,v_amount::integer,p_idempotency_key);
END $function$

