CREATE OR REPLACE FUNCTION public.create_individual_question_as_student(p_question_type text, p_title text, p_body text, p_amount_cents integer DEFAULT NULL::integer, p_designated_mentor_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text)
 RETURNS SETOF individual_questions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_type text := lower(trim(coalesce(p_question_type, '')));
  v_idem text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  v_price int;
  v_res public.individual_question_escrow_result;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  if v_type not in ('direct', 'open') then
    raise exception 'INVALID_INPUT: question_type must be direct or open'
      using errcode = '22023';
  end if;

  if length(trim(coalesce(p_title, ''))) = 0
     or length(trim(coalesce(p_body, ''))) = 0 then
    raise exception 'INVALID_INPUT: title and body are required'
      using errcode = '22023';
  end if;

  -- 가격 결정: open 은 앱이 보낸 금액, direct 은 멘토 가격표에서 조회.
  if v_type = 'direct' then
    if p_designated_mentor_id is null then
      raise exception 'INVALID_INPUT: designated_mentor_id is required for direct'
        using errcode = '22023';
    end if;

    select amount_cents
      into v_price
    from public.mentor_individual_question_pricing
    where mentor_id = p_designated_mentor_id;

    if v_price is null then
      raise exception 'MENTOR_PRICE_NOT_SET' using errcode = 'P0001';
    end if;
  else
    v_price := p_amount_cents;
    if v_price is null or v_price <= 0 then
      raise exception 'INVALID_INPUT: amount_cents must be positive for open'
        using errcode = '22023';
    end if;
  end if;

  -- 멱등성 키: 앱이 안 보내면 랜덤 생성(코어 NOT NULL 충족용).
  if v_idem is null then
    v_idem := 'iqc:' || gen_random_uuid()::text;
  end if;

  -- 🔴 v2 코어 호출(자격 게이트 일관). 자격 파라미터는 null 만 전달.
  v_res := public.create_individual_question_with_hold_v2(
    v_uid,                       -- p_student_id (self only)
    v_type,                      -- p_question_type
    p_designated_mentor_id,      -- p_mentor_id (direct only; null for open)
    null,                        -- p_subject
    null,                        -- p_topic
    p_title,                     -- p_title
    p_body,                      -- p_body
    v_price,                     -- p_price_cents
    v_idem,                      -- p_idempotency_key
    null,                        -- p_required_school_tier
    null                         -- p_required_major_category
  );

  if not v_res.ok then
    raise exception 'INDIVIDUAL_QUESTION_CREATE_FAILED:%:%', v_res.code, v_res.message
      using errcode = 'P0001';
  end if;

  return query
    select * from public.individual_questions where id = v_res.question_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_individual_question_with_hold(p_student_id uuid, p_question_type text, p_mentor_id uuid, p_subject text, p_topic text, p_title text, p_body text, p_price_cents integer, p_idempotency_key text)
 RETURNS individual_question_escrow_result
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_type text := lower(trim(coalesce(p_question_type, '')));
  v_status text;
  v_idem text := trim(coalesce(p_idempotency_key, ''));
  v_question public.individual_questions%rowtype;
  v_ledger_id uuid;
  v_wallet_balance bigint;
  v_wallet_rows int;
begin
  if p_student_id is null then
    return (false, 'invalid_student', 'student_id is required', null, null, null, null)::public.individual_question_escrow_result;
  end if;

  if not exists (select 1 from public.users u where u.id = p_student_id and u.role = 'student') then
    return (false, 'invalid_student', 'student must be a student user', null, null, null, null)::public.individual_question_escrow_result;
  end if;

  if v_type not in ('direct', 'open') then
    return (false, 'invalid_type', 'question_type must be direct or open', null, null, null, null)::public.individual_question_escrow_result;
  end if;

  if v_type = 'direct' and p_mentor_id is null then
    return (false, 'mentor_required', 'direct question requires mentor_id', null, null, null, null)::public.individual_question_escrow_result;
  end if;

  if v_type = 'direct' and not public.individual_question_user_is_approved_mentor(p_mentor_id) then
    return (false, 'mentor_not_approved', 'mentor is not approved for individual questions', null, null, null, null)::public.individual_question_escrow_result;
  end if;

  if p_price_cents is null or p_price_cents <= 0 then
    return (false, 'invalid_price', 'price_cents must be positive', null, null, null, null)::public.individual_question_escrow_result;
  end if;

  if p_price_cents > 1000000000 then
    return (false, 'price_too_large', 'price_cents is too large', null, null, null, null)::public.individual_question_escrow_result;
  end if;

  if length(v_idem) = 0 then
    return (false, 'invalid_idempotency_key', 'idempotency_key is required', null, null, null, null)::public.individual_question_escrow_result;
  end if;

  if length(trim(coalesce(p_title, ''))) = 0 or length(trim(coalesce(p_body, ''))) = 0 then
    return (false, 'invalid_content', 'title and body are required', null, null, null, null)::public.individual_question_escrow_result;
  end if;

  select *
    into v_question
  from public.individual_questions
  where create_idempotency_key = v_idem;

  if found then
    select balance_cents
      into v_wallet_balance
    from public.cash_wallets
    where user_id = p_student_id;

    return (
      true,
      'already_exists',
      'individual question already created for idempotency key',
      v_question.id,
      v_question.status,
      v_question.hold_ledger_id,
      v_wallet_balance
    )::public.individual_question_escrow_result;
  end if;

  insert into public.cash_wallets (user_id, balance_cents)
  values (p_student_id, 0)
  on conflict (user_id) do nothing;

  select balance_cents
    into v_wallet_balance
  from public.cash_wallets
  where user_id = p_student_id
  for update;

  -- Re-check idempotency after wallet lock to avoid double debit on concurrent calls.
  select *
    into v_question
  from public.individual_questions
  where create_idempotency_key = v_idem;

  if found then
    return (
      true,
      'already_exists',
      'individual question already created for idempotency key',
      v_question.id,
      v_question.status,
      v_question.hold_ledger_id,
      v_wallet_balance
    )::public.individual_question_escrow_result;
  end if;

  if coalesce(v_wallet_balance, 0) < p_price_cents then
    return (
      false,
      'insufficient_cash',
      'CASH_INSUFFICIENT',
      null,
      null,
      null,
      coalesce(v_wallet_balance, 0)
    )::public.individual_question_escrow_result;
  end if;

  v_status := case when v_type = 'direct' then 'assigned' else 'open' end;

  insert into public.individual_questions (
    student_id,
    question_type,
    designated_mentor_id,
    subject,
    topic,
    title,
    body,
    price_cents,
    status,
    create_idempotency_key
  )
  values (
    p_student_id,
    v_type,
    case when v_type = 'direct' then p_mentor_id else null end,
    nullif(trim(coalesce(p_subject, '')), ''),
    nullif(trim(coalesce(p_topic, '')), ''),
    trim(p_title),
    trim(p_body),
    p_price_cents,
    v_status,
    v_idem
  )
  returning * into v_question;

  insert into public.cash_ledger (
    user_id,
    delta_cents,
    reason,
    ref_type,
    ref_id,
    idempotency_key
  )
  values (
    p_student_id,
    -p_price_cents,
    'individual_question_escrow_hold',
    'individual_questions',
    v_question.id,
    'iq_hold:' || v_question.id::text
  )
  on conflict (idempotency_key) do nothing
  returning id into v_ledger_id;

  if v_ledger_id is null then
    raise exception 'INDIVIDUAL_QUESTION_HOLD_LEDGER_CONFLICT';
  end if;

  update public.cash_wallets
  set balance_cents = balance_cents - p_price_cents
  where user_id = p_student_id
    and balance_cents >= p_price_cents
  returning balance_cents into v_wallet_balance;

  get diagnostics v_wallet_rows = row_count;
  if coalesce(v_wallet_rows, 0) = 0 then
    raise exception 'CASH_INSUFFICIENT_AFTER_LOCK' using errcode = 'P0001';
  end if;

  update public.individual_questions
  set hold_ledger_id = v_ledger_id
  where id = v_question.id
  returning * into v_question;

  return (
    true,
    'created',
    'individual question created and cash held',
    v_question.id,
    v_question.status,
    v_ledger_id,
    v_wallet_balance
  )::public.individual_question_escrow_result;
end;
$function$

