CREATE OR REPLACE FUNCTION public.custom_order_student_request_revision(p_order_id uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  o public.custom_request_orders%rowtype;
  v_norm text;
  v_note text := btrim(coalesce(p_note, ''));
  v_revision_id uuid;
begin
  if v_actor is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'P0001';
  end if;

  if v_note = '' then
    raise exception 'REVISION_NOTE_REQUIRED' using errcode = 'P0001';
  end if;

  if char_length(v_note) > 8000 then
    raise exception 'REVISION_NOTE_TOO_LONG' using errcode = 'P0001';
  end if;

  select * into o
  from public.custom_request_orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'ORDER_NOT_FOUND' using errcode = 'P0001';
  end if;

  if not public._cro_transition_actor_is_student(o, v_actor) then
    raise exception 'ORDER_STUDENT_FORBIDDEN' using errcode = 'P0001';
  end if;

  if public._cro_transition_has_active_dispute(p_order_id) then
    raise exception 'ORDER_HAS_ACTIVE_DISPUTE' using errcode = 'P0001';
  end if;

  v_norm := public._cro_transition_primary_status_norm(o);
  if v_norm = '' then
    raise exception 'ORDER_STATUS_COLUMN_MISSING' using errcode = 'P0001';
  end if;

  if public._cro_transition_is_terminal(o) then
    raise exception 'ORDER_TERMINAL' using errcode = 'P0001';
  end if;

  if v_norm not in (
    'delivered', 'delivered_pending_review', 'waiting_review', 'pending_review',
    'redelivered', 'delivery_submitted', 'in_review'
  ) then
    raise exception 'ORDER_STATUS_NOT_REVISIONABLE' using errcode = 'P0001';
  end if;

  if public._cro_transition_deliverable_count(p_order_id) < 1 then
    raise exception 'ORDER_DELIVERABLE_REQUIRED' using errcode = 'P0001';
  end if;

  if public._cro_transition_revision_count(p_order_id) >= 2 then
    raise exception 'REVISION_LIMIT_EXCEEDED' using errcode = 'P0001';
  end if;

  if lower(btrim(coalesce(o.order_status, ''))) <> 'delivered' then
    raise exception 'ORDER_STATUS_NOT_DELIVERED' using errcode = 'P0001';
  end if;

  insert into public.custom_order_revisions (
    custom_request_order_id,
    order_id,
    custom_order_id,
    request_order_id,
    author_id,
    request_note,
    status
  ) values (
    p_order_id,
    p_order_id,
    p_order_id,
    p_order_id,
    v_actor,
    v_note,
    'open'
  ) returning id into v_revision_id;

  update public.custom_request_orders
  set order_status = 'revision_requested'
  where id = p_order_id
    and order_status = 'delivered';

  if not found then
    raise exception 'ORDER_STATUS_NOT_DELIVERED' using errcode = 'P0001';
  end if;

  return jsonb_build_object(
    'ok', true,
    'transition', 'student_request_revision',
    'from', v_norm,
    'to', 'revision_requested',
    'revision_id', v_revision_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_mentor_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_used numeric;
  v_limit numeric;
  v_new numeric;
begin
  -- active 로 들어오는(또는 active 로 바뀌는) 행만 검사
  if lower(coalesce(NEW.status, '')) <> 'active' then
    return NEW;
  end if;
  if TG_OP = 'UPDATE' and lower(coalesce(OLD.status, '')) = 'active' then
    -- 이미 active 였던 행의 갱신은 추가 cap 점유가 아님
    return NEW;
  end if;

  v_new := public.subscription_cap_weight(NEW.plan_tier);
  if v_new <= 0 then
    return NEW; -- 가중치를 모르는 플랜은 차단하지 않음
  end if;

  select coalesce(sum(public.subscription_cap_weight(s.plan_tier)), 0)
    into v_used
  from public.subscriptions s
  where s.mentor_id = NEW.mentor_id
    and lower(coalesce(s.status, '')) = 'active'
    and s.id <> NEW.id;

  v_limit := public.mentor_cap_limit(NEW.mentor_id);

  if (v_used + v_new) > v_limit then
    raise exception 'MENTOR_CAP_EXCEEDED: mentor % cap %/% (+%) 초과', NEW.mentor_id, v_used, v_limit, v_new
      using errcode = 'check_violation';
  end if;

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_mentor_profile_privileged_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_jwt_role  text;
  v_sensitive boolean;
BEGIN
  -- TG_OP 선분기: INSERT 에서 OLD 는 NULL 이므로 OLD 비교 전에 반드시 분기한다.
  IF tg_op = 'INSERT' THEN
    -- 기본값 대비 판정. 50 하드코딩은 컬럼 기본값 변경 시 드리프트하는 취약점이다 —
    -- 기본값을 바꾸는 마이그레이션은 이 조건을 함께 갱신해야 한다(주석 의무). 190: 28 → 50.
    v_sensitive := (new.verification_status IS DISTINCT FROM 'pending'
                    OR new.cap_limit IS DISTINCT FROM 50);
  ELSE  -- 'UPDATE'
    v_sensitive := (new.verification_status IS DISTINCT FROM old.verification_status
                    OR new.cap_limit IS DISTINCT FROM old.cap_limit);
  END IF;

  IF v_sensitive THEN
    v_jwt_role := auth.jwt() ->> 'role';
    IF v_jwt_role = 'service_role' THEN RETURN new; END IF;   -- 서버 경유
    IF v_jwt_role IS NULL THEN RETURN new; END IF;            -- SQL Editor·migration
    IF EXISTS (SELECT 1 FROM public.users u
               WHERE u.id = (SELECT auth.uid()) AND u.role = 'admin') THEN
      RETURN new;                                             -- 기존 관리자
    END IF;
    RAISE EXCEPTION 'MENTOR_PROFILE_PRIVILEGED_COLUMN_FORBIDDEN'
      USING errcode = '42501';
  END IF;
  RETURN new;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_users_role_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_jwt_role text;
begin
  -- 트리거를 WHEN 절 없이 재생성해도 안전하도록 함수 안에서도 재확인
  if new.role is distinct from old.role then
    -- 206(DB-5 B): 소셜 가입 완성 — 역할이 없는(완성 전) 행에 student/mentor 를 처음 채우는 전이는 허용.
    --   (authenticated 는 users UPDATE 권한이 없고 users_protected_columns_guard 가 클라이언트 역할의 role 변경을 거부하므로
    --    이 전이는 SECURITY DEFINER 경로 api_app_v1.complete_profile 로만 도달한다.)
    if old.role is null and old.profile_completed_at is null and new.role in ('student', 'mentor') then
      return new;
    end if;

    v_jwt_role := auth.jwt() ->> 'role';

    if v_jwt_role = 'service_role' then
      return new; -- 1) 서버(service key) 경유
    end if;

    if v_jwt_role is null then
      return new; -- 2) JWT 없는 직접 DB 세션(SQL Editor·마이그레이션)
    end if;

    if exists (
      select 1
        from public.users u
       where u.id = (select auth.uid())
         and u.role = 'admin'
    ) then
      return new; -- 3) 관리자
    end if;

    raise exception 'ROLE_CHANGE_FORBIDDEN'
      using errcode = '42501', -- insufficient_privilege
            detail  = format('users.id=%s role %L -> %L', old.id, old.role, new.role),
            hint    = 'role 변경은 service_role 또는 admin 만 가능합니다.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_users_role_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_jwt_role text;
begin
  if new.role = 'admin' then
    v_jwt_role := auth.jwt() ->> 'role';

    if v_jwt_role = 'service_role' then
      return new; -- 1) 서버(service key) 경유 — admin 프로비저닝 정상 경로
    end if;

    if v_jwt_role is null then
      return new; -- 2) JWT 없는 직접 DB 세션(SQL Editor·마이그레이션·SECURITY DEFINER)
    end if;

    if exists (
      select 1
        from public.users u
       where u.id = (select auth.uid())
         and u.role = 'admin'
    ) then
      return new; -- 3) 기존 관리자
    end if;

    raise exception 'ADMIN_INSERT_FORBIDDEN'
      using errcode = '42501', -- insufficient_privilege
            detail  = format('users.id=%s attempted role INSERT %L', new.id, new.role),
            hint    = 'admin 계정 생성은 service_role 또는 admin 만 가능합니다(가입 경로 불가).';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.expire_voucher_service_period(p_subscription_id uuid, p_expected_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s public.subscriptions%ROWTYPE; e public.subscription_billing_events%ROWTYPE;
 r public.voucher_redemptions%ROWTYPE; v_student uuid; v_mentor uuid; v_entitlement uuid;
 v_decided_at timestamptz; v_terminal uuid; v_key text;
BEGIN
 IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'VOUCHER_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_subscription_id IS NULL OR p_expected_event_id IS NULL THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_EXPIRY_INPUT_INVALID'); END IF;
 SELECT student_id,mentor_id INTO v_student,v_mentor FROM public.subscriptions WHERE id=p_subscription_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','SUBSCRIPTION_NOT_FOUND'); END IF;
 PERFORM pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
 SELECT vr.entitlement_id INTO v_entitlement FROM public.subscription_billing_events be JOIN public.voucher_redemptions vr ON vr.id=be.voucher_redemption_id WHERE be.id=p_expected_event_id AND be.subscription_id=p_subscription_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_EXPIRY_STATE_CHANGED'); END IF;
 PERFORM 1 FROM public.voucher_entitlements WHERE id=v_entitlement FOR UPDATE;
 SELECT * INTO s FROM public.subscriptions WHERE id=p_subscription_id FOR UPDATE;
 IF s.student_id IS DISTINCT FROM v_student OR s.mentor_id IS DISTINCT FROM v_mentor THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_EXPIRY_STATE_CHANGED'); END IF;
 -- Same mentor-cap serialization as checkout/redeem; release seats atomically.
 PERFORM 1 FROM public.mentor_profiles WHERE user_id=v_mentor FOR UPDATE;
 SELECT * INTO e FROM public.subscription_billing_events WHERE id=p_expected_event_id FOR UPDATE;
 SELECT * INTO r FROM public.voucher_redemptions WHERE id=e.voucher_redemption_id FOR UPDATE;
 v_decided_at := clock_timestamp();
 v_key:='voucher_expired:'||p_expected_event_id::text;
 SELECT id INTO v_terminal FROM public.subscription_billing_events WHERE idempotency_key=v_key AND subscription_id=p_subscription_id AND event_type='expired' AND status='succeeded';
 IF FOUND THEN RETURN jsonb_build_object('ok',true,'code','already_succeeded','billing_event_id',v_terminal); END IF;
 IF s.funding_source IS DISTINCT FROM 'voucher' OR s.current_service_period_event_id IS DISTINCT FROM e.id
  OR s.status NOT IN ('active','cancel_scheduled','past_due') OR e.funding_source IS DISTINCT FROM 'voucher'
  OR e.status<>'succeeded' OR e.subscription_id<>s.id OR e.student_id<>s.student_id OR e.mentor_id<>s.mentor_id
  OR r.id IS NULL OR r.entitlement_id<>v_entitlement OR r.service_end IS DISTINCT FROM e.period_end
  OR e.period_end IS NULL OR v_decided_at<e.period_end THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_EXPIRY_STATE_CHANGED'); END IF;
 INSERT INTO public.subscription_billing_events(subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,plan_tier,plan_id,idempotency_key,processed_at)
 VALUES(s.id,s.student_id,s.mentor_id,'expired','succeeded',e.period_start,e.period_end,v_decided_at,e.plan_tier,e.plan_id,v_key,v_decided_at) RETURNING id INTO v_terminal;
 -- Existing expired-status trigger enqueues notification within this transaction.
 UPDATE public.subscriptions SET status='expired',expired_at=v_decided_at,next_billing_at=NULL,current_service_period_event_id=NULL,last_billing_event_id=v_terminal,updated_at=v_decided_at WHERE id=s.id;
 RETURN jsonb_build_object('ok',true,'code','succeeded','billing_event_id',v_terminal);
END $function$

CREATE OR REPLACE FUNCTION public.get_mobile_app_version_policy(p_platform text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.mobile_app_version_policies;
begin
  if p_platform is null or lower(btrim(p_platform)) not in ('android','ios') then
    raise exception 'INVALID_PLATFORM' using errcode = '22023';
  end if;
  select * into v_row from public.mobile_app_version_policies
  where platform = lower(btrim(p_platform));
  if not found then
    return jsonb_build_object(
      'platform', lower(btrim(p_platform)),
      'min_supported_build', 1,
      'latest_build', 1,
      'minimum_version_name', null,
      'store_url', null,
      'message', null);
  end if;
  return jsonb_build_object(
    'platform', v_row.platform,
    'min_supported_build', v_row.min_supported_build,
    'latest_build', v_row.latest_build,
    'minimum_version_name', v_row.minimum_version_name,
    'store_url', v_row.store_url,
    'message', v_row.message);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_weekly_question_usage(p_student_id uuid, p_mentor_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_usage jsonb; v_event uuid; v_redemption uuid; v_end timestamptz; v_now timestamptz; v_code text := 'allowed'; v_anchor timestamptz;
  v_week_start timestamptz;
  v_week_end timestamptz;
  v_elapsed_seconds numeric;
  v_period_index integer;
  v_used integer := 0;
  v_plan_tier text;
  v_limit integer := 0;
begin
  -- [S2 M15] NULL-safe pair-party 가드 (계약 §7 F1 — 오너 확정 형태 고정).
  IF (auth.jwt() ->> 'role') IS DISTINCT FROM 'service_role'
     AND auth.uid() IS DISTINCT FROM p_student_id
     AND auth.uid() IS DISTINCT FROM p_mentor_id
  THEN
    RAISE EXCEPTION 'NOT_PAIR_PARTY'
      USING ERRCODE = '42501';
  END IF;

  if p_student_id is null or p_mentor_id is null then
    raise exception 'p_student_id and p_mentor_id are required';
  end if;

  v_now:=clock_timestamp();
  select e.id,e.voucher_redemption_id into v_event,v_redemption
    from public.subscriptions s join public.subscription_billing_events e on e.id=s.current_service_period_event_id
    where s.student_id=p_student_id and s.mentor_id=p_mentor_id order by s.created_at desc limit 1;
  if v_event is not null then
    v_code:=core_private.service_period_eligibility(v_event,coalesce(auth.uid(),p_student_id),'quota',v_now);
    if v_redemption is not null then
      v_usage:=core_private.qna_voucher_weekly_usage(v_event,v_now);
      return (v_usage || jsonb_build_object('plan_tier','standard','remaining',case when v_code='allowed' then (v_usage->>'remaining')::int else 0 end,'can_ask',v_code='allowed' and (v_usage->>'can_ask')::boolean,'code',nullif(v_code,'allowed')))::json;
    end if;
  end if;
  if v_event is null then
    if exists(select 1 from public.subscriptions where student_id=p_student_id and mentor_id=p_mentor_id and status='active') then
      raise exception 'SERVICE_PERIOD_UNBOUND';
    end if;
    if exists(select 1 from public.voucher_redemptions where student_id=p_student_id and mentor_id=p_mentor_id) then
      -- A cleared current pointer after expiry must not look like a free-quota
      -- candidate to existing clients (limit=0 / plan_tier=null means free).
      select id into v_event from public.subscription_billing_events
        where student_id=p_student_id and mentor_id=p_mentor_id and voucher_redemption_id is not null
          and event_type in ('initial','renewal') order by period_start desc,id limit 1;
      if v_event is not null then v_usage:=core_private.qna_voucher_weekly_usage(v_event,v_now); end if;
      return (coalesce(v_usage,'{}'::jsonb)||jsonb_build_object('used',coalesce((v_usage->>'used')::integer,0),
        'limit',9,'plan_tier','standard','remaining',0,'can_ask',false,'code','SERVICE_PERIOD_EXPIRED'))::json;
    end if;
  end if;
  -- Cash retains its established weekly anchor/count. The common eligibility
  -- decision gates both this display and the locked creation RPC.
  v_usage:=core_private.qna_cash_weekly_usage(p_student_id,p_mentor_id,v_now)::jsonb;
  return (v_usage||jsonb_build_object(
    'remaining',case when v_code='allowed' then (v_usage->>'remaining')::integer else 0 end,
    'can_ask',v_code='allowed' and (v_usage->>'can_ask')::boolean,'code',nullif(v_code,'allowed')))::json;
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  m jsonb;
  r text;
  subj text[];
  subj_str text;
  bdate date;
  v_name text;
begin
  m := coalesce(NEW.raw_user_meta_data, '{}'::jsonb);

  -- ── 소셜(OAuth) 가입: app_role 키 없음 → 역할 미정 · 완성 전. 프로필 행(mentor_profiles)은 만들지 않는다(정정 B) ──
  if not (m ? 'app_role') then
    v_name := coalesce(
      nullif(trim(m->>'full_name'), ''),
      nullif(trim(m->>'name'), ''),
      nullif(trim(m->>'preferred_username'), ''),
      nullif(trim(m->>'nickname'), ''),
      nullif(trim(m->>'user_name'), '')
    );
    perform core_private.user_signup_provision_impl(
      NEW.id, null, nullif(NEW.email, ''), v_name, v_name,
      null, null, null,
      false, false, false,
      null, null, null, null, null,
      null,
      null);   -- 소셜: 가입 시점 동의 없음 → 원장 기록 없음(complete_profile 이 남긴다)
    return NEW;
  end if;

  -- ── 이메일 가입(app_role 있음): 122 정규화 그대로 ──
  r := lower(trim(m->>'app_role'));
  if r is null or r = '' then
    r := 'student';
  end if;
  -- ★ XV-01: 'admin' 제거 — 가입 메타로는 student/mentor 만 가능. 그 외 전부 student.
  if r not in ('student', 'mentor') then
    r := 'student';
  end if;

  subj_str := nullif(trim(m->>'teaching_subjects_csv'), '');
  if subj_str is not null then
    subj := array(
      select trim(both ' ' from x)
      from unnest(string_to_array(subj_str, ',')) as x
      where length(trim(both ' ' from x)) > 0
    );
  else
    subj := '{}';
  end if;

  begin
    bdate := (m->>'birth_date')::date;
  exception when others then
    bdate := null;
  end;

  perform core_private.user_signup_provision_impl(
    NEW.id, r, coalesce(NEW.email, ''),
    m->>'full_name', m->>'nickname',
    m->>'grade_level', m->>'student_status', bdate,
    (m->>'terms_agreed') = 'true', (m->>'privacy_agreed') = 'true', (m->>'marketing_agreed') = 'true',
    m->>'university_name', m->>'department_name', coalesce(subj, '{}'), m->>'high_school_name', m->>'intro_line',
    now(),
    m);   -- 이메일: 가입 메타 그대로 → 동의 원장(187 과 같은 행 · zz 트리거는 멱등 no-op)

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.iq_append_message(p_question_id uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_q public.individual_questions%rowtype;
  v_mentor uuid;
  v_is_mentor boolean;
  v_status text; v_susp timestamptz; v_norm text;
  v_message_id uuid;
  v_transitioned boolean := false;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  if coalesce(btrim(p_body), '') = '' then raise exception 'BODY_REQUIRED' using errcode = '22023'; end if;

  select * into v_q from public.individual_questions where id = p_question_id for update;
  if not found then raise exception 'QUESTION_NOT_FOUND' using errcode = 'P0001'; end if;

  v_mentor := coalesce(v_q.claimed_mentor_id, v_q.designated_mentor_id);
  if v_uid = v_q.student_id then v_is_mentor := false;
  elsif v_mentor is not null and v_uid = v_mentor then v_is_mentor := true;
  else raise exception 'NOT_QUESTION_PARTY' using errcode = '42501';
  end if;

  -- 계정 상태 4종 + 삭제 진행 + 상호 차단 (qna_append_message 와 동일 게이트)
  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = v_uid;
  if not found then raise exception 'ACCOUNT_NOT_ACTIVE'; end if;
  v_norm := lower(btrim(coalesce(v_status,'')));
  if v_norm = 'banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if v_norm = 'suspended' and (v_susp is null or v_susp > now()) then raise exception 'ACCOUNT_SUSPENDED'; end if;
  if v_norm not in ('active','suspended') then raise exception 'ACCOUNT_NOT_ACTIVE'; end if;
  if public.account_deletion_write_blocked(v_uid) then raise exception 'ACCOUNT_DELETION_IN_PROGRESS'; end if;
  if v_mentor is not null and public.qna_users_blocked(v_q.student_id, v_mentor) then raise exception 'BLOCKED'; end if;

  -- 상태 게이트: 종결(released/refunded/expired/canceled)은 잠금.
  -- escrowed(공개·미선점)는 멘토 미확정이라 학생만 추가 설명 가능.
  if v_q.status in ('released','refunded','expired','canceled') then
    raise exception 'QUESTION_LOCKED' using errcode = 'P0001';
  end if;
  if v_q.status = 'escrowed' and v_is_mentor then
    raise exception 'NOT_ANSWERABLE_STATUS:%', v_q.status using errcode = 'P0001';
  end if;
  if v_is_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then
    raise exception 'MENTOR_NOT_APPROVED';
  end if;

  insert into public.individual_question_messages (question_id, author_id, body)
  values (p_question_id, v_uid, btrim(p_body))
  returning id into v_message_id;

  -- 멘토 첫 답변 = answered 전이 (answer_individual_question 의 의미 보존)
  if v_is_mentor and v_q.status in ('claimed','assigned') then
    update public.individual_questions
      set status = 'answered', answered_at = coalesce(answered_at, now())
      where id = p_question_id;
    v_transitioned := true;
  end if;

  return jsonb_build_object('ok', true, 'message_id', v_message_id, 'answered_transition', v_transitioned);
end;
$function$

CREATE OR REPLACE FUNCTION public.iq_notify_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_recipient uuid; v_type text; v_title text; v_body text; v_mentor uuid;
begin
  v_mentor := coalesce(NEW.claimed_mentor_id, NEW.designated_mentor_id);
  if NEW.status = 'answered' then
    v_recipient := NEW.student_id; v_type := 'individual_question_answered';
    v_title := '개별 질문 답변 도착'; v_body := '요청한 개별 질문에 답변이 등록됐어요.';
  elsif NEW.status = 'released' then
    v_recipient := v_mentor; v_type := 'individual_question_released';
    v_title := '개별 질문 정산 확정'; v_body := '학생이 답변을 확정해 정산이 확정됐어요.';
  elsif NEW.status = 'claimed' then
    v_recipient := NEW.student_id; v_type := 'individual_question_claimed';
    v_title := '개별 질문 수락됨'; v_body := '멘토가 개별 질문을 수락했어요.';
  elsif NEW.status = 'refunded' then
    v_recipient := NEW.student_id; v_type := 'individual_question_expired_refunded';
    v_title := '개별 질문 환불'; v_body := '개별 질문이 만료되어 캐시가 환불됐어요.';
  else
    return NEW;
  end if;
  if v_recipient is not null then
    perform public.record_domain_notification(
      v_recipient, v_type || ':' || NEW.id::text, v_type || ':' || NEW.id::text, v_type,
      v_title, v_body, null,
      jsonb_build_object('question_id', NEW.id, 'status', NEW.status),
      jsonb_build_object('question_id', NEW.id));
  end if;
  return NEW;
end $function$

CREATE OR REPLACE FUNCTION public.iqm_notify_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_student uuid; v_mentor uuid; v_recipient uuid;
begin
  select student_id, coalesce(claimed_mentor_id, designated_mentor_id)
    into v_student, v_mentor from public.individual_questions where id = NEW.question_id;
  if NEW.author_id = v_student then v_recipient := v_mentor;
  elsif NEW.author_id = v_mentor then v_recipient := v_student;
  else v_recipient := null; end if;
  if v_recipient is not null then
    perform public.record_domain_notification(
      v_recipient, 'individual_question_message:' || NEW.id::text,
      'individual_question_message:' || NEW.id::text, 'individual_question_message',
      '개별 질문 새 메시지', '개별 질문에 새 메시지가 도착했어요.', null,
      jsonb_build_object('question_id', NEW.question_id, 'message_id', NEW.id),
      jsonb_build_object('question_id', NEW.question_id, 'message_id', NEW.id));
  end if;
  return NEW;
end $function$

CREATE OR REPLACE FUNCTION public.issue_voucher_entitlement(p_campaign_id uuid, p_external_entitlement_hmac text, p_code_hmac text, p_hmac_key_version text, p_ciphertext text, p_nonce text, p_auth_tag text, p_encryption_key_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_e public.voucher_entitlements%ROWTYPE; v_new boolean := false;
BEGIN
 IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'VOUCHER_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_external_entitlement_hmac IS NULL OR p_external_entitlement_hmac !~ '^[0-9a-f]{64}$' OR p_code_hmac IS NULL OR p_code_hmac !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'VOUCHER_INPUT_INVALID'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('voucher_issue:'||p_external_entitlement_hmac,0));
 SELECT * INTO v_e FROM public.voucher_entitlements WHERE external_entitlement_hmac=p_external_entitlement_hmac FOR UPDATE;
 IF FOUND THEN
  IF v_e.campaign_id IS DISTINCT FROM p_campaign_id THEN RAISE EXCEPTION 'VOUCHER_ENTITLEMENT_CONFLICT'; END IF;
 ELSE
  PERFORM 1 FROM public.voucher_campaigns WHERE id=p_campaign_id AND status IN ('active','disabled') FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'VOUCHER_CAMPAIGN_UNAVAILABLE'; END IF;
  INSERT INTO public.voucher_entitlements(campaign_id,external_entitlement_hmac,code_hmac,hmac_key_version)
   VALUES(p_campaign_id,p_external_entitlement_hmac,p_code_hmac,p_hmac_key_version) RETURNING * INTO v_e;
  INSERT INTO public.voucher_delivery_envelopes(entitlement_id,ciphertext,nonce,auth_tag,encryption_key_version)
   VALUES(v_e.id,p_ciphertext,p_nonce,p_auth_tag,p_encryption_key_version);
  v_new:=true;
 END IF;
 RETURN jsonb_build_object('ok',true,'entitlement_id',v_e.id,'idempotent',NOT v_new,'envelope',(SELECT to_jsonb(d)-'entitlement_id'-'created_at' FROM public.voucher_delivery_envelopes d WHERE entitlement_id=v_e.id));
END $function$

CREATE OR REPLACE FUNCTION public.keep_subscription_refunded_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.status='canceled' and exists(select 1 from public.subscription_billing_events e join public.refunds r on core_private.refund_matches_service_period(r,e)
 where e.id=coalesce(new.current_service_period_event_id,new.last_billing_event_id) and e.subscription_id=new.id and r.status='succeeded') then
 new.status:='refunded'; new.cancel_at_period_end:=false; new.next_billing_at:=null;
 new.canceled_at:=coalesce(new.canceled_at,now()); new.expired_at:=coalesce(new.expired_at,now()); end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.mark_all_notifications_read()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := (select auth.uid()); v_count int;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  update public.notifications
  set is_read = true, read_at = coalesce(read_at, now()), updated_at = now()
  where is_read is distinct from true
    and (user_id = v_uid or recipient_id = v_uid or student_id = v_uid or mentor_id = v_uid or target_user_id = v_uid or owner_id = v_uid or recipient_user_id = v_uid);
  get diagnostics v_count = row_count;
  return coalesce(v_count, 0);
end; $function$

CREATE OR REPLACE FUNCTION public.mark_notification_read(p_notification_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_row public.notifications%rowtype;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;
  select * into v_row from public.notifications where id = p_notification_id for update;
  if not found then
    raise exception 'NOTIFICATION_NOT_FOUND' using errcode = 'P0001';
  end if;
  if not coalesce(
      (v_row.recipient_user_id = v_uid or v_row.user_id = v_uid or v_row.recipient_id = v_uid
       or v_row.student_id = v_uid or v_row.mentor_id = v_uid
       or v_row.target_user_id = v_uid or v_row.owner_id = v_uid), false) then
    raise exception 'NOT_RECIPIENT' using errcode = '42501';
  end if;
  if coalesce(v_row.is_read, false) then
    return jsonb_build_object('ok', true, 'contract_version', 1, 'idempotent_hit', true);
  end if;
  update public.notifications
     set is_read = true, read_at = coalesce(read_at, now()), updated_at = now()
   where id = p_notification_id;
  return jsonb_build_object('ok', true, 'contract_version', 1, 'idempotent_hit', false);
end
$function$

CREATE OR REPLACE FUNCTION public.mentor_acad_change_guard_self_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce((select public.is_admin()), false) then
    return new;
  end if;

  if new.mentor_id = (select auth.uid()) then
    new.status := 'pending';
    new.approved_university_name := null;
    new.reviewed_by := null;
    new.reviewed_at := null;
    new.reject_reason := null;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.mentor_school_verification_storage_path(p_ref text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_raw text := btrim(coalesce(p_ref, ''));
  v_marker constant text := '/student-id-images/';
  v_prefix constant text := 'student-id-images/';
  v_idx integer;
  v_path text;
begin
  if v_raw = '' then
    return null;
  end if;

  if v_raw like 'http://%' or v_raw like 'https://%' then
    v_idx := position(v_marker in v_raw);
    if v_idx = 0 then
      return null;
    end if;
    v_path := substr(v_raw, v_idx + length(v_marker));
    v_path := split_part(v_path, '?', 1);
    v_path := split_part(v_path, '#', 1);
    return nullif(btrim(v_path), '');
  end if;

  if v_raw like (v_prefix || '%') then
    return nullif(regexp_replace(substr(v_raw, length(v_prefix) + 1), '^/+', ''), '');
  end if;

  if position('/' in v_raw) > 0 then
    return nullif(regexp_replace(v_raw, '^/+', ''), '');
  end if;

  return null;
end;
$function$

