$function$

CREATE OR REPLACE FUNCTION public.mp_notify_activity_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sub record;
  v_key text;
  v_date_key text;
  v_body_date text;
begin
  if NEW.activity_status = 'terminating' then
    v_date_key := to_char(coalesce(NEW.termination_effective_at, now()) at time zone 'UTC', 'YYYY-MM-DD');
    v_body_date := public.notification_date_label(coalesce(NEW.termination_effective_at, now()));
    for v_sub in
      select s.id, s.student_id from public.subscriptions s
      where s.mentor_id = NEW.user_id and s.status in ('active', 'past_due')
    loop
      v_key := 'mentor_termination_notice:' || v_sub.id::text || ':' || v_date_key;
      perform public.record_domain_notification(
        v_sub.student_id, v_key, v_key, 'mentor_termination_notice',
        '멘토 활동 종료 예정',
        '구독 중인 멘토가 활동을 종료합니다. 2주 후(' || v_body_date
          || ') 구독이 정리되며 남은 기간은 환불됩니다. 그때까지는 정상 이용할 수 있어요.',
        '/subscriptions',
        jsonb_build_object('mentor_id', NEW.user_id, 'effective_at', NEW.termination_effective_at,
          'subscription_id', v_sub.id),
        jsonb_build_object('mentor_id', NEW.user_id, 'subscription_id', v_sub.id));
    end loop;
  elsif NEW.activity_status = 'paused' then
    v_date_key := to_char(coalesce(NEW.pause_until, now()) at time zone 'UTC', 'YYYY-MM-DD');
    v_body_date := public.notification_date_label(coalesce(NEW.pause_until, now()));
    for v_sub in
      select s.id, s.student_id from public.subscriptions s
      where s.mentor_id = NEW.user_id and s.status in ('active', 'past_due')
    loop
      v_key := 'mentor_pause_notice:' || v_sub.id::text || ':' || v_date_key;
      perform public.record_domain_notification(
        v_sub.student_id, v_key, v_key, 'mentor_pause_notice',
        '멘토 일시 휴식 안내',
        '구독 중인 멘토가 ' || v_body_date || '까지 일시 휴식합니다. 쉰 기간만큼 구독 기간이 자동 연장됩니다.',
        '/subscriptions',
        jsonb_build_object('mentor_id', NEW.user_id, 'pause_until', NEW.pause_until,
          'subscription_id', v_sub.id),
        jsonb_build_object('mentor_id', NEW.user_id, 'subscription_id', v_sub.id));
    end loop;
  end if;
  return NEW;
end $function$

CREATE OR REPLACE FUNCTION public.notification_create_deliveries(p_outbox_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_recipient uuid; v_etype text; v_allowed boolean; v_created int := 0;
begin
  select recipient_user_id, event_type into v_recipient, v_etype from public.notification_outbox where id=p_outbox_id;
  if v_recipient is null then return jsonb_build_object('ok',false,'code','OUTBOX_NOT_FOUND'); end if;
  v_allowed := public.notification_delivery_allowed(v_recipient, v_etype);
  if not v_allowed then
    return jsonb_build_object('ok',true,'created',0,'suppressed',true);
  end if;
  insert into public.notification_deliveries (outbox_id, device_token_id)
    select p_outbox_id, dt.id from public.device_tokens dt
    where dt.user_id = v_recipient and dt.revoked_at is null
  on conflict (outbox_id, device_token_id) do nothing;
  get diagnostics v_created = row_count;
  return jsonb_build_object('ok',true,'created',v_created,'suppressed',false);
end $function$

CREATE OR REPLACE FUNCTION public.notification_delivery_mark_failed(p_id uuid, p_error text, p_invalid_token boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_token_id uuid;
begin
  update public.notification_deliveries
    set attempt_count = attempt_count + 1, last_error = left(coalesce(p_error,''),1000),
        status = case when p_invalid_token then 'dead' else 'failed' end, updated_at=now()
    where id=p_id returning device_token_id into v_token_id;
  if v_token_id is null then return jsonb_build_object('ok',false,'code','NOT_FOUND'); end if;
  if p_invalid_token then perform public.revoke_device_token(v_token_id); end if;
  return jsonb_build_object('ok',true,'invalid_token',p_invalid_token);
end $function$

CREATE OR REPLACE FUNCTION public.notification_outbox_mark_failed(p_id uuid, p_error text, p_backoff_seconds integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_attempt int; v_max int; v_dead boolean;
begin
  update public.notification_outbox
    set attempt_count = attempt_count + 1, last_error = left(coalesce(p_error,''),1000),
        lease_owner=null, leased_until=null,
        next_attempt_at = now() + make_interval(secs => greatest(1,p_backoff_seconds)), updated_at=now()
    where id=p_id
    returning attempt_count, max_attempts into v_attempt, v_max;
  if v_attempt is null then return jsonb_build_object('ok',false,'code','NOT_FOUND'); end if;
  v_dead := v_attempt >= v_max;
  update public.notification_outbox set status = case when v_dead then 'dead' else 'failed' end where id=p_id;
  return jsonb_build_object('ok',true,'attempt',v_attempt,'dead',v_dead);
end $function$

CREATE OR REPLACE FUNCTION public.notification_outbox_reclaim_expired()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n int;
begin
  update public.notification_outbox set status='pending', lease_owner=null, leased_until=null, updated_at=now()
    where status='leased' and leased_until is not null and leased_until < now();
  get diagnostics v_n = row_count;
  return v_n;
end $function$

CREATE OR REPLACE FUNCTION public.notifications_read_state_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.is_read is null then new.is_read := coalesce(new.read, false); end if;
    new.read := new.is_read;
    if new.is_read and new.read_at is null then new.read_at := now(); end if;
    return new;
  end if;
  -- UPDATE: 어느 쪽이 갱신되든 정본(is_read)으로 수렴 후 미러
  if new.is_read is distinct from old.is_read then
    new.read := new.is_read;
  elsif coalesce(new.read, false) is distinct from coalesce(old.read, false) then
    new.is_read := coalesce(new.read, false);
    new.read := new.is_read;
  else
    new.read := new.is_read;
  end if;
  if new.is_read then
    if new.read_at is null then new.read_at := now(); end if;
  else
    new.read_at := null;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.pay_due_payouts_for_run(p_run_date date, p_idempotency_key text DEFAULT NULL::text, p_dry_run boolean DEFAULT true)
 RETURNS TABLE(run_id uuid, paid_count integer, skipped_no_account integer, total_mentor_cents bigint, total_withholding_cents bigint, total_net_cents bigint, dry_run boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_idem text := coalesce(p_idempotency_key, 'payout:' || to_char(p_run_date, 'YYYY-MM'));
  v_cutoff timestamptz := (date_trunc('month', p_run_date::timestamp) at time zone 'Asia/Seoul') - interval '1 second';
  v_run public.payout_runs%rowtype;
  v_run_id uuid;
  v_subscription_candidates uuid[];
  rec record; lock_pair record; fresh public.subscription_settlement_items%rowtype; ev public.subscription_billing_events%rowtype;
  v_ledger_id uuid; v_item_id uuid; v_has_account boolean; v_effective_end timestamptz;
  v_paid int := 0; v_skipped int := 0;
  v_total bigint := 0; v_total_wh bigint := 0; v_total_net bigint := 0;
  v_withholding bigint; v_net bigint; v_wh_ledger_id uuid;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if;
  if p_run_date is null or p_dry_run is null then raise exception 'PAYOUT_ARGUMENT_REQUIRED'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('subscription_payout_runs'),0);
  select coalesce(array_agg(d.source_id),'{}'::uuid[]) into v_subscription_candidates from public.due_payouts d where d.source_type='subscription' and d.completion_ts<=v_cutoff;
  -- Pre-acquire every candidate pair before retaining a profile/resource lock across loop iterations.
  for lock_pair in select distinct e.student_id,e.mentor_id from public.subscription_settlement_items i
   join public.subscription_billing_events e on e.id=i.billing_event_id where i.id=any(v_subscription_candidates)
   order by e.student_id,e.mentor_id
  loop perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(lock_pair.student_id::text),pg_catalog.hashtext(lock_pair.mentor_id::text)); end loop;
  if not p_dry_run then
    select * into v_run from public.payout_runs where idempotency_key = v_idem;
    if found then
      v_run_id := v_run.id;
      if v_run.status = 'completed' then
        return query select v_run.id, v_run.mentor_count, 0, v_run.total_mentor_cents,
          coalesce((select sum(withholding_cents) from public.payout_run_items where payout_run_id=v_run.id),0)::bigint,
          coalesce((select sum(net_paid_cents) from public.payout_run_items where payout_run_id=v_run.id),0)::bigint, false;
        return;
      end if;
    else
      insert into public.payout_runs (run_date, cutoff_end, status, idempotency_key)
      values (p_run_date, v_cutoff, 'executing', v_idem) returning id into v_run_id;
    end if;
  end if;

  for rec in
    select d.* from public.due_payouts d
    where d.completion_ts <= v_cutoff
      and (d.source_type<>'subscription' or d.source_id=any(v_subscription_candidates))
      and not exists (select 1 from public.payout_run_items i where i.source_type=d.source_type and i.source_id=d.source_id)
    order by d.mentor_id, d.source_type, d.completion_ts
  loop
    if rec.source_type='subscription' then
      select * into fresh from public.subscription_settlement_items where id=rec.source_id;
      if not found then continue; end if;
      perform core_private.lock_service_period_finance(fresh.billing_event_id);
      select * into ev from public.subscription_billing_events where id=fresh.billing_event_id;
      select * into fresh from public.subscription_settlement_items where id=rec.source_id for update;
      v_effective_end:=core_private.service_period_effective_end(ev.id);
      if v_effective_end is null or fresh.status not in ('pending','accruing') or fresh.period_end is null or fresh.period_end>clock_timestamp() or fresh.period_end>v_cutoff
       or core_private.service_period_financial_state(ev.id)<>'clear'
       or exists(select 1 from public.mentor_profiles where user_id=ev.mentor_id and coalesce(activity_status,'active')<>'active')
       or exists(select 1 from public.service_period_financial_holds where billing_event_id=ev.id)
       or exists(select 1 from public.payout_run_items where source_type='subscription' and source_id=fresh.id)
       or exists(select 1 from public.cash_ledger where idempotency_key='sub_payout:'||fresh.id::text)
       or fresh.mentor_id<>ev.mentor_id or fresh.student_id is distinct from ev.student_id or fresh.subscription_id<>ev.subscription_id
       or fresh.gross_cents<>ev.amount_cents or fresh.payment_id is distinct from ev.payment_id
       or fresh.period_start is distinct from ev.period_start or fresh.period_end is distinct from v_effective_end then continue; end if;
      if ev.voucher_redemption_id is not null then
        if not exists(select 1 from public.voucher_redemptions r where r.id=ev.voucher_redemption_id and r.gross_cents=fresh.gross_cents and r.platform_fee_cents=fresh.platform_fee_cents and r.mentor_amount_cents=fresh.mentor_amount_cents) then continue; end if;
      elsif fresh.platform_fee_cents<>floor(ev.amount_cents::numeric*0.15)::bigint or fresh.mentor_amount_cents<>ev.amount_cents-floor(ev.amount_cents::numeric*0.15)::bigint then continue; end if;
      rec.mentor_id:=fresh.mentor_id; rec.mentor_amount_cents:=fresh.mentor_amount_cents; rec.gross_cents:=fresh.gross_cents;
      rec.platform_fee_cents:=fresh.platform_fee_cents; rec.fee_rate:=fresh.fee_rate;
    end if;
    select coalesce(nullif(trim(mp.payout_account_number), ''), '') <> '' into v_has_account
      from public.mentor_profiles mp where mp.user_id = rec.mentor_id;
    if coalesce(v_has_account, false) = false then
      v_skipped := v_skipped + 1; continue;
    end if;

    v_withholding := public.calc_withholding_cents(rec.mentor_amount_cents);
    v_net := rec.mentor_amount_cents - v_withholding;

    if p_dry_run then
      v_paid := v_paid + 1; v_total := v_total + rec.mentor_amount_cents;
      v_total_wh := v_total_wh + v_withholding; v_total_net := v_total_net + v_net;
      continue;
    end if;

    v_ledger_id := null;
    v_item_id := null;
    if rec.source_type = 'custom_request' then
      perform public.record_custom_order_escrow_payout(rec.source_id);
      select id into v_ledger_id from public.cash_ledger
        where idempotency_key = 'cr_payout_' || rec.source_id::text and reason='custom_order_escrow_payout' limit 1;
    elsif rec.source_type = 'individual_question' then
      perform public.release_individual_question_payout(rec.source_id);
      select id into v_ledger_id from public.cash_ledger
        where idempotency_key = 'iq_payout:' || rec.source_id::text and reason='individual_question_payout' limit 1;
    elsif rec.source_type = 'subscription' then
      insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
      values (rec.mentor_id, rec.mentor_amount_cents, 'subscription_settlement_payout',
              'subscription_settlement_items', rec.source_id, 'sub_payout:' || rec.source_id::text)
      on conflict (idempotency_key) do nothing returning id into v_ledger_id;
      if v_ledger_id is not null then
        insert into public.cash_wallets (user_id, balance_cents) values (rec.mentor_id, 0) on conflict (user_id) do nothing;
        update public.cash_wallets w set balance_cents = w.balance_cents + rec.mentor_amount_cents where w.user_id = rec.mentor_id;
      else
        select id into v_ledger_id from public.cash_ledger where idempotency_key='sub_payout:' || rec.source_id::text limit 1;
      end if;
      update public.subscription_settlement_items set status='paid', paid_at=coalesce(paid_at, now()), updated_at=now()
        where id = rec.source_id and status <> 'paid';
    else
      continue;
    end if;

    if v_withholding > 0 then
      v_wh_ledger_id := null;
      insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
      values (rec.mentor_id, -v_withholding, 'payout_withholding_3_3pct', rec.source_type, rec.source_id,
              'wh:' || rec.source_type || ':' || rec.source_id::text)
      on conflict (idempotency_key) do nothing returning id into v_wh_ledger_id;
      if v_wh_ledger_id is not null then
        update public.cash_wallets w set balance_cents = w.balance_cents - v_withholding where w.user_id = rec.mentor_id;
      end if;
    end if;

    insert into public.payout_run_items (
      payout_run_id, mentor_id, source_type, source_id,
      gross_cents, platform_fee_cents, mentor_amount_cents, fee_rate, ledger_id,
      withholding_cents, net_paid_cents
    ) values (
      v_run_id, rec.mentor_id, rec.source_type, rec.source_id,
      rec.gross_cents, rec.platform_fee_cents, rec.mentor_amount_cents, rec.fee_rate, v_ledger_id,
      v_withholding, v_net
    )
    on conflict (source_type, source_id) do nothing
    returning id into v_item_id;

    if v_item_id is not null then
      v_paid := v_paid + 1;
      v_total := v_total + rec.mentor_amount_cents;
      v_total_wh := v_total_wh + v_withholding;
      v_total_net := v_total_net + v_net;
    end if;
  end loop;

  if not p_dry_run then
    update public.payout_runs
    set status='completed',
        mentor_count=(select count(distinct mentor_id) from public.payout_run_items where payout_run_id=v_run_id),
        total_mentor_cents=(select coalesce(sum(mentor_amount_cents),0) from public.payout_run_items where payout_run_id=v_run_id),
        executed_at=now(), updated_at=now()
    where id=v_run_id;
  end if;

  return query select v_run_id, v_paid, v_skipped, v_total, v_total_wh, v_total_net, p_dry_run;
end;
$function$

CREATE OR REPLACE FUNCTION public.preview_voucher(p_student_id uuid, p_mentor_id uuid, p_code_hmac text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_c public.voucher_campaigns%ROWTYPE;
BEGIN
 IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'VOUCHER_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT c.* INTO v_c FROM public.voucher_entitlements e JOIN public.voucher_campaigns c ON c.id=e.campaign_id WHERE e.code_hmac=p_code_hmac AND e.status='issued' AND c.status='active';
 IF NOT FOUND OR now()<v_c.redeem_start OR now()>=v_c.redeem_end THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_UNAVAILABLE'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=p_student_id AND role='student' AND status='active') OR NOT public.individual_question_user_is_approved_mentor(p_mentor_id) THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_PARTY_UNAVAILABLE'); END IF;
 RETURN jsonb_build_object('ok',true,'gross_cents',v_c.gross_cents,'plan_tier',v_c.plan_tier,'weekly_question_limit',v_c.weekly_question_limit,'service_end',v_c.service_end);
END $function$

CREATE OR REPLACE FUNCTION public.qa_direct_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_room uuid; v_status text;
begin
  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;
  select mentor_student_room_id, status into v_room, v_status from public.question_threads where id = NEW.thread_id;
  if v_status in ('confirmed','closed','archived') then raise exception 'DIRECT_ATT_THREAD_LOCKED'; end if;
  if NEW.storage_path is null or NEW.storage_path not like (v_room::text||'/'||NEW.thread_id::text||'/%') then raise exception 'DIRECT_ATT_PATH_FORGERY'; end if;
  if not exists (select 1 from storage.objects o where o.bucket_id='question-room-attachments' and o.name=NEW.storage_path and o.owner_id=auth.uid()::text) then raise exception 'DIRECT_ATT_OBJECT_NOT_OWNED'; end if;
  return NEW;
end; $function$

CREATE OR REPLACE FUNCTION public.qm_direct_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_status text;
begin
  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;
  select status into v_status from public.question_threads where id = NEW.thread_id;
  if v_status in ('confirmed','closed','archived') then raise exception 'DIRECT_MSG_THREAD_LOCKED'; end if;
  return NEW;
end; $function$

CREATE OR REPLACE FUNCTION public.qna_append_message(p_thread_id uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_status text; v_thread_status text;
  v_first_answered timestamptz; v_message_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_sub_id uuid;
  v_susp timestamptz; v_norm text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if char_length(p_body)>10000 then raise exception 'MESSAGE_TOO_LONG'; end if;
  if p_body is null or btrim(p_body)='' then raise exception 'BODY_REQUIRED'; end if;
  perform core_private.qna_lock_thread_write(p_thread_id,'message');
  select t.mentor_student_room_id,t.status,t.first_answered_at into v_room,v_thread_status,v_first_answered from public.question_threads t where id=p_thread_id;
  select student_id,mentor_id into v_student,v_mentor from public.mentor_student_rooms where id=v_room;
  v_is_mentor := v_uid=v_mentor;
  -- F2(D-12)+R1: 아래 INSERT 가 AFTER INSERT 알림 트리거를 발화 — 멘토 메시지 행 1건 = 알림 정확히 1건.
  insert into public.question_messages (thread_id, author_id, body) values (p_thread_id, v_uid, btrim(p_body)) returning id into v_message_id;
  if v_is_mentor and v_first_answered is null then
    update public.question_threads set status='answered', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;
    v_transitioned := true;
  end if;
  return jsonb_build_object('ok',true,'message_id',v_message_id,'answered_transition',v_transitioned);
end; $function$

CREATE OR REPLACE FUNCTION public.qna_apply_answered_transition(p_thread_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_room uuid; v_status text; v_first timestamptz; v_student uuid; v_mentor uuid;
begin
  select mentor_student_room_id, status, first_answered_at into v_room, v_status, v_first from public.question_threads where id=p_thread_id;
  if v_room is null then return; end if;
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;
  if auth.uid() is distinct from v_mentor then return; end if;          -- 멘토만
  if v_first is not null or v_status not in ('pending','open') then return; end if;
  if not exists (select 1 from public.question_messages m where m.thread_id=p_thread_id and m.author_id=v_mentor)
     and not exists (select 1 from public.question_attachments a where a.thread_id=p_thread_id and a.author_id=v_mentor) then
    return; -- content-less: no-op
  end if;
  update public.question_threads set status='answered', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;
end; $function$

CREATE OR REPLACE FUNCTION public.qna_confirm_thread(p_thread_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_status text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  select t.mentor_student_room_id, t.status into v_room, v_status from public.question_threads t where t.id=p_thread_id for update;
  if not found then raise exception 'THREAD_NOT_FOUND'; end if;
  select student_id into v_student from public.mentor_student_rooms where id=v_room;
  if v_uid <> v_student then raise exception 'STUDENT_ONLY'; end if;
  if v_status='confirmed' then return jsonb_build_object('ok',true,'thread_id',p_thread_id); end if;
  if v_status <> 'answered' then raise exception 'NOT_ANSWERED'; end if;
  update public.question_threads set status='confirmed', confirmed_at=coalesce(confirmed_at,now()), updated_at=now() where id=p_thread_id;
  return jsonb_build_object('ok',true,'thread_id',p_thread_id);
end; $function$

CREATE OR REPLACE FUNCTION public.qna_create_question_thread(p_room_id uuid, p_title text, p_subject text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_first_message_body text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid; v_status text; v_suspended_until timestamptz;
  v_created_at timestamptz; v_total int; v_per int; v_subject text; v_thread_id uuid; v_message_id uuid;
  v_event uuid; v_redemption uuid; v_entitlement uuid; v_payment uuid; v_decided_at timestamptz; v_code text; v_start timestamptz; v_end timestamptz; v_week timestamptz; v_used integer; v_has_active_sub boolean; v_usage json; v_path text; v_sub_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if char_length(p_title)>120 then raise exception 'TITLE_TOO_LONG'; end if;
  if char_length(p_topic)>80 then raise exception 'TOPIC_TOO_LONG'; end if;
  if char_length(p_first_message_body)>10000 then raise exception 'MESSAGE_TOO_LONG'; end if;
  if char_length(p_subject)>64 then raise exception 'SUBJECT_INVALID'; end if;
  if p_title is null or btrim(p_title)='' then raise exception 'TITLE_REQUIRED'; end if;
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=p_room_id;
  if not found then raise exception 'ROOM_NOT_FOUND'; end if;
  if v_uid <> v_student then
    if v_uid = v_mentor then raise exception 'MENTOR_CANNOT_CREATE_THREAD'; else raise exception 'NOT_ROOM_PARTY'; end if;
  end if;
  perform pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
  select id,current_service_period_event_id into v_sub_id,v_event from public.subscriptions
    where student_id=v_student and mentor_id=v_mentor order by created_at desc limit 1;
  if v_event is not null then
    perform core_private.lock_service_period_finance(v_event);
    select voucher_redemption_id into v_redemption from public.subscription_billing_events where id=v_event;
  else
    perform 1 from public.subscriptions where id=v_sub_id for update;
    perform 1 from public.mentor_profiles where user_id=v_mentor for update;
  end if;
  perform 1 from public.users where id=v_student for update;
  v_decided_at := clock_timestamp();
  v_code := core_private.qna_pair_write_eligibility(v_student,v_mentor,v_uid,v_decided_at);
  if v_code <> 'allowed' then raise exception '%',v_code; end if;
  select status, suspended_until, created_at into v_status, v_suspended_until, v_created_at from public.users where id=v_student;
  if lower(coalesce(v_status,'active'))='banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if lower(coalesce(v_status,'active'))='suspended' and (v_suspended_until is null or v_suspended_until > v_decided_at) then raise exception 'ACCOUNT_SUSPENDED'; end if;
  if exists (select 1 from public.user_blocks where (blocker_id=v_student and blocked_id=v_mentor) or (blocker_id=v_mentor and blocked_id=v_student)) then raise exception 'BLOCKED'; end if;
  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception 'MENTOR_NOT_APPROVED'; end if;
  if v_event is not null then
    v_code := core_private.service_period_eligibility(v_event,v_uid,'new_question',v_decided_at);
    if v_code <> 'allowed' then raise exception '%',v_code; end if;
    if v_redemption is not null then
      v_usage := core_private.qna_voucher_weekly_usage(v_event,v_decided_at);
      if not (v_usage->>'can_ask')::boolean then raise exception 'WEEKLY_LIMIT_EXHAUSTED'; end if;
    else
      v_usage := core_private.qna_cash_weekly_usage(v_student,v_mentor,v_decided_at);
      if not coalesce((v_usage->>'can_ask')::boolean,false) then raise exception 'WEEKLY_LIMIT_EXHAUSTED'; end if;
    end if;
    v_path := 'subscription';
  elsif exists(select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and status='active') then
    -- An active row without a verified financial period is unknown, not cash.
    raise exception 'SERVICE_PERIOD_UNBOUND';
  else
    if exists(select 1 from public.voucher_redemptions where student_id=v_student and mentor_id=v_mentor) then raise exception 'SERVICE_PERIOD_EXPIRED'; end if;
    if v_created_at is not null and v_decided_at >= v_created_at + interval '7 days' then raise exception 'FREE_QUOTA_EXPIRED'; end if;
    select count(*) into v_total from public.free_question_usage where student_id=v_student;
    if v_total >= 7 then raise exception 'FREE_QUOTA_TOTAL_EXHAUSTED'; end if;
    select count(*) into v_per from public.free_question_usage where student_id=v_student and mentor_id=v_mentor;
    if v_per >= 3 then raise exception 'FREE_QUOTA_MENTOR_EXHAUSTED'; end if;
    v_path := 'free';
  end if;
  v_subject := nullif(btrim(coalesce(p_subject,'')),'');
  if v_subject is not null and not exists (select 1 from public.subjects where code=v_subject) then raise exception 'SUBJECT_INVALID'; end if;
  insert into public.question_threads (mentor_student_room_id, title, status, subject, topic, service_period_event_id, created_at)
  values (p_room_id, btrim(p_title), 'pending', v_subject, nullif(btrim(coalesce(p_topic,'')),''),v_event,v_decided_at) returning id into v_thread_id;
  if p_first_message_body is not null and btrim(p_first_message_body) <> '' then
    insert into public.question_messages (thread_id, author_id, body) values (v_thread_id, v_student, btrim(p_first_message_body)) returning id into v_message_id;
  end if;
  if v_path='free' then insert into public.free_question_usage (student_id, mentor_id, thread_id) values (v_student, v_mentor, v_thread_id); end if;

  -- ── 새 질문 → 방 멘토 인앱 알림(question_received) ──
  -- 20260805 도입(구독 한정) → S1-7/QA-C13 에서 무료 경로까지 확장.
  -- 같은 트랜잭션 안 — 위 생성이 롤백되면 알림도 롤백(원자), record_domain_notification
  -- 이 (recipient,event_key) 멱등 + outbox 게이트를 기존 계약대로 처리한다.
  -- S1-7/QA-C13: 무료·구독 경로 모두 알린다(종전에는 subscription 한정 조건이 있었다).
    perform public.record_domain_notification(
      v_mentor,
      'question_received:' || v_thread_id::text,
      'question_received:' || v_thread_id::text,
      'question_received',
      '새 질문이 도착했어요',
      '학생이 새 질문을 등록했어요.',
      '/mentor/question-room/' || p_room_id::text || '?thread=' || v_thread_id::text,
      jsonb_build_object('room_id', p_room_id, 'thread_id', v_thread_id, 'student_id', v_student),
      jsonb_build_object('room_id', p_room_id, 'thread_id', v_thread_id, 'student_id', v_student)
    );

  return jsonb_build_object('ok',true,'thread_id',v_thread_id,'message_id',v_message_id,'path',v_path,'used_free_quota',(v_path='free'));
end;
$function$

CREATE OR REPLACE FUNCTION public.qna_emit_answer_notification(p_thread_id uuid, p_message_id uuid DEFAULT NULL::uuid, p_attachment_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_room uuid; v_student uuid; v_mentor uuid; v_name text;
  v_key text; v_body_suffix text; v_meta jsonb;
  v_actor uuid;
begin
  if p_thread_id is null then return; end if;
  -- 정확히 하나의 행 스코프(메시지 XOR 단독첨부)만 허용 — 호출 계약 위반은 즉시 실패(무음 금지).
  if (p_message_id is null) = (p_attachment_id is null) then
    raise exception 'ANSWER_EVENT_SCOPE_REQUIRED';
  end if;

  select t.mentor_student_room_id into v_room
  from public.question_threads t where t.id = p_thread_id;
  if v_room is null then return; end if;

  select student_id, mentor_id into v_student, v_mentor
  from public.mentor_student_rooms where id = v_room;
  if v_student is null then return; end if;

  v_actor := (select auth.uid());

  -- ── 멘토 발신 → 학생 (기존 동작 · 불변) ────────────────────────────────
  if v_actor is not distinct from v_mentor then
    if p_message_id is not null then
      if not exists (
        select 1 from public.question_messages m
        where m.id = p_message_id and m.thread_id = p_thread_id and m.author_id = v_mentor
      ) then return; end if;
      v_key := 'question_answer_message:' || p_message_id::text;
      v_body_suffix := '님이 답변을 남겼습니다.';
      v_meta := jsonb_build_object('room_id', v_room, 'thread_id', p_thread_id, 'message_id', p_message_id);
    else
      if not exists (
        select 1 from public.question_attachments a
        where a.id = p_attachment_id and a.thread_id = p_thread_id
          and a.author_id = v_mentor and a.message_id is null
      ) then return; end if;
      v_key := 'question_answer_attachment:' || p_attachment_id::text;
      v_body_suffix := '님이 파일을 보냈습니다.';
      v_meta := jsonb_build_object('room_id', v_room, 'thread_id', p_thread_id, 'attachment_id', p_attachment_id);
    end if;

    select coalesce(nullif(btrim(full_name),''), nullif(btrim(nickname),''), '멘토')
      into v_name from public.users where id = v_mentor;

    perform public.record_domain_notification(
      v_student,
      v_key,
      v_key,
      'question_answered',
      '새 답변이 도착했어요',
      coalesce(v_name,'멘토') || v_body_suffix,
      '/question-room/' || v_room::text || '?thread=' || p_thread_id::text,
      v_meta,
      v_meta
    );
    return;
  end if;

  -- ── 학생 발신 → 멘토 (S1-4 신규) ──────────────────────────────────────
  if v_actor is not distinct from v_student then
    if p_message_id is not null then
      if not exists (
        select 1 from public.question_messages m
        where m.id = p_message_id and m.thread_id = p_thread_id and m.author_id = v_student
      ) then return; end if;
      -- ★ 스레드의 **첫 메시지**는 이 경로에서 알리지 않는다.
      --   질문 생성 RPC(qna_create_question_thread)가 이미 '새 질문이 도착했어요'
      --   (question_received:<thread_id>)를 보내므로, 여기서 또 보내면 질문
      --   1건에 멘토 알림이 2건 생긴다(무료·구독 공통 — 검증에서 실제 확인).
      --
      --   판정 기준은 **이 스레드에 이보다 앞선 메시지가 있는가**다.
      --   앞선 것이 없으면 곧 첫 메시지 → 침묵, 있으면 → 알림.
      --   (초안이던 '스레드와 같은 트랜잭션인가'(m2.created_at = t2.created_at)는
      --    p_first_message_body 를 주지 않고 스레드만 만드는 경로에서 무너진다 —
      --    free_question_entry.createFreeThread 의 firstMessageBody 는 nullable 이라
      --    학생의 진짜 첫 메시지가 별도 트랜잭션으로 들어오고, 그러면 생성 알림과
      --    이 알림이 겹쳐 다시 2건이 된다. 그 경로까지 덮으려면 순서 비교가 맞다.)
      --   동률 created_at 도 (created_at, id) 튜플 비교로 전순서가 되어
      --   2번째 메시지를 잘못 삼키지 않는다.
      if not exists (
        select 1
          from public.question_messages m_prev
          join public.question_messages m_self on m_self.id = p_message_id
         where m_prev.thread_id = p_thread_id
           and (m_prev.created_at, m_prev.id) < (m_self.created_at, m_self.id)
      ) then return; end if;
      v_key := 'question_student_message:' || p_message_id::text;
      v_body_suffix := '님이 메시지를 보냈어요.';
      v_meta := jsonb_build_object('room_id', v_room, 'thread_id', p_thread_id, 'message_id', p_message_id);
    else
      if not exists (
        select 1 from public.question_attachments a
        where a.id = p_attachment_id and a.thread_id = p_thread_id
          and a.author_id = v_student and a.message_id is null
      ) then return; end if;
      v_key := 'question_student_attachment:' || p_attachment_id::text;
      v_body_suffix := '님이 파일을 보냈어요.';
      v_meta := jsonb_build_object('room_id', v_room, 'thread_id', p_thread_id, 'attachment_id', p_attachment_id);
    end if;

    select coalesce(nullif(btrim(full_name),''), nullif(btrim(nickname),''), '학생')
      into v_name from public.users where id = v_student;

    perform public.record_domain_notification(
      v_mentor,
      v_key,
      v_key,
      'question_received',
      '새 메시지가 도착했어요',
      coalesce(v_name,'학생') || v_body_suffix,
      '/mentor/question-room/' || v_room::text || '?thread=' || p_thread_id::text,
      v_meta,
      v_meta
    );
    return;
  end if;

  -- 방 당사자가 아닌 세션(관리자·워커 등)은 알림을 만들지 않는다.
  return;
end;
$function$

CREATE OR REPLACE FUNCTION public.qna_flag_wrong_answer(p_thread_id uuid, p_is_wrong boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_room uuid;
  v_student uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;

  select t.mentor_student_room_id into v_room
  from public.question_threads t where t.id = p_thread_id for update;
  if not found then raise exception 'THREAD_NOT_FOUND'; end if;

  select student_id into v_student from public.mentor_student_rooms where id = v_room;
  if v_uid <> v_student then raise exception 'STUDENT_ONLY'; end if;

  update public.question_threads
    set is_wrong_answer = coalesce(p_is_wrong, true),
        mastery_status = case when coalesce(p_is_wrong, true) then 'wrong' else 'unknown' end,
        updated_at = now()
  where id = p_thread_id;

  return jsonb_build_object('ok', true, 'thread_id', p_thread_id, 'is_wrong_answer', coalesce(p_is_wrong, true));
end;
$function$

CREATE OR REPLACE FUNCTION public.qna_register_attachment(p_thread_id uuid, p_storage_path text, p_file_name text DEFAULT NULL::text, p_mime_type text DEFAULT NULL::text, p_message_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_thread_status text;
  v_first_answered timestamptz; v_att_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_sub_id uuid;
  v_status text; v_susp timestamptz; v_norm text;
begin
  perform core_private.qna_assert_text_bound(p_storage_path,1024);
  perform core_private.qna_assert_text_bound(p_file_name,255);
  perform core_private.qna_assert_text_bound(p_mime_type,127);

  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_storage_path is null or btrim(p_storage_path)='' then raise exception 'STORAGE_PATH_REQUIRED'; end if;
  perform core_private.qna_lock_thread_write(p_thread_id,'attachment');
  select t.mentor_student_room_id,t.status,t.first_answered_at into v_room,v_thread_status,v_first_answered from public.question_threads t where id=p_thread_id;
  select student_id,mentor_id into v_student,v_mentor from public.mentor_student_rooms where id=v_room;
  v_is_mentor := v_uid=v_mentor;
  if p_storage_path not like (v_room::text || '/' || p_thread_id::text || '/%') then raise exception 'STORAGE_PATH_MISMATCH'; end if;
  if not exists (select 1 from storage.objects o where o.bucket_id='question-room-attachments' and o.name=btrim(p_storage_path) and o.owner_id=v_uid::text) then raise exception 'STORAGE_OBJECT_NOT_OWNED'; end if;
  if p_message_id is not null and not exists(select 1 from public.question_messages where id=p_message_id and thread_id=p_thread_id) then raise exception 'MESSAGE_THREAD_MISMATCH'; end if;
  -- F2(D-12)+R1: 아래 INSERT 가 AFTER INSERT 알림 트리거를 발화 — 멘토 단독 첨부 행 1건 = 알림 정확히 1건.
  insert into public.question_attachments (thread_id, message_id, author_id, storage_path, file_name, mime_type)
  values (p_thread_id, p_message_id, v_uid, btrim(p_storage_path), p_file_name, p_mime_type) returning id into v_att_id;
  if v_is_mentor and v_first_answered is null then
    update public.question_threads set status='answered', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;
    v_transitioned := true;
  end if;
  return jsonb_build_object('ok',true,'attachment_id',v_att_id,'answered_transition',v_transitioned);
end; $function$

CREATE OR REPLACE FUNCTION public.qra_path_upload_eligible(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_thread uuid; v_room uuid;
BEGIN
 IF auth.uid() IS NULL OR length(p_name)>1024 THEN RETURN false; END IF;
 BEGIN
  v_room:=split_part(p_name,'/',1)::uuid;
  v_thread:=split_part(p_name,'/',2)::uuid;
 EXCEPTION WHEN invalid_text_representation THEN RETURN false;
 END;
 IF split_part(p_name,'/',3)='' OR NOT EXISTS(SELECT 1 FROM public.question_threads WHERE id=v_thread AND mentor_student_room_id=v_room) THEN RETURN false; END IF;
 BEGIN
  PERFORM core_private.qna_lock_thread_write(v_thread,'attachment');
 EXCEPTION WHEN raise_exception THEN RETURN false;
 END;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.qra_uploader_allowed_for_path(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_room uuid; v_student uuid; v_mentor uuid; v_uid uuid := auth.uid(); v_status text;
begin
  if v_uid is null then return false; end if;
  v_room := public.qra_room_uuid_from_path(p_name);
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = v_room;
  if v_student is null then return false; end if;
  select status into v_status from public.users where id = v_uid;
  if lower(coalesce(v_status,'active')) = 'banned' then return false; end if;
  if lower(coalesce(v_status,'active')) = 'suspended' then
    if exists (select 1 from public.users where id=v_uid and (suspended_until is null or suspended_until > now())) then return false; end if;
  end if;
  if v_uid = v_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then return false; end if;
  if public.qna_users_blocked(v_student, v_mentor) then return false; end if;
  return true;
end; $function$

CREATE OR REPLACE FUNCTION public.qt_direct_consume_free_usage()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_student uuid; v_mentor uuid;
begin
  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = NEW.mentor_student_room_id;
  if not exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''))='active') then
    insert into public.free_question_usage (student_id, mentor_id, thread_id) values (v_student, v_mentor, NEW.id);
  end if;
  return NEW;
end; $function$

CREATE OR REPLACE FUNCTION public.qt_direct_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid; v_status text; v_suspended_until timestamptz;
  v_created_at timestamptz; v_total int; v_per int; v_has_sub boolean; v_usage json; v_sub_id uuid;
begin
  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = NEW.mentor_student_room_id;
  if TG_OP = 'INSERT' then
    if v_student is null then raise exception 'ROOM_NOT_FOUND'; end if;
    if v_uid is distinct from v_student then raise exception 'DIRECT_CREATE_STUDENT_ONLY'; end if;
    if coalesce(NEW.status,'pending') not in ('pending','open') then raise exception 'DIRECT_INSERT_STATUS_FORBIDDEN'; end if;
    if NEW.first_answered_at is not null or NEW.confirmed_at is not null then raise exception 'DIRECT_INSERT_WORKFLOW_FIELDS_FORBIDDEN'; end if;
    select status, suspended_until, created_at into v_status, v_suspended_until, v_created_at from public.users where id=v_student;
    if lower(coalesce(v_status,'active'))='banned' then raise exception 'ACCOUNT_BANNED'; end if;
    if lower(coalesce(v_status,'active'))='suspended' and (v_suspended_until is null or v_suspended_until > now()) then raise exception 'ACCOUNT_SUSPENDED'; end if;
    if public.qna_users_blocked(v_student, v_mentor) then raise exception 'BLOCKED'; end if;
    if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception 'MENTOR_NOT_APPROVED'; end if;
    v_has_sub := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''))='active');
    if v_has_sub then
      select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''))='active';
      if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception 'SUBSCRIPTION_REFUND_PENDING'; end if;
      v_usage := public.get_weekly_question_usage(v_student, v_mentor);
      if not coalesce((v_usage->>'can_ask')::boolean, false) then raise exception 'WEEKLY_LIMIT_EXHAUSTED'; end if;
    else
      if v_created_at is not null and now() >= v_created_at + interval '7 days' then raise exception 'FREE_QUOTA_EXPIRED'; end if;
      select count(*) into v_total from public.free_question_usage where student_id=v_student;
      if v_total >= 7 then raise exception 'FREE_QUOTA_TOTAL_EXHAUSTED'; end if;
      select count(*) into v_per from public.free_question_usage where student_id=v_student and mentor_id=v_mentor;
      if v_per >= 3 then raise exception 'FREE_QUOTA_MENTOR_EXHAUSTED'; end if;
    end if;
    return NEW;
  end if;
  if NEW.status is distinct from OLD.status then
    if NEW.status = 'answered' then raise exception 'DIRECT_ANSWERED_VIA_CONTENT_ONLY'; end if;
    if NEW.status = 'confirmed' and v_uid is distinct from v_student then raise exception 'DIRECT_CONFIRM_STUDENT_ONLY'; end if;
  end if;
  if NEW.first_answered_at is distinct from OLD.first_answered_at then raise exception 'DIRECT_FIRST_ANSWERED_VIA_CONTENT_ONLY'; end if;
  if (NEW.is_wrong_answer is distinct from OLD.is_wrong_answer or NEW.mastery_status is distinct from OLD.mastery_status) and v_uid is distinct from v_student then raise exception 'DIRECT_WRONG_FLAG_STUDENT_ONLY'; end if;
  return NEW;
end; $function$

CREATE OR REPLACE FUNCTION public.record_custom_order_dispute_split(p_order_id uuid, p_mentor_gross_won integer, p_student_refund_won integer, p_admin_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o public.custom_request_orders%rowtype;
  s public.custom_order_settlement_items%rowtype;
  v_hold_idem text := 'cr_hold_' || p_order_id::text;
  v_payout_idem text := 'cr_payout_' || p_order_id::text;
  v_refund_idem text := 'cr_refund_' || p_order_id::text;
  v_dispute_payout_idem text := 'cr_dispute_payout_' || p_order_id::text;
  v_dispute_refund_idem text := 'cr_dispute_refund_' || p_order_id::text;
  v_hold_cents bigint;
  v_hold_gross_won integer;
  v_settlement_gross integer;
  v_fee_rate numeric;                 -- 191: 정산 행(custom_order_settlement_items.fee_rate)에서 읽는다 — 내부 상수 없음
  v_settlement_found boolean := false;
  v_platform_fee_won integer;
  v_mentor_net_won integer;
  v_mentor_cents bigint;
  v_student_cents bigint;
  v_pay text;
  v_norm text;
  v_admin_ok boolean;
  v_new_mentor_ledger uuid;
  v_new_student_ledger uuid;
  v_wu int;
  v_now timestamptz := now();
  v_disputes_resolved int := 0;
begin
  if p_order_id is null then
    raise exception 'p_order_id is required';
  end if;
  if p_admin_id is null then
    raise exception 'ADMIN_REQUIRED';
  end if;
  if p_mentor_gross_won is null or p_student_refund_won is null then
    raise exception 'DISPUTE_SPLIT_AMOUNTS_REQUIRED';
  end if;
  if p_mentor_gross_won < 0 or p_student_refund_won < 0 then
    raise exception 'DISPUTE_SPLIT_AMOUNTS_INVALID';
  end if;

  select exists(
    select 1 from public.users u where u.id = p_admin_id and u.role = 'admin'
  ) into v_admin_ok;
  if not coalesce(v_admin_ok, false) then
    raise exception 'ADMIN_REQUIRED';
  end if;

  select * into o
  from public.custom_request_orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  if o.student_id is null or o.mentor_id is null then
    raise exception 'ORDER_PARTIES_MISSING';
  end if;

  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''), '')));
  v_norm := public._order_primary_status_norm(o);

  -- payout / refund / dispute-split 상호 배타
  if exists (
    select 1 from public.cash_ledger l
    where l.idempotency_key = v_payout_idem
      and l.reason = 'custom_order_escrow_payout'
  ) then
    raise exception 'ALREADY_PAID_OUT';
  end if;

  if exists (
    select 1 from public.cash_ledger l
    where l.idempotency_key = v_refund_idem
      and l.reason = 'custom_order_escrow_refund'
  ) then
    raise exception 'ALREADY_REFUNDED';
  end if;

  select * into s
  from public.custom_order_settlement_items
  where custom_request_order_id = p_order_id
  for update;
  v_settlement_found := found;

  if v_settlement_found and s.status = 'paid' then
    raise exception 'ALREADY_PAID_OUT';
  end if;

  -- 191: 플랫폼 수수료율은 해당 주문의 정산 행 요율만 쓴다. 정산 행이 없거나 요율이 NULL 이면
  --      추측하지 않고 예외(부분 반영 0 — 트랜잭션 전체 rollback).
  if not v_settlement_found or s.fee_rate is null then
    raise exception 'SETTLEMENT_FEE_RATE_MISSING';
  end if;
  v_fee_rate := s.fee_rate;

  select abs(l.delta_cents) into v_hold_cents
  from public.cash_ledger l
  where l.idempotency_key = v_hold_idem
    and l.reason = 'custom_order_escrow_hold'
  limit 1;

  if v_hold_cents is null then
    raise exception 'ESCROW_HOLD_MISSING';
  end if;

  if v_hold_cents <= 0 or v_hold_cents > 1000000000 then
    raise exception 'ESCROW_HOLD_AMOUNT_INVALID';
  end if;

  if v_hold_cents % 100 <> 0 then
    raise exception 'ESCROW_HOLD_AMOUNT_INVALID';
  end if;

  v_hold_gross_won := (v_hold_cents / 100)::integer;

  if found then
    v_settlement_gross := s.gross_amount;
    if v_settlement_gross is distinct from v_hold_gross_won then
      raise exception 'ESCROW_HOLD_AMOUNT_MISMATCH';
    end if;
  end if;

  -- 멱등: 분배 ledger 가 하나라도 있으면 상태 수리 후 종료
  if exists (
    select 1 from public.cash_ledger l
    where l.idempotency_key in (v_dispute_payout_idem, v_dispute_refund_idem)
      and l.reason in ('custom_order_dispute_payout', 'custom_order_dispute_refund')
  ) then
    update public.custom_order_settlement_items
    set status = 'cancelled', updated_at = v_now
    where custom_request_order_id = p_order_id
      and status in ('pending', 'on_hold', 'payable');

    update public.custom_request_orders
    set
      payment_status = 'dispute_resolved',
      status = 'dispute_resolved',
      state = 'dispute_resolved',
      order_status = 'dispute_resolved',
      updated_at = v_now
    where id = p_order_id;

    update public.disputes d
    set
      status = 'resolved',
      resolved_at = coalesce(d.resolved_at, v_now),
      resolved_by = coalesce(d.resolved_by, p_admin_id),
      updated_at = v_now
    where d.custom_request_order_id = p_order_id
      and d.status in ('open', 'under_review', 'escalated');

    get diagnostics v_disputes_resolved = row_count;

    return jsonb_build_object(
      'ok', true,
      'noop', true,
      'order_id', p_order_id,
      'hold_gross_won', v_hold_gross_won,
      'disputes_resolved', v_disputes_resolved
    );
  end if;

  if p_mentor_gross_won + p_student_refund_won is distinct from v_hold_gross_won then
    raise exception 'DISPUTE_SPLIT_MISMATCH';
  end if;

  if v_pay not in ('escrowed', 'dispute_resolved') then
    raise exception 'PAYMENT_NOT_ESCROWED';
  end if;

  v_platform_fee_won := floor(p_mentor_gross_won * v_fee_rate)::integer;
  v_mentor_net_won := p_mentor_gross_won - v_platform_fee_won;
  v_mentor_cents := v_mentor_net_won::bigint * 100;
  v_student_cents := p_student_refund_won::bigint * 100;

  if v_mentor_cents > 1000000000 or v_student_cents > 1000000000 then
    raise exception 'p_amount_too_large';
  end if;

  if v_mentor_cents > 0 then
    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
    values (
      o.mentor_id,
      v_mentor_cents,
      'custom_order_dispute_payout',
      'custom_request_orders',
      p_order_id,
      v_dispute_payout_idem
    )
    on conflict (idempotency_key) do nothing
    returning id into v_new_mentor_ledger;

    if v_new_mentor_ledger is not null then
      insert into public.cash_wallets (user_id, balance_cents)
      values (o.mentor_id, 0)
      on conflict (user_id) do nothing;

      update public.cash_wallets w
      set balance_cents = w.balance_cents + v_mentor_cents
      where w.user_id = o.mentor_id;
      get diagnostics v_wu = row_count;
      if coalesce(v_wu, 0) = 0 then
        raise exception 'CASH_WALLET_UPDATE_FAILED' using errcode = 'P0001';
      end if;
    end if;
  end if;

  if v_student_cents > 0 then
    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
    values (
      o.student_id,
      v_student_cents,
      'custom_order_dispute_refund',
      'custom_request_orders',
      p_order_id,
      v_dispute_refund_idem
    )
    on conflict (idempotency_key) do nothing
    returning id into v_new_student_ledger;

    if v_new_student_ledger is not null then
      insert into public.cash_wallets (user_id, balance_cents)
      values (o.student_id, 0)
      on conflict (user_id) do nothing;

      update public.cash_wallets w
      set balance_cents = w.balance_cents + v_student_cents
      where w.user_id = o.student_id;
      get diagnostics v_wu = row_count;
      if coalesce(v_wu, 0) = 0 then
        raise exception 'CASH_WALLET_UPDATE_FAILED' using errcode = 'P0001';
      end if;
    end if;
  end if;

  update public.custom_order_settlement_items
  set status = 'cancelled', updated_at = v_now
  where custom_request_order_id = p_order_id
    and status in ('pending', 'on_hold', 'payable');

  update public.custom_request_orders
  set
    payment_status = 'dispute_resolved',
    status = 'dispute_resolved',
    state = 'dispute_resolved',
    order_status = 'dispute_resolved',
    updated_at = v_now
  where id = p_order_id;

  update public.disputes d
  set
    status = 'resolved',
    resolved_at = coalesce(d.resolved_at, v_now),
    resolved_by = coalesce(d.resolved_by, p_admin_id),
    updated_at = v_now
  where d.custom_request_order_id = p_order_id
    and d.status in ('open', 'under_review', 'escalated');

  get diagnostics v_disputes_resolved = row_count;

  return jsonb_build_object(
    'ok', true,
    'noop', false,
    'order_id', p_order_id,
    'hold_gross_won', v_hold_gross_won,
    'mentor_gross_won', p_mentor_gross_won,
    'mentor_platform_fee_won', v_platform_fee_won,
    'mentor_net_won', v_mentor_net_won,
    'mentor_cents', v_mentor_cents,
    'student_refund_won', p_student_refund_won,
    'student_cents', v_student_cents,
    'fee_rate', v_fee_rate,
    'disputes_resolved', v_disputes_resolved
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.record_custom_order_escrow_hold(p_student_id uuid, p_order_id uuid, p_amount_cents bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_idem text := 'cr_hold_' || p_order_id::text;
  v_new_ledger_id uuid;
  v_wu int;
begin
  if p_student_id is null or p_order_id is null then
    raise exception 'p_student_id and p_order_id are required';
  end if;

  if p_amount_cents is null or p_amount_cents <= 0 then
    raise exception 'p_amount_cents must be a positive amount';
  end if;

  if p_amount_cents > 1000000000 then
    raise exception 'p_amount_too_large';
  end if;

  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
  values (
    p_student_id,
    -p_amount_cents,
    'custom_order_escrow_hold',
    'custom_request_orders',
    p_order_id,
    v_idem
  )
  on conflict (idempotency_key) do nothing
  returning id into v_new_ledger_id;

  if v_new_ledger_id is null then
    return;
  end if;

  insert into public.cash_wallets (user_id, balance_cents)
  values (p_student_id, 0)
  on conflict (user_id) do nothing;

  update public.cash_wallets w
  set balance_cents = w.balance_cents - p_amount_cents
  where w.user_id = p_student_id
    and w.balance_cents >= p_amount_cents;
  get diagnostics v_wu = row_count;
  if coalesce(v_wu, 0) = 0 then
    raise exception 'CASH_INSUFFICIENT' using errcode = 'P0001';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_custom_order_escrow_payout(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o public.custom_request_orders%rowtype;
  s public.custom_order_settlement_items%rowtype;
  v_idem text := 'cr_payout_' || p_order_id::text;
  v_mentor_cents bigint;
  v_hold_cents bigint;
  v_gross_cents bigint;
  v_new_ledger_id uuid;
  v_wu int;
  v_pay text;
  v_now timestamptz := now();
begin
  if p_order_id is null then
    raise exception 'p_order_id is required';
  end if;

  select * into o
  from public.custom_request_orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''), '')));

  select * into s
  from public.custom_order_settlement_items
  where custom_request_order_id = p_order_id
  for update;

  if not found then
    raise exception 'SETTLEMENT_NOT_FOUND';
  end if;

  -- 이미 지급 완료 — 멱등 수리(주문 payment_status 만 escrowed→paid 보정)
  if s.status = 'paid' then
    if v_pay = 'escrowed' then
      update public.custom_request_orders
      set payment_status = 'paid', updated_at = v_now
      where id = p_order_id;
    end if;
    return;
  end if;

  if s.status not in ('pending', 'payable', 'on_hold') then
    raise exception 'SETTLEMENT_NOT_PAYABLE';
  end if;

  -- escrowed(정상) 또는 paid(부분 실패 수리) 만 지급. unpaid·legacy 무예치 차단.
  if v_pay not in ('escrowed', 'paid') then
    raise exception 'PAYMENT_NOT_ESCROWED';
  end if;

  -- 예치 hold 존재·금액 정합: hold cents == settlement gross(원)×100
  select abs(l.delta_cents) into v_hold_cents
  from public.cash_ledger l
  where l.idempotency_key = 'cr_hold_' || p_order_id::text
    and l.reason = 'custom_order_escrow_hold'
  limit 1;

  v_gross_cents := s.gross_amount::bigint * 100;

  if v_hold_cents is null then
    raise exception 'ESCROW_HOLD_MISSING';
  end if;

  if v_hold_cents <> v_gross_cents then
    raise exception 'ESCROW_HOLD_AMOUNT_MISMATCH';
  end if;

  -- mentor_amount: 원(integer) → cents(원×100). gross/ledger 와 동일 단위 규칙.
  v_mentor_cents := s.mentor_amount::bigint * 100;

  if v_mentor_cents is null or v_mentor_cents <= 0 then
    raise exception 'INVALID_MENTOR_AMOUNT';
  end if;

  if v_mentor_cents > 1000000000 then
    raise exception 'p_amount_too_large';
  end if;

  -- 플랫폼 수수료(gross − mentor_amount)는 별도 platform wallet ledger 없음 — hold 차감분에 implicit.

  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
  values (
    s.mentor_id,
    v_mentor_cents,
    'custom_order_escrow_payout',
    'custom_request_orders',
    p_order_id,
    v_idem
  )
  on conflict (idempotency_key) do nothing
  returning id into v_new_ledger_id;

  if v_new_ledger_id is null then
    update public.custom_order_settlement_items
    set status = 'paid', paid_at = coalesce(paid_at, v_now), updated_at = v_now
    where id = s.id and status <> 'paid';

    update public.custom_request_orders
    set payment_status = 'paid', updated_at = v_now
    where id = p_order_id and payment_status = 'escrowed';

    return;
  end if;

  insert into public.cash_wallets (user_id, balance_cents)
  values (s.mentor_id, 0)
  on conflict (user_id) do nothing;

  update public.cash_wallets w
  set balance_cents = w.balance_cents + v_mentor_cents
  where w.user_id = s.mentor_id;
  get diagnostics v_wu = row_count;
  if coalesce(v_wu, 0) = 0 then
    raise exception 'CASH_WALLET_UPSERT_FAILED' using errcode = 'P0001';
  end if;

  update public.custom_order_settlement_items
  set status = 'paid', paid_at = v_now, updated_at = v_now
  where id = s.id;

  update public.custom_request_orders
  set payment_status = 'paid', updated_at = v_now
  where id = p_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_custom_order_escrow_refund(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o public.custom_request_orders%rowtype;
  s public.custom_order_settlement_items%rowtype;
  v_hold_idem text := 'cr_hold_' || p_order_id::text;
  v_payout_idem text := 'cr_payout_' || p_order_id::text;
  v_refund_idem text := 'cr_refund_' || p_order_id::text;
  v_hold_cents bigint;
  v_pay text;
  v_norm text;
  v_new_ledger_id uuid;
  v_wu int;
  v_now timestamptz := now();
begin
  if p_order_id is null then
    raise exception 'p_order_id is required';
  end if;

  select * into o
  from public.custom_request_orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  if o.student_id is null then
    raise exception 'STUDENT_NOT_FOUND';
  end if;

  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''), '')));
  v_norm := public._order_primary_status_norm(o);

  -- 멘토 지급 완료 차단: payout ledger 또는 settlement paid
  if exists (
    select 1 from public.cash_ledger l
    where l.idempotency_key = v_payout_idem
      and l.reason = 'custom_order_escrow_payout'
  ) then
    raise exception 'ALREADY_PAID_OUT';
  end if;

  select * into s
  from public.custom_order_settlement_items
  where custom_request_order_id = p_order_id
  for update;

  if found and s.status = 'paid' then
    raise exception 'ALREADY_PAID_OUT';
  end if;

  -- 멱등: 이미 환불 ledger 있으면 상태만 수리 후 종료
  if exists (
    select 1 from public.cash_ledger l
    where l.idempotency_key = v_refund_idem
      and l.reason = 'custom_order_escrow_refund'
  ) then
    if v_pay = 'escrowed' then
      update public.custom_request_orders
      set payment_status = 'refunded', updated_at = v_now
      where id = p_order_id;
    end if;

    update public.custom_order_settlement_items
    set status = 'cancelled', updated_at = v_now
    where custom_request_order_id = p_order_id
      and status in ('pending', 'on_hold', 'payable');

    if v_norm not in ('cancelled', 'canceled', 'refunded') then
      update public.custom_request_orders
      set
        status = 'cancelled',
        state = 'cancelled',
        order_status = 'cancelled',
        updated_at = v_now
      where id = p_order_id;
    end if;

    return;
  end if;

  -- hold 필수
  select abs(l.delta_cents) into v_hold_cents
  from public.cash_ledger l
  where l.idempotency_key = v_hold_idem
    and l.reason = 'custom_order_escrow_hold'
  limit 1;

  if v_hold_cents is null then
    raise exception 'ESCROW_HOLD_MISSING';
  end if;

  if v_hold_cents <= 0 or v_hold_cents > 1000000000 then
    raise exception 'ESCROW_HOLD_AMOUNT_INVALID';
  end if;

  -- 환불 대상: escrowed(정상) 또는 refunded(부분 실패 수리)
  if v_pay not in ('escrowed', 'refunded') then
    raise exception 'PAYMENT_NOT_ESCROWED';
  end if;

  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
  values (
    o.student_id,
    v_hold_cents,
    'custom_order_escrow_refund',
    'custom_request_orders',
    p_order_id,
    v_refund_idem
  )
  on conflict (idempotency_key) do nothing
  returning id into v_new_ledger_id;

  if v_new_ledger_id is null then
    return;
  end if;

  insert into public.cash_wallets (user_id, balance_cents)
  values (o.student_id, 0)
  on conflict (user_id) do nothing;

  update public.cash_wallets w
  set balance_cents = w.balance_cents + v_hold_cents
  where w.user_id = o.student_id;
  get diagnostics v_wu = row_count;
  if coalesce(v_wu, 0) = 0 then
    raise exception 'CASH_WALLET_UPDATE_FAILED' using errcode = 'P0001';
  end if;

  update public.custom_order_settlement_items
  set status = 'cancelled', updated_at = v_now
  where custom_request_order_id = p_order_id
    and status in ('pending', 'on_hold', 'payable');

  update public.custom_request_orders
  set
    payment_status = 'refunded',
    status = 'cancelled',
    state = 'cancelled',
    order_status = 'cancelled',
    updated_at = v_now
  where id = p_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_domain_notification(p_recipient_user_id uuid, p_event_key text, p_dedup_key text, p_event_type text, p_title text, p_body text, p_link text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_notif_id uuid; v_outbox_id uuid;
  v_notif_created boolean := false; v_outbox_created boolean := false;
  v_push_enabled boolean := false;
begin
  if p_recipient_user_id is null then raise exception 'RECIPIENT_REQUIRED'; end if;
  if p_event_key is null or p_dedup_key is null or p_event_type is null then raise exception 'EVENT_KEYS_REQUIRED'; end if;
  insert into public.notifications (recipient_user_id, user_id, event_key, type, body, metadata, data, is_read)
  values (p_recipient_user_id, p_recipient_user_id, p_event_key, p_event_type, p_body,
     coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('event_key', p_event_key, 'link', p_link),
     jsonb_build_object('title', p_title, 'link', p_link), false)
  on conflict (recipient_user_id, event_key) where recipient_user_id is not null and event_key is not null
  do nothing returning id into v_notif_id;
  v_notif_created := v_notif_id is not null;
  if v_notif_id is null then
    select id into v_notif_id from public.notifications where recipient_user_id = p_recipient_user_id and event_key = p_event_key limit 1;
  end if;

  -- OS push 전송로가 꺼져 있으면 outbox 를 새로 적재하지 않는다 (§14.6).
  -- 인앱 알림 행·멱등 계약은 위에서 그대로 유지됐다.
  select c.push_transport_enabled into v_push_enabled
    from public.notification_transport_config c where c.id is true;
  if coalesce(v_push_enabled, false) then
    insert into public.notification_outbox (recipient_user_id, notification_id, event_key, dedup_key, event_type, payload)
    values (p_recipient_user_id, v_notif_id, p_event_key, p_dedup_key, p_event_type,
       coalesce(p_payload,'{}'::jsonb) || jsonb_build_object('event_key', p_event_key, 'notification_id', v_notif_id))
    on conflict (recipient_user_id, dedup_key) do nothing returning id into v_outbox_id;
    v_outbox_created := v_outbox_id is not null;
    if v_outbox_id is null then
      select id into v_outbox_id from public.notification_outbox where recipient_user_id = p_recipient_user_id and dedup_key = p_dedup_key limit 1;
    end if;
  end if;

  return jsonb_build_object('ok',true,'notification_id',v_notif_id,'outbox_id',v_outbox_id,
    'notification_created',v_notif_created,'outbox_created',v_outbox_created);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_subscription_cash_debit(p_user_id uuid, p_subscription_id uuid, p_payment_id uuid, p_amount_cents bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_idem text := 'sub_debit_' || p_payment_id::text;
  v_new_ledger_id uuid;
  v_wu int;
begin
  if p_user_id is null or p_subscription_id is null or p_payment_id is null then
    raise exception 'p_user_id, p_subscription_id, p_payment_id are required';
  end if;

  if p_amount_cents is null or p_amount_cents <= 0 then
    raise exception 'p_amount_cents must be a positive amount';
  end if;

  -- 1) 멱등: idempotency_key 는 전역 unique. 먼저 insert 시도 → conflict 이면 이미 처리됨(지갑 재차감 없음)
  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
  values (
    p_user_id,
    -p_amount_cents,
    'subscription_payment',
    'subscriptions',
    p_subscription_id,
    v_idem
  )
  on conflict (idempotency_key) do nothing
  returning id into v_new_ledger_id;

  if v_new_ledger_id is null then
    return;
  end if;

  -- 2) wallet 행 + 잔액 차감 (insert 성공한 트랜잭션만 아래로 진행; 실패 시 1) 롤백)
  insert into public.cash_wallets (user_id, balance_cents)
  values (p_user_id, 0)
  on conflict (user_id) do nothing;

  update public.cash_wallets w
  set balance_cents = w.balance_cents - p_amount_cents
  where w.user_id = p_user_id
    and w.balance_cents >= p_amount_cents;
  get diagnostics v_wu = row_count;
  if coalesce(v_wu, 0) = 0 then
    raise exception 'CASH_INSUFFICIENT' using errcode = 'P0001';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_subscription_cash_rollback(p_user_id uuid, p_subscription_id uuid, p_payment_id uuid, p_amount_cents bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_idem text := 'sub_rollback_' || p_payment_id::text;
  v_new_ledger_id uuid;
  v_wu int;
begin
  if p_user_id is null or p_subscription_id is null or p_payment_id is null then
    raise exception 'p_user_id, p_subscription_id, p_payment_id are required';
  end if;
  if p_amount_cents is null or p_amount_cents <= 0 then
    return;
  end if;

  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
  values (
    p_user_id,
    p_amount_cents,
    'subscription_checkout_rollback',
    'subscriptions',
    p_subscription_id,
    v_idem
  )
  on conflict (idempotency_key) do nothing
  returning id into v_new_ledger_id;

  if v_new_ledger_id is null then
    return;
  end if;

  update public.cash_wallets w
  set balance_cents = w.balance_cents + p_amount_cents
  where w.user_id = p_user_id;
  get diagnostics v_wu = row_count;
  if coalesce(v_wu, 0) = 0 then
    insert into public.cash_wallets (user_id, balance_cents)
    values (p_user_id, p_amount_cents);
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_subscription_pg_refund_confirmation(p_refund_id uuid, p_payment_id uuid, p_cancellation_id text, p_amount_cents bigint, p_cancelled_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.refunds%rowtype; e public.subscription_billing_events%rowtype; p public.payments%rowtype; receipt public.subscription_pg_refund_receipts%rowtype; v_paid boolean;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if;
 select * into r from public.refunds where id=p_refund_id;
 if not found or r.billing_event_id is null then raise exception 'SERVICE_PERIOD_UNRESOLVED'; end if;
 perform core_private.lock_service_period_finance(r.billing_event_id);
 select * into e from public.subscription_billing_events where id=r.billing_event_id;
 select * into p from public.payments where id=e.payment_id;
 select * into r from public.refunds where id=p_refund_id for update;
 if p.id is null or p.id is distinct from p_payment_id or r.payment_id is distinct from p.id or r.user_id<>e.student_id or r.subscription_id<>e.subscription_id
 or p.pg_tx_id is null or p.pg_provider is null or e.voucher_redemption_id is not null then raise exception 'PG_REFUND_BINDING_MISMATCH'; end if;
 if p_amount_cents is distinct from r.amount_cents or p_amount_cents<=0 or p_amount_cents>e.amount_cents or p_cancelled_at is null or p_cancelled_at>clock_timestamp()
 or p_cancellation_id is null or char_length(p_cancellation_id) not between 1 and 200 then raise exception 'PG_REFUND_PROOF_INVALID'; end if;
 select * into receipt from public.subscription_pg_refund_receipts where refund_id=r.id;
 if found then
  if receipt.payment_id<>p.id or receipt.cancellation_id<>p_cancellation_id or receipt.amount_cents<>p_amount_cents or receipt.cancelled_at<>p_cancelled_at then raise exception 'PG_REFUND_REPLAY_CONFLICT'; end if;
  return jsonb_build_object('ok',true,'idempotent',true,'refund_id',r.id);
 end if;
 perform 1 from public.subscription_settlement_items where billing_event_id=e.id for update;
 select exists(select 1 from public.subscription_settlement_items where billing_event_id=e.id and status='paid') into v_paid;
 insert into public.subscription_pg_refund_receipts(refund_id,payment_id,provider,cancellation_id,amount_cents,cancelled_at)
 values(r.id,p.id,p.pg_provider,p_cancellation_id,p_amount_cents,p_cancelled_at);
 update public.refunds set pg_cancellation_id=p_cancellation_id,pg_cancelled_at=p_cancelled_at,status='succeeded',processed_at=clock_timestamp() where id=r.id;
 update public.payments set status='refunded',updated_at=now() where id=p.id;
 if p_amount_cents=e.amount_cents then update public.refunds set status='canceled' where billing_event_id=e.id and status='pending' and id<>r.id; end if;
 if v_paid or p_amount_cents<e.amount_cents then
  insert into public.service_period_financial_holds(billing_event_id,state,reason)
  values(e.id,case when v_paid then 'adjustment_required' else 'hold' end,case when v_paid then 'pg_refund_after_payout' else 'partial_refund_allocation_unresolved' end)
  on conflict(billing_event_id) do update set state=excluded.state,reason=excluded.reason,updated_at=now();
 else delete from public.service_period_financial_holds where billing_event_id=e.id and state='hold'; end if;
 update public.subscription_settlement_items set status=case when p_amount_cents=e.amount_cents then 'canceled' else 'hold' end,hold_reason='pg_refund_confirmed',updated_at=now() where billing_event_id=e.id and status<>'paid';
 return jsonb_build_object('ok',true,'idempotent',false,'refund_id',r.id,'adjustment_required',v_paid);
end $function$

CREATE OR REPLACE FUNCTION public.record_voucher_external_refund(p_billing_event_id uuid, p_external_refund_key text, p_amount_cents bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.subscription_billing_events%rowtype; v_existing public.voucher_external_refunds%rowtype; v_refund uuid; v_paid boolean; v_total bigint;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if;
 if p_external_refund_key is null or char_length(p_external_refund_key) not between 1 and 200 or p_amount_cents is null or p_amount_cents<=0 then raise exception 'INVALID_EXTERNAL_REFUND'; end if;
 perform core_private.lock_service_period_finance(p_billing_event_id);
 select * into e from public.subscription_billing_events where id=p_billing_event_id;
 if e.voucher_redemption_id is null then raise exception 'NOT_VOUCHER_PERIOD'; end if;
 select * into v_existing from public.voucher_external_refunds where external_refund_key=p_external_refund_key;
 if found then
  if v_existing.billing_event_id<>e.id or v_existing.amount_cents<>p_amount_cents then raise exception 'EXTERNAL_REFUND_REPLAY_CONFLICT'; end if;
  return jsonb_build_object('ok',true,'idempotent',true,'refund_id',v_existing.refund_id);
 end if;
 select coalesce(sum(amount_cents),0) into v_total from public.voucher_external_refunds where billing_event_id=e.id;
 if v_total+p_amount_cents>e.amount_cents then raise exception 'EXTERNAL_REFUND_AMOUNT_EXCEEDED'; end if;
 perform 1 from public.subscription_settlement_items where billing_event_id=e.id for update;
 select exists(select 1 from public.subscription_settlement_items where billing_event_id=e.id and status='paid') into v_paid;
 insert into public.refunds(user_id,subscription_id,billing_event_id,payment_id,amount_cents,status,request_type,reason)
 values(e.student_id,e.subscription_id,e.id,null,p_amount_cents,'pending','voucher_external','Confirmed external voucher refund') returning id into v_refund;
 insert into public.voucher_external_refunds(external_refund_key,billing_event_id,amount_cents,refund_id) values(p_external_refund_key,e.id,p_amount_cents,v_refund);
 update public.refunds set status='succeeded',processed_at=clock_timestamp() where id=v_refund;
 if v_total+p_amount_cents=e.amount_cents then
  update public.voucher_redemptions set status='refunded' where id=e.voucher_redemption_id;
  update public.refunds set status='canceled' where billing_event_id=e.id and status='pending' and id<>v_refund;
  delete from public.service_period_financial_holds where billing_event_id=e.id and state='hold';
 end if;
 if v_paid or v_total+p_amount_cents<e.amount_cents then
  insert into public.service_period_financial_holds(billing_event_id,state,reason)
  values(e.id,case when v_paid then 'adjustment_required' else 'hold' end,case when v_paid then 'external_refund_after_payout' else 'partial_refund_allocation_unresolved' end)
  on conflict(billing_event_id) do update set state=excluded.state,reason=excluded.reason,updated_at=now();
 end if;
 update public.subscription_settlement_items set status=case when v_total+p_amount_cents=e.amount_cents then 'canceled' else 'hold' end,
 hold_reason=case when v_total+p_amount_cents=e.amount_cents then 'refund_succeeded' else 'partial_refund_allocation_unresolved' end,updated_at=now()
 where billing_event_id=e.id and status<>'paid';
 return jsonb_build_object('ok',true,'idempotent',false,'refund_id',v_refund,'adjustment_required',v_paid);
end $function$

CREATE OR REPLACE FUNCTION public.redeem_voucher(p_student_id uuid, p_mentor_id uuid, p_code_hmac text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_e public.voucher_entitlements%ROWTYPE; v_c public.voucher_campaigns%ROWTYPE; v_s public.subscriptions%ROWTYPE;
 v_r public.voucher_redemptions%ROWTYPE; v_p public.mentor_plans%ROWTYPE; v_m public.mentor_profiles%ROWTYPE;
 v_u public.users%ROWTYPE; v_mentor_status text; v_constraint text; v_decided_at timestamptz; v_event uuid; v_room uuid; v_sub uuid;
BEGIN
 IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'VOUCHER_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_student_id IS NULL OR p_mentor_id IS NULL OR p_request_id IS NULL OR p_student_id=p_mentor_id OR p_code_hmac IS NULL OR p_code_hmac !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'VOUCHER_INPUT_INVALID'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(p_student_id::text),hashtext(p_mentor_id::text));
 SELECT * INTO v_e FROM public.voucher_entitlements WHERE code_hmac=p_code_hmac FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_UNAVAILABLE'); END IF;
 -- Request replay never restores mutable subscription or room references.
 SELECT * INTO v_r FROM public.voucher_redemptions WHERE student_id=p_student_id AND request_id=p_request_id;
 IF FOUND THEN
  IF v_r.entitlement_id<>v_e.id OR v_r.mentor_id<>p_mentor_id THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_REQUEST_CONFLICT'); END IF;
  SELECT id INTO v_event FROM public.subscription_billing_events WHERE voucher_redemption_id=v_r.id;
  IF v_event IS NULL THEN RAISE EXCEPTION 'VOUCHER_STATE_INCONSISTENT'; END IF;
  SELECT id INTO v_room FROM public.mentor_student_rooms WHERE student_id=p_student_id AND mentor_id=p_mentor_id;
  RETURN jsonb_build_object('ok',true,'idempotent',true,'subscription_id',v_r.subscription_id,'redemption_id',v_r.id,'billing_event_id',v_event,'room_id',v_room);
 END IF;
 IF v_e.status<>'issued' THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_UNAVAILABLE'); END IF;
 SELECT * INTO v_c FROM public.voucher_campaigns WHERE id=v_e.campaign_id FOR SHARE;
 SELECT * INTO v_s FROM public.subscriptions WHERE student_id=p_student_id AND mentor_id=p_mentor_id FOR UPDATE;
 SELECT * INTO v_m FROM public.mentor_profiles WHERE user_id=p_mentor_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_PARTY_UNAVAILABLE'); END IF;
 SELECT * INTO v_p FROM public.mentor_plans WHERE mentor_id=p_mentor_id AND plan_tier='standard' AND is_active FOR SHARE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_PLAN_UNAVAILABLE'); END IF;
 SELECT * INTO v_u FROM public.users WHERE id=p_student_id FOR UPDATE;
 IF NOT FOUND OR v_u.role<>'student' THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_PARTY_UNAVAILABLE'); END IF;
 SELECT status INTO v_mentor_status FROM public.users WHERE id=p_mentor_id FOR SHARE;
 SELECT * INTO v_m FROM public.mentor_profiles WHERE user_id=p_mentor_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_PARTY_UNAVAILABLE'); END IF;
 -- All approval locks acquired; exactly one wall-clock sample after waits.
 v_decided_at := clock_timestamp();
 IF v_c.status<>'active' OR v_decided_at<v_c.redeem_start OR v_decided_at>=v_c.redeem_end THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_WINDOW_CLOSED'); END IF;
 IF v_u.status<>'active' OR v_mentor_status IS DISTINCT FROM 'active' OR NOT v_m.is_open_for_subscriptions OR v_m.activity_status<>'active' OR NOT public.individual_question_user_is_approved_mentor(p_mentor_id) THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_PARTY_UNAVAILABLE'); END IF;
 IF v_s.id IS NOT NULL AND core_private.subscription_has_pending_refund(v_s.id) THEN RETURN jsonb_build_object('ok',false,'code','SERVICE_PERIOD_REFUND_PENDING'); END IF;
 IF v_s.current_service_period_event_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.subscription_billing_events WHERE id=v_s.current_service_period_event_id AND status='succeeded' AND core_private.service_period_effective_end(id)>v_decided_at) AND core_private.service_period_financial_state(v_s.current_service_period_event_id)<>'refunded' THEN RETURN jsonb_build_object('ok',false,'code','SERVICE_PERIOD_ACTIVE'); END IF;
 IF v_s.id IS NOT NULL AND (v_s.status IN ('active','past_due','cancel_scheduled') AND (v_s.current_period_end IS NULL OR v_s.current_period_end>v_decided_at)) THEN RETURN jsonb_build_object('ok',false,'code','SERVICE_PERIOD_ACTIVE'); END IF;
 IF public.mentor_cap_used(p_mentor_id) - (CASE WHEN v_s.status='active' THEN public.subscription_cap_weight(v_s.plan_tier) ELSE 0 END) + public.subscription_cap_weight('standard') > public.mentor_cap_limit(p_mentor_id) THEN RETURN jsonb_build_object('ok',false,'code','MENTOR_CAP_EXCEEDED'); END IF;
 -- Every write below belongs to this transaction; any exception rolls everything back.
 INSERT INTO public.subscriptions(student_id,mentor_id,plan_id,plan_tier,status,payment_id,last_payment_id,funding_source,started_at,current_period_start,current_period_end,next_billing_at,billing_cycle,cancel_at_period_end)
 VALUES(p_student_id,p_mentor_id,v_p.id,'standard','active',NULL,NULL,'voucher',v_decided_at,v_decided_at,v_c.service_end,NULL,'fixed',true)
 ON CONFLICT(student_id,mentor_id) DO UPDATE SET plan_id=excluded.plan_id,plan_tier='standard',status='active',payment_id=NULL,last_payment_id=NULL,funding_source='voucher',current_period_start=v_decided_at,current_period_end=v_c.service_end,next_billing_at=NULL,billing_cycle='fixed',cancel_at_period_end=true,cancel_requested_at=NULL,canceled_at=NULL,expired_at=NULL,grace_until=NULL
 RETURNING id INTO v_sub;
 INSERT INTO public.voucher_redemptions(entitlement_id,subscription_id,student_id,mentor_id,request_id,service_start,service_end,decided_at)
 VALUES(v_e.id,v_sub,p_student_id,p_mentor_id,p_request_id,v_decided_at,v_c.service_end,v_decided_at) RETURNING * INTO v_r;
 INSERT INTO public.subscription_billing_events(subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,amount_cents,plan_tier,plan_id,idempotency_key,processed_at,funding_source,voucher_redemption_id)
 VALUES(v_sub,p_student_id,p_mentor_id,'initial','succeeded',v_decided_at,v_c.service_end,v_decided_at,v_c.gross_cents,'standard',v_p.id,'voucher_initial:'||v_r.id::text,v_decided_at,'voucher',v_r.id) RETURNING id INTO v_event;
 UPDATE public.subscriptions SET current_service_period_event_id=v_event,last_billing_event_id=v_event WHERE id=v_sub;
 UPDATE public.voucher_entitlements SET status='redeemed' WHERE id=v_e.id;
 INSERT INTO public.mentor_student_rooms(student_id,mentor_id,subscription_id,payment_id)
 VALUES(p_student_id,p_mentor_id,v_sub,NULL) ON CONFLICT(student_id,mentor_id) DO UPDATE SET subscription_id=excluded.subscription_id,payment_id=NULL WHERE public.mentor_student_rooms.subscription_id IS NULL OR public.mentor_student_rooms.subscription_id=v_sub RETURNING id INTO v_room;
 IF v_room IS NULL THEN RAISE EXCEPTION 'VOUCHER_ROOM_CONFLICT'; END IF;
 RETURN jsonb_build_object('ok',true,'idempotent',false,'subscription_id',v_sub,'redemption_id',v_r.id,'billing_event_id',v_event,'room_id',v_room);
EXCEPTION WHEN unique_violation THEN
 GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
 IF v_constraint='voucher_redemptions_student_id_request_id_key' THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_REQUEST_CONFLICT'); END IF;
 RAISE;
END $function$

CREATE OR REPLACE FUNCTION public.refund_individual_question(p_question_id uuid)
 RETURNS individual_question_escrow_result
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_owner uuid;
  v_status text;
  v_refund_ledger uuid;
  v_res public.individual_question_escrow_result;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;
  if p_question_id is null then
    raise exception 'INVALID_INPUT: question_id is required' using errcode = '22023';
  end if;

  select q.student_id, q.status, q.refund_ledger_id
    into v_owner, v_status, v_refund_ledger
  from public.individual_questions q
  where q.id = p_question_id
  for update;

  if not found or v_owner is distinct from v_uid then
    raise exception 'NOT_QUESTION_OWNER' using errcode = '42501';
  end if;

  if v_status = 'refunded' or v_refund_ledger is not null then
    return public.refund_individual_question_hold(p_question_id);
  end if;

  if v_status not in ('escrowed', 'open', 'assigned', 'claimed') then
    raise exception 'REFUND_NOT_ALLOWED: status=%', v_status using errcode = 'P0001';
  end if;

  v_res := public.refund_individual_question_hold(p_question_id);
  if not v_res.ok then
    raise exception 'INDIVIDUAL_QUESTION_REFUND_FAILED:%:%', v_res.code, v_res.message
      using errcode = 'P0001';
  end if;
  return v_res;
end;
$function$

CREATE OR REPLACE FUNCTION public.refund_individual_question_hold(p_question_id uuid)
 RETURNS individual_question_escrow_result
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_question public.individual_questions%rowtype;
  v_ledger_id uuid;
  v_wallet_balance bigint;
  v_new_ledger boolean := false;
begin
  if p_question_id is null then
    return (false, 'invalid_question', 'question_id is required', null, null, null, null)::public.individual_question_escrow_result;
  end if;

  select *
    into v_question
  from public.individual_questions
  where id = p_question_id
  for update;

  if not found then
    return (false, 'not_found', 'individual question not found', p_question_id, null, null, null)::public.individual_question_escrow_result;
  end if;

  if v_question.refund_ledger_id is not null or v_question.status = 'refunded' then
    return (true, 'already_refunded', 'individual question already refunded', v_question.id, v_question.status, v_question.refund_ledger_id, null)::public.individual_question_escrow_result;
  end if;

  if v_question.release_ledger_id is not null or v_question.status = 'released' then
    return (false, 'already_released', 'individual question already released', v_question.id, v_question.status, v_question.release_ledger_id, null)::public.individual_question_escrow_result;
  end if;

  if v_question.hold_ledger_id is null then
    return (false, 'hold_missing', 'escrow hold ledger is missing', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;
  end if;

  if exists (
    select 1
    from public.cash_ledger l
    where l.idempotency_key = 'iq_payout:' || v_question.id::text
      and l.reason = 'individual_question_payout'
  ) then
    return (false, 'already_released', 'payout ledger already exists', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;
  end if;

  insert into public.cash_ledger (
    user_id,
    delta_cents,
    reason,
    ref_type,
    ref_id,
    idempotency_key
  )
  values (
    v_question.student_id,
    v_question.price_cents,
    'individual_question_refund',
    'individual_questions',
    v_question.id,
    'iq_refund:' || v_question.id::text
  )
  on conflict (idempotency_key) do nothing
  returning id into v_ledger_id;

  if v_ledger_id is not null then
    v_new_ledger := true;
  else
    select id
      into v_ledger_id
    from public.cash_ledger
    where idempotency_key = 'iq_refund:' || v_question.id::text
      and reason = 'individual_question_refund';
  end if;

  if v_ledger_id is null then
    raise exception 'INDIVIDUAL_QUESTION_REFUND_LEDGER_MISSING';
  end if;

  if v_new_ledger then
    insert into public.cash_wallets (user_id, balance_cents)
    values (v_question.student_id, 0)
    on conflict (user_id) do nothing;

    update public.cash_wallets
    set balance_cents = balance_cents + v_question.price_cents
    where user_id = v_question.student_id
    returning balance_cents into v_wallet_balance;

    if not found then
      raise exception 'INDIVIDUAL_QUESTION_STUDENT_WALLET_REFUND_FAILED';
    end if;
  end if;

  update public.individual_questions
  set
    status = 'refunded',
    refunded_at = coalesce(refunded_at, now()),
    refund_ledger_id = v_ledger_id
  where id = v_question.id
  returning * into v_question;

  return (true, 'refunded', 'individual question escrow refunded', v_question.id, v_question.status, v_ledger_id, v_wallet_balance)::public.individual_question_escrow_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_device_token(p_token text, p_platform text DEFAULT 'unknown'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_id uuid; v_plat text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_token is null or btrim(p_token)='' then raise exception 'TOKEN_REQUIRED'; end if;
  v_plat := case when p_platform in ('ios','android','web') then p_platform else 'unknown' end;
  insert into public.device_tokens (user_id, token, platform)
    values (v_uid, btrim(p_token), v_plat)
  on conflict (token) do update set user_id = v_uid, platform = v_plat, revoked_at = null, updated_at = now()
  returning id into v_id;
  return jsonb_build_object('ok', true, 'device_token_id', v_id);
end $function$

CREATE OR REPLACE FUNCTION public.reject_refund_request_admin(p_refund_id uuid, p_admin_id uuid, p_admin_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.refunds%rowtype;
  v_admin_ok boolean;
begin
  if p_refund_id is null then
    return jsonb_build_object('ok', false, 'message', '환불 ID가 필요합니다.');
  end if;
  if p_admin_id is null then
    return jsonb_build_object('ok', false, 'message', '관리자 ID가 필요합니다.');
  end if;

  select exists(
    select 1 from public.users u where u.id = p_admin_id and u.role = 'admin'
  ) into v_admin_ok;
  if not coalesce(v_admin_ok, false) then
    raise exception 'ADMIN_REQUIRED';
  end if;

  select * into r from public.refunds where id = p_refund_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'message', '환불 요청을 찾을 수 없습니다.');
  end if;

  if r.status is distinct from 'pending' then
    return jsonb_build_object(
      'ok', true,
      'noop', true,
      'refund_id', p_refund_id,
      'message', '이미 처리되었거나 대기 상태가 아닙니다.',
      'status', r.status
    );
  end if;

  update public.refunds
  set
    status = 'rejected',
    processed_at = now(),
    processed_by = p_admin_id,
    admin_note = p_admin_note,
    updated_at = now()
  where id = r.id;

  return jsonb_build_object(
    'ok', true,
    'noop', false,
    'refund_id', r.id,
    'message', '환불이 거절되었습니다.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.release_individual_question(p_question_id uuid)
 RETURNS individual_question_escrow_result
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_res public.individual_question_escrow_result;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  if p_question_id is null then
    raise exception 'INVALID_INPUT: question_id is required' using errcode = '22023';
  end if;

  -- 본인 한정: only the owning student may release/settle their question.
  if not exists (
    select 1
    from public.individual_questions q
    where q.id = p_question_id
      and q.student_id = v_uid
  ) then
    raise exception 'NOT_QUESTION_OWNER' using errcode = '42501';
  end if;

  v_res := public.release_individual_question_payout(p_question_id);

  if not v_res.ok then
    raise exception 'INDIVIDUAL_QUESTION_RELEASE_FAILED:%:%', v_res.code, v_res.message
      using errcode = 'P0001';
  end if;

  return v_res;
end;
$function$

CREATE OR REPLACE FUNCTION public.release_individual_question_payout(p_question_id uuid)
 RETURNS individual_question_escrow_result
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_question public.individual_questions%rowtype;
  v_mentor_id uuid;
  v_ledger_id uuid;
  v_wallet_balance bigint;
  v_new_ledger boolean := false;
  v_mentor_cents bigint;  -- 255: 멘토 지급 = floor(price_cents * 0.85), 플랫폼 15% 차액 implicit
begin
  if p_question_id is null then
    return (false, 'invalid_question', 'question_id is required', null, null, null, null)::public.individual_question_escrow_result;
  end if;

  select *
    into v_question
  from public.individual_questions
  where id = p_question_id
  for update;

  if not found then
    return (false, 'not_found', 'individual question not found', p_question_id, null, null, null)::public.individual_question_escrow_result;
  end if;

  if v_question.release_ledger_id is not null or v_question.status = 'released' then
    return (true, 'already_released', 'individual question already released', v_question.id, v_question.status, v_question.release_ledger_id, null)::public.individual_question_escrow_result;
  end if;

  if v_question.refund_ledger_id is not null or v_question.status = 'refunded' then
    return (false, 'already_refunded', 'individual question already refunded', v_question.id, v_question.status, v_question.refund_ledger_id, null)::public.individual_question_escrow_result;
  end if;

  if v_question.status <> 'answered' then
    return (false, 'not_answered', 'question must be answered before payout', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;
  end if;

  if v_question.hold_ledger_id is null then
    return (false, 'hold_missing', 'escrow hold ledger is missing', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;
  end if;

  v_mentor_id := coalesce(v_question.claimed_mentor_id, v_question.designated_mentor_id);
  if v_mentor_id is null then
    return (false, 'mentor_missing', 'mentor is missing', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;
  end if;

  if exists (
    select 1
    from public.cash_ledger l
    where l.idempotency_key = 'iq_refund:' || v_question.id::text
      and l.reason = 'individual_question_refund'
  ) then
    return (false, 'already_refunded', 'refund ledger already exists', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;
  end if;

  -- 멘토 몫 85% (플랫폼 15%는 price_cents - v_mentor_cents = hold 차액으로 남김)
  v_mentor_cents := floor(v_question.price_cents::numeric * 0.85)::bigint;
  if v_mentor_cents <= 0 then
    return (false, 'invalid_payout', 'mentor payout amount must be positive', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;
  end if;

  insert into public.cash_ledger (
    user_id,
    delta_cents,
    reason,
    ref_type,
    ref_id,
    idempotency_key
  )
  values (
    v_mentor_id,
    v_mentor_cents,
    'individual_question_payout',
    'individual_questions',
    v_question.id,
    'iq_payout:' || v_question.id::text
  )
  on conflict (idempotency_key) do nothing
  returning id into v_ledger_id;

  if v_ledger_id is not null then
    v_new_ledger := true;
  else
    select id
      into v_ledger_id
    from public.cash_ledger
    where idempotency_key = 'iq_payout:' || v_question.id::text
      and reason = 'individual_question_payout';
  end if;

  if v_ledger_id is null then
    raise exception 'INDIVIDUAL_QUESTION_PAYOUT_LEDGER_MISSING';
  end if;

  if v_new_ledger then
    insert into public.cash_wallets (user_id, balance_cents)
    values (v_mentor_id, 0)
    on conflict (user_id) do nothing;

    update public.cash_wallets
    set balance_cents = balance_cents + v_mentor_cents
    where user_id = v_mentor_id
    returning balance_cents into v_wallet_balance;

    if not found then
      raise exception 'INDIVIDUAL_QUESTION_MENTOR_WALLET_CREDIT_FAILED';
    end if;
  end if;

  update public.individual_questions
  set
    status = 'released',
    released_at = coalesce(released_at, now()),
    release_ledger_id = v_ledger_id
  where id = v_question.id
  returning * into v_question;

  return (true, 'released', 'individual question payout released', v_question.id, v_question.status, v_ledger_id, v_wallet_balance)::public.individual_question_escrow_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.reviews_enforce_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_is_admin boolean := coalesce((select public.is_admin()), false);
  v_is_author boolean;
begin
  -- service_role: 시스템 경로 통과 (126 동작 그대로 보존)
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;

  -- 관리자가 우연히 작성자이기도 한 경우에는 **관리자 의미론을 우선**한다
  -- (권한이 늘어나지 않는 보수적 방향 — 관리자 분기는 rating·body 를 못 바꾼다).
  v_is_author := (not v_is_admin) and v_uid is not null and v_uid = old.author_id;

  -- 공통 불변 보호 필드 (모든 비-service 액터)
  -- 126:87-96 과 동일하되 rating·body 는 아래에서 액터 조건부로 판정한다.
  if new.id is distinct from old.id
     or new.mentor_id is distinct from old.mentor_id
     or new.author_id is distinct from old.author_id
     or new.subscription_count is distinct from old.subscription_count
     or new.created_at is distinct from old.created_at then
    raise exception 'reviews: protected columns are immutable';
  end if;

  -- rating·body 는 **작성자만** 변경 가능. 멘토·관리자에게는 종전대로 불변.
  if not v_is_author then
    if new.rating is distinct from old.rating
       or new.body is distinct from old.body then
      raise exception 'reviews: protected columns are immutable';
    end if;
  end if;

  -- 관리자: is_hidden/is_blinded/moderation_state 만. moderated_* 서버 강제.
  if v_is_admin then
    if new.mentor_reply is distinct from old.mentor_reply
       or new.mentor_replied_at is distinct from old.mentor_replied_at then
      raise exception 'reviews: admin must not change mentor reply fields';
    end if;
    new.moderated_at := now();
    new.moderated_by := v_uid;
    -- 조정은 "작성자가 마지막으로 수정한 시각"을 건드리지 않는다.
    new.updated_at := old.updated_at;
    return new;
  end if;

  -- 작성자(학생): rating·body 만. 조정·멘토답글 필드 7종 전량 차단. updated_at 서버 강제.
  if v_is_author then
    -- ★ 173: 모더레이션된 리뷰는 작성자가 수정할 수 없다.
    --   이 가드는 **작성자 분기 안에서만** 동작한다 — 관리자의 숨김 해제와
    --   멘토의 답글은 종전대로 조정된 행에도 적용되어야 하기 때문이다.
    if coalesce(old.is_hidden, false) or coalesce(old.is_blinded, false) then
      raise exception 'reviews: moderated review is not editable by author';
    end if;
    if new.is_hidden is distinct from old.is_hidden
       or new.is_blinded is distinct from old.is_blinded
       or new.moderation_state is distinct from old.moderation_state
       or new.moderated_at is distinct from old.moderated_at
       or new.moderated_by is distinct from old.moderated_by
       or new.mentor_reply is distinct from old.mentor_reply
       or new.mentor_replied_at is distinct from old.mentor_replied_at then
      raise exception 'reviews: author must not change moderation or mentor reply fields';
    end if;
    new.updated_at := now();   -- 클라이언트 값 무시
    return new;
  end if;

  -- 멘토(본인 리뷰): mentor_reply 만, 1회. moderation 필드 변경 금지. replied_at 서버 강제.
  if v_uid is not null and v_uid = old.mentor_id then
    if new.is_hidden is distinct from old.is_hidden
       or new.is_blinded is distinct from old.is_blinded
       or new.moderation_state is distinct from old.moderation_state
       or new.moderated_at is distinct from old.moderated_at
       or new.moderated_by is distinct from old.moderated_by then
      raise exception 'reviews: mentor must not change moderation fields';
    end if;
    if old.mentor_reply is not null and new.mentor_reply is distinct from old.mentor_reply then
      raise exception 'reviews: mentor reply already set (one-time only)';
    end if;
    if new.mentor_reply is distinct from old.mentor_reply
      then new.mentor_replied_at := now(); else new.mentor_replied_at := old.mentor_replied_at; end if;
    -- 멘토 답글은 학생 수정 시각을 건드리지 않는다.
    new.updated_at := old.updated_at;
    return new;
  end if;

  -- 그 외: 수정 불가
  raise exception 'reviews: not permitted to update this review';
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.run_scheduled_payout(p_run_date date, p_force_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_enabled boolean; v_dry boolean; v_res record;
begin
  select scheduler_enabled into v_enabled from public.payout_settings where id = 1;
  v_enabled := coalesce(v_enabled, false);
  v_dry := (not v_enabled) or coalesce(p_force_dry_run, false);
  select * into v_res from public.pay_due_payouts_for_run(p_run_date, null, v_dry);
  return jsonb_build_object(
    'ok', true, 'scheduler_enabled', v_enabled, 'dry_run', v_res.dry_run,
    'run_id', v_res.run_id, 'paid_count', v_res.paid_count, 'skipped_no_account', v_res.skipped_no_account,
    'total_mentor_cents', v_res.total_mentor_cents, 'total_withholding_cents', v_res.total_withholding_cents,
    'total_net_cents', v_res.total_net_cents);
end $function$

