CREATE OR REPLACE FUNCTION public.shortform_posts_protected_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  -- SECURITY INVOKER 필수 — current_user 게이트가 실제 클라이언트 역할을 봐야 한다.
  if current_user not in ('anon','authenticated') then
    return new;
  end if;
  if coalesce((select public.is_admin()), false) then
    return new;
  end if;
  if new.id                   is distinct from old.id
     or new.author_id            is distinct from old.author_id
     or new.creator_id           is distinct from old.creator_id
     or new.author_role          is distinct from old.author_role
     or new.author_label         is distinct from old.author_label
     or new.source               is distinct from old.source
     or new.created_at           is distinct from old.created_at
     or new.view_count           is distinct from old.view_count
     or new.like_count           is distinct from old.like_count
     or new.create_idempotency_key is distinct from old.create_idempotency_key then
    raise exception 'SHORTFORM_PROTECTED_COLUMNS' using errcode = '42501';
  end if;
  if new.status is distinct from old.status then
    if not (old.status in ('draft','published') and new.status in ('draft','published')) then
      raise exception 'SHORTFORM_STATUS_TRANSITION_FORBIDDEN' using errcode = '42501';
    end if;
  end if;
  -- 194: deleted_by = auth.uid() 만 · 복원은 관리자만 · deleted_by 단독 변경 금지(RLS 가 작성자 직접 soft delete 를 먼저 거부하므로 심층 방어)
  if new.deleted_at is distinct from old.deleted_at then
    if new.deleted_at is null then
      raise exception 'SHORTFORM_RESTORE_ADMIN_ONLY' using errcode = '42501';
    end if;
    if new.deleted_by is distinct from (select auth.uid()) then
      raise exception 'SHORTFORM_DELETED_BY_MISMATCH' using errcode = '42501';
    end if;
  elsif new.deleted_by is distinct from old.deleted_by then
    raise exception 'SHORTFORM_PROTECTED_COLUMNS' using errcode = '42501';
  end if;
  new.updated_at := now();
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.shortform_view_record_v2(p_post_id uuid, p_event_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_inserted boolean := false;
begin
  if p_post_id is null or p_event_key is null then
    raise exception 'INVALID_INPUT' using errcode = '22023';
  end if;
  -- 게시 상태 공개 글만 계수(194: 삭제된 글 제외)
  if not exists (select 1 from public.shortform_posts sp
                  where sp.id = p_post_id and sp.status = 'published' and sp.deleted_at is null) then
    raise exception 'POST_NOT_FOUND' using errcode = 'P0001';
  end if;

  insert into public.shortform_view_events (post_id, event_key, viewer_user_id)
  values (p_post_id, p_event_key, v_uid)
  on conflict (post_id, event_key) do nothing;
  v_inserted := found;

  if v_inserted then
    update public.shortform_posts
       set view_count = view_count + 1
     where id = p_post_id;
  end if;

  -- 중복 key 는 idempotent success (계수 증가 없음)
  return jsonb_build_object('ok', true, 'contract_version', 1, 'incremented', v_inserted);
end
$function$

CREATE OR REPLACE FUNCTION public.soft_delete_own_content(p_kind text, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_author uuid;
  v_creator uuid;
  v_deleted_at timestamptz;
  v_hidden boolean;
  v_post_type text;
  v_status text;
  v_susp timestamptz;
  v_norm text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;
  if p_id is null or p_kind is null or p_kind not in ('shortform', 'shortform_comment', 'board_comment', 'board_post') then
    raise exception 'INVALID_KIND' using errcode = '22023';
  end if;

  -- 대상 행 잠금 + 작성자 · 삭제 · 숨김(moderation) 상태
  if p_kind = 'shortform' then
    select sp.author_id, sp.creator_id, sp.deleted_at, (sp.status = 'hidden')
      into v_author, v_creator, v_deleted_at, v_hidden
      from public.shortform_posts sp where sp.id = p_id for update;
  elsif p_kind = 'shortform_comment' then
    select cc.author_id, null::uuid, cc.deleted_at, (cc.status <> 'visible'), cc.post_type
      into v_author, v_creator, v_deleted_at, v_hidden, v_post_type
      from public.community_comments cc where cc.id = p_id for update;
  elsif p_kind = 'board_comment' then
    select c.author_id, null::uuid, c.deleted_at, (c.is_deleted and c.deleted_at is null)
      into v_author, v_creator, v_deleted_at, v_hidden
      from public.comments c where c.id = p_id for update;
  else
    select cp.author_id, null::uuid, cp.deleted_at, (cp.status = 'hidden')
      into v_author, v_creator, v_deleted_at, v_hidden
      from public.community_posts cp where cp.id = p_id for update;
  end if;
  if not found then
    raise exception 'CONTENT_NOT_FOUND' using errcode = 'P0001';
  end if;
  if p_kind = 'shortform_comment' and v_post_type is distinct from 'shortform' then
    raise exception 'CONTENT_KIND_MISMATCH' using errcode = '22023';
  end if;
  -- 본인 판정 — 숏폼은 author_id 또는 creator_id(sf_update_own · sf_delete_own 과 같다) · 나머지는 author_id
  if v_author is distinct from v_uid and v_creator is distinct from v_uid then
    raise exception 'CONTENT_NOT_OWNED' using errcode = '42501';
  end if;

  -- 계정 게이트 (community_comment_soft_delete_self 와 동일: banned · 유효 suspended · unknown/deleted · 삭제 진행 차단)
  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = v_uid;
  if not found then raise exception 'ACCOUNT_NOT_ACTIVE'; end if;
  v_norm := lower(btrim(coalesce(v_status, '')));
  if v_norm = 'banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if v_norm = 'suspended' and (v_susp is null or v_susp > now()) then raise exception 'ACCOUNT_SUSPENDED'; end if;
  if v_norm not in ('active', 'suspended') then raise exception 'ACCOUNT_NOT_ACTIVE'; end if;
  if public.account_deletion_write_blocked(v_uid) then raise exception 'ACCOUNT_DELETION_IN_PROGRESS'; end if;

  -- 멱등: 이미 삭제된 행은 그대로 둔다(누가 지웠든)
  if v_deleted_at is not null then
    return;
  end if;
  -- 관리자가 숨긴 행은 본인이 삭제로 덮지 못한다(moderation 유지)
  if coalesce(v_hidden, false) then
    raise exception 'CONTENT_MODERATED' using errcode = '42501';
  end if;

  if p_kind = 'shortform' then
    update public.shortform_posts set deleted_at = now(), deleted_by = v_uid where id = p_id;
  elsif p_kind = 'shortform_comment' then
    update public.community_comments set deleted_at = now(), deleted_by = v_uid where id = p_id;
  elsif p_kind = 'board_comment' then
    -- is_deleted 는 comments_sync_deleted_flag(194)가 true 로 · 레거시 미러 · 댓글 수 재계산은 기존 트리거
    update public.comments set deleted_at = now(), deleted_by = v_uid where id = p_id;
  else
    update public.community_posts set deleted_at = now(), deleted_by = v_uid where id = p_id;
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.trg_block_settlement_on_active_dispute()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_cnt integer;
begin
  if new.custom_request_order_id is null then
    return new;
  end if;

  select count(*)::integer
    into v_cnt
  from public.disputes d
  where d.custom_request_order_id = new.custom_request_order_id
    and d.status in ('open', 'under_review', 'escalated');

  if v_cnt > 0 then
    raise exception 'settlement insert blocked: active dispute for order %', new.custom_request_order_id
      using errcode = 'P0001',
            hint = '진행 중인 분쟁이 있으면 정산 예정을 추가할 수 없습니다.';
  end if;

  return new;
end;
$function$

